function pick<T>(rng: () => number, list: readonly T[]): T {
  return list[Math.floor(rng() * list.length)]!;
}

export function buildContent(rng: () => number, i: number): string {
  const n = pick(rng, NOUNS);
  const v = pick(rng, VERBS);
  const c1 = pick(rng, CONCEPTS);
  const c2 = pick(rng, CONCEPTS);
  const k = Math.floor(rng() * 9999);
  return `seed-${i} the ${n} ${v} ${c1} under ${c2} pressure (k=${k})`;
}

export interface ToolCapture {
  index: number;
  toolName: string;
  toolInput: Record<string, unknown>;
  toolOutput: string;
  headMarker: string;
  tailMarker: string;
}

const TOOLS = ["Bash", "Read", "Edit", "Grep"] as const;

export function buildToolCapture(
  rng: () => number,
  i: number,
  outputBytes: number,
): ToolCapture {
  const toolName = pick(rng, TOOLS);
  const headMarker = `capmark${i}head`;
  const tailMarker = `capmark${i}tail`;
  const file = `src/${pick(rng, NOUNS)}/${pick(rng, NOUNS)}-${i}.ts`;
  const toolInput: Record<string, unknown> =
    toolName === "Bash"
      ? { command: `npm test -- ${pick(rng, NOUNS)} --shard=${i}` }
      : toolName === "Grep"
        ? { pattern: pick(rng, CONCEPTS), path: `src/${pick(rng, NOUNS)}-${i}` }
        : { file_path: file };
  const lines: string[] = [`${headMarker} ${buildContent(rng, i)}`];
  let size = lines[0]!.length;
  while (size < outputBytes - tailMarker.length - 1) {
    const line = buildContent(rng, i);
    lines.push(line);
    size += line.length + 1;
  }
  lines.push(tailMarker);
  return {
    index: i,
    toolName,
    toolInput,
    toolOutput: lines.join("\n"),
    headMarker,
    tailMarker,
  };
}

/**
 * Nearest-rank percentile over a pre-sorted ascending array of numbers.
 *
 * No dependencies, no allocation. The caller is responsible for sorting
 * the input ascending (`arr.sort((a, b) => a - b)`) — sorting in here
 * would hide an O(n log n) cost in what looks like a cheap lookup.
 *
 * @param sorted Ascending-sorted samples. Empty array returns `NaN`.
 * @param p Percentile in [0, 100]. Values outside the range are clamped.
 * @returns The sample at the nearest rank, or `NaN` for empty input.
 */
export function pXX(sorted: number[], p: number): number {
  const n = sorted.length;
  if (n === 0) return NaN;
  const clamped = Math.max(0, Math.min(100, p));
  if (clamped === 0) return sorted[0]!;
  if (clamped === 100) return sorted[n - 1]!;
  // Nearest-rank: rank = ceil(p/100 * n), index = rank - 1.
  const rank = Math.ceil((clamped / 100) * n);
  const idx = Math.min(n - 1, Math.max(0, rank - 1));
  return sorted[idx]!;
}

