import {
  buildMergedHooks,
  findPluginRoot,
  type HookManifest,
} from "../src/cli/connect/codex-hooks.js";

const PLUGIN_ROOT = resolve(__dirname, "..", "plugin");

const DEVIN_EVENTS = [
  "SessionStart",
  "UserPromptSubmit",
  "PreToolUse",
  "PostToolUse",
  "Stop",
  "SessionEnd",
];

const DEVIN_TOOL_NAMES = [
  "exec",
  "edit",
  "write",
  "read",
  "apply_patch",
  "grep",
  "glob",
];

function runHook(
  script: string,
  payload: Record<string, unknown>,
  env: Record<string, string> = {},
): Promise<string> {
  return new Promise((resolve_) => {
    const child = spawn("node", [`plugin/scripts/${script}.mjs`], {
      env: { ...process.env, AGENTMEMORY_URL: "http://127.0.0.1:1", ...env },
    });
    let out = "";
    child.stdout.on("data", (c) => (out += c));
    child.on("exit", () => resolve_(out));
    child.stdin.write(JSON.stringify(payload));
    child.stdin.end();
  });
}

