function gateFirstLessonList(kv: { list: (scope: string) => Promise<unknown[]> }) {
  const origList = kv.list.bind(kv);
  let release!: () => void;
  const gate = new Promise<void>((r) => {
    release = r;
  });
  let gated = true;
  kv.list = async (scope: string) => {
    if (scope === "mem:lessons" && gated) {
      gated = false;
      await gate;
    }
    return origList(scope);
  };
  return release;
}

