    seedSessions(kv, 3, 10);
    kv.seed(KV.memories, "m_big", { id: "m_big", content: "z".repeat(SAFE_PAYLOAD_BYTES + 1024) });
    kv.seed(KV.graphNodes, "n_1", { id: "n_1" });

