import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { homedir } from "node:os";
import { join } from "node:path";
import { loadClaudeBridgeConfig } from "../src/config.js";

// bridge path must match Claude Code's slug convention exactly:
//   ~/.claude/projects/<slug>/memory/MEMORY.md
// where <slug> replaces every / and \ with - and KEEPS any leading -.
// The memory/ subdirectory holds MEMORY.md (the index) plus per-topic
// .md files — this is where Claude Code 2.x actually reads/writes.
describe("loadClaudeBridgeConfig path", () => {
  const ORIG_ENV = { ...process.env };
  beforeEach(() => {
    delete process.env["CLAUDE_MEMORY_BRIDGE"];
    delete process.env["CLAUDE_PROJECT_PATH"];
    delete process.env["CLAUDE_MEMORY_LINE_BUDGET"];
  });
  afterEach(() => {
    process.env = { ...ORIG_ENV };
  });

  it("preserves leading - on POSIX absolute paths", () => {
    process.env["CLAUDE_MEMORY_BRIDGE"] = "true";
    process.env["CLAUDE_PROJECT_PATH"] = "/home/user/repos/my-project";
    const cfg = loadClaudeBridgeConfig();
    expect(cfg.memoryFilePath).toBe(
      join(homedir(), ".claude", "projects", "-home-user-repos-my-project", "memory", "MEMORY.md"),
    );
  });

  it("writes MEMORY.md inside the memory/ subdir under the slug dir", () => {
    process.env["CLAUDE_MEMORY_BRIDGE"] = "true";
    process.env["CLAUDE_PROJECT_PATH"] = "/Users/x/agentmemory";
    const cfg = loadClaudeBridgeConfig();
    expect(cfg.memoryFilePath).toMatch(/-Users-x-agentmemory[/\\]memory[/\\]MEMORY\.md$/);
  });

  it("returns empty memoryFilePath when bridge disabled", () => {
    const cfg = loadClaudeBridgeConfig();
    expect(cfg.enabled).toBe(false);
    expect(cfg.memoryFilePath).toBe("");
  });

  it("returns empty memoryFilePath when project path unset", () => {
    process.env["CLAUDE_MEMORY_BRIDGE"] = "true";
    const cfg = loadClaudeBridgeConfig();
    expect(cfg.enabled).toBe(true);
    expect(cfg.memoryFilePath).toBe("");
  });

  it("handles Windows-style backslash paths by swapping to -", () => {
    process.env["CLAUDE_MEMORY_BRIDGE"] = "true";
    process.env["CLAUDE_PROJECT_PATH"] = "C:\\Users\\x\\project";
    const cfg = loadClaudeBridgeConfig();
    expect(cfg.memoryFilePath).toMatch(/C:-Users-x-project[/\\]memory[/\\]MEMORY\.md$/);
  });
});

import { describe, it, expect } from "vitest";
import { HybridSearch } from "../src/state/hybrid-search.js";
import { SearchIndex } from "../src/state/search-index.js";
import { VectorIndex } from "../src/state/vector-index.js";
import type { CompressedObservation } from "../src/types.js";

// Graph retrieval lists every node and edge on each search. A graph weight
// of 0 multiplied its results by zero but still paid for both traversals,
// so AGENTMEMORY_GRAPH_WEIGHT=0 saved nothing. At weight 0 the graph must
// not be read at all.

const obs: CompressedObservation = {
  id: "obs_1",
  sessionId: "ses_1",
  timestamp: new Date().toISOString(),
  type: "file_edit",
  title: "Edit auth middleware",
  subtitle: "JWT validation",
  facts: ["Added token check"],
  narrative:
    "Modified the AuthMiddleware in src/middleware/auth.ts to validate JWT tokens",
  concepts: ["authentication", "jwt"],
  files: ["src/middleware/auth.ts"],
  importance: 7,
};

function mockKV() {
  const store = new Map<string, Map<string, unknown>>();
  const listed: string[] = [];
  return {
    listed,
    get: async <T>(scope: string, key: string): Promise<T | null> =>
      (store.get(scope)?.get(key) as T) ?? null,
    set: async <T>(scope: string, key: string, data: T): Promise<T> => {
      if (!store.has(scope)) store.set(scope, new Map());
      store.get(scope)!.set(key, data);
      return data;
    },
    delete: async (scope: string, key: string): Promise<void> => {
      store.get(scope)?.delete(key);
    },
    list: async <T>(scope: string): Promise<T[]> => {
      listed.push(scope);
      const entries = store.get(scope);
      return entries ? (Array.from(entries.values()) as T[]) : [];
    },
  };
}

async function searchWith(graphWeight: number | undefined) {
  const bm25 = new SearchIndex();
  bm25.add(obs);
  const kv = mockKV();
  await kv.set("mem:obs:ses_1", "obs_1", obs);
  const hybrid =
    graphWeight === undefined
      ? new HybridSearch(bm25, null, null, kv as never)
      : new HybridSearch(bm25, null, null, kv as never, 0.4, 0.6, graphWeight);
  const results = await hybrid.search(
    "AuthMiddleware src/middleware/auth.ts JWT",
    10,
  );
  return {
    results,
    graphLists: kv.listed.filter((s) => s.startsWith("mem:graph:")),
  };
}

describe("graph weight 0 skips graph retrieval", () => {
  it("control: the default weight reads the graph", async () => {
    const { graphLists } = await searchWith(undefined);
    expect(graphLists.length).toBeGreaterThan(0);
  });

  it("weight 0 never lists a graph scope", async () => {
    const { graphLists } = await searchWith(0);
    expect(graphLists).toEqual([]);
  });

  it("weight 0 still returns the BM25 result", async () => {
    const { results } = await searchWith(0);
    expect(
      results.map((r) => r.observation?.id ?? (r as { obsId?: string }).obsId),
    ).toContain("obs_1");
  });
});

describe("graph weight 0 also skips vector-chunk graph expansion", () => {
  // Lowercase query with no entity-like tokens, so only the expansion
  // traversal (driven by the top vector hits) can read the graph.
  const embedder = {
    name: "fake",
    dimensions: 3,
    embed: async () => new Float32Array([1, 0, 0]),
    embedBatch: async (t: string[]) => t.map(() => new Float32Array([1, 0, 0])),
  };

  async function vectorSearchWith(graphWeight: number) {
    const bm25 = new SearchIndex();
    bm25.add(obs);
    const vector = new VectorIndex();
    vector.add("obs_1", "ses_1", new Float32Array([1, 0, 0]));
    const kv = mockKV();
    await kv.set("mem:obs:ses_1", "obs_1", obs);
    const hybrid = new HybridSearch(
      bm25,
      vector,
      embedder as never,
      kv as never,
      0.4,
      0.6,
      graphWeight,
    );
    await hybrid.search("validate tokens", 10);
    return kv.listed.filter((sc) => sc.startsWith("mem:graph:"));
  }

  it("control: a positive weight expands through the graph", async () => {
    expect((await vectorSearchWith(0.3)).length).toBeGreaterThan(0);
  });

  it("weight 0 does not expand through the graph", async () => {
    expect(await vectorSearchWith(0)).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import {
  LIST_PAGE_MAX,
  decodeCursor,
  encodeCursor,
  matchesText,
  pageAfterCursor,
  pageByOffset,
  parseListQuery,
  sortByKeyDesc,
} from "../src/state/list-query.js";

type Row = { id: string; at: string };
const keyOf = (r: Row) => r.at;
const idOf = (r: Row) => r.id;

function rows(): Row[] {
  return sortByKeyDesc(
    [
      { id: "a", at: "2026-01-01" },
      { id: "b", at: "2026-01-03" },
      { id: "c", at: "2026-01-02" },
      { id: "d", at: "2026-01-03" },
      { id: "e", at: "2026-01-05" },
    ],
    keyOf,
    idOf,
  );
}

describe("list query helpers", () => {
  it("parses filters and clamps the page size", () => {
    const q = parseListQuery({ limit: "9999", project: " web ", type: "fact", q: "  ", cursor: "abc", status: "active" });
    expect(q).toEqual({ limit: LIST_PAGE_MAX, cursor: "abc", project: "web", type: "fact", status: "active", q: undefined });
    expect(parseListQuery({ limit: "0" }).limit).toBeUndefined();
    expect(parseListQuery({ limit: "abc" }).limit).toBeUndefined();
    expect(parseListQuery(undefined)).toEqual({});
  });

  it("sorts newest first with id as the tiebreak", () => {
    expect(rows().map((r) => r.id)).toEqual(["e", "d", "b", "c", "a"]);
  });

  it("walks every row exactly once across cursor pages", () => {
    const sorted = rows();
    const seen: string[] = [];
    let cursor: string | undefined;
    for (let i = 0; i < 10; i++) {
      const { page, nextCursor } = pageAfterCursor(sorted, keyOf, idOf, cursor, 2);
      seen.push(...page.map((r) => r.id));
      if (!nextCursor) break;
      cursor = nextCursor;
    }
    expect(seen).toEqual(["e", "d", "b", "c", "a"]);
  });

  it("keeps the next page stable when a newer row arrives between requests", () => {
    const first = pageAfterCursor(rows(), keyOf, idOf, undefined, 2);
    const grown = sortByKeyDesc([...rows(), { id: "z", at: "2026-02-01" }], keyOf, idOf);
    const second = pageAfterCursor(grown, keyOf, idOf, first.nextCursor ?? undefined, 2);
    expect(second.page.map((r) => r.id)).toEqual(["b", "c"]);
  });

  it("pages by offset for relevance-ordered results", () => {
    const ordered = ["x", "y", "z"];
    const first = pageByOffset(ordered, undefined, 2);
    expect(first.page).toEqual(["x", "y"]);
    const second = pageByOffset(ordered, first.nextCursor ?? undefined, 2);
    expect(second).toEqual({ page: ["z"], nextCursor: null });
  });

  it("ignores malformed cursors", () => {
    expect(decodeCursor("not-base64-json")).toBeNull();
    expect(decodeCursor(encodeCursor({ offset: -1 }))).toEqual({});
    expect(pageAfterCursor(rows(), keyOf, idOf, "garbage", 2).page.map((r) => r.id)).toEqual(["e", "d"]);
  });

  it("matches text case-insensitively across fields", () => {
    expect(matchesText("AUTH", "fix auth bug", undefined)).toBe(true);
    expect(matchesText("auth", null, "other")).toBe(false);
    expect(matchesText(undefined, "anything")).toBe(true);
  });
});

