    process.env["III_REST_PORT"] = "3211";
    const cfg = loadConfig();
    expect(cfg.restPort).toBe(3211);
    expect(cfg.streamsPort).toBe(3212);
    expect(cfg.viewerPort).toBe(3213);
    expect(cfg.engineUrl).toBe("ws://localhost:49234");
