interface Release {
  version: string;
  date: string;
  body: string;
}

function formatDate(d: string) {
  if (!d) return "";
  const date = new Date(`${d}T00:00:00Z`);
  return date.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" });
}

