  border: 1px solid color-mix(in srgb, var(--invert-ink) 30%, transparent);
  border-radius: var(--radius);
  font-family: var(--font-mono), monospace;
  font-size: 13px;
}

.single {
  max-width: 760px;
  margin: 0 auto;
}

.agents {
  display: grid;
  grid-template-colum

.section {
  border-top: 1px solid var(--line);
}

.row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.tile {
  display: grid;
  grid-template-rows: auto auto 1fr auto auto;
  gap: var(--s-3);
  padding: var(--s-7) var(--s-5);
  border-left: 1px dashed var(--line-2);
  min-width: 0;
}

.tile:first-child {
  border-left: 0;
  padding-left: 0;
}

.tile:last-child {
  padding-right: 0;
}

.tile h3 {
  font-size: var(--t-16);
  font-weight: 500;
  letter-spacing: 0;
  color: var(--ink);
}

.tile p {
  font-size: var(--t-14);
  color: var(--muted);
  line-height: 1.55;
  max-width: 34ch;
}

.tile :global(.src) {
  justify-self: start;
}

.art {
  display: grid;
  place-items: center;
  min-height: 230px;
  padding: var(--s-4) 0;
}

.gauge {
  width: 100%;
  max-width: 300px;
}

.track {
  fill: none;
  stroke: var(--line-2);
  stroke-width: 2;
}

.tick {
  stroke: var(--line-2);
  stroke-width: 1.2;
}

.fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 4;
  stroke-linecap: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.readout {
  font-family: var(--font-mono), monospace;
  font-size: 30px;
  fill: var(--ink);
  letter-spacing: -0.02em;
}

.scale {
  font-family: var(--font-mono), monospace;
  font-size: 14px;
  fill: var(--muted);
}

.call {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  font-size: var(--t-12);
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
}

.caret {
  display: inline-block;
  width: 7px;
  height: 14px;
  margin-left: 4px;
  background: var(--ink);
  animation: blink 1s steps(1) 3;
}

.iso {
  width: 100%;
  max-width: 300px;
}

.ghost {
  fill: none;
  stroke: var(--line-2);
  stroke-width: 1;
  stroke-dasharray: 4 4;
}

.drop {
  stroke: var(--line-2);
  stroke-dasharray: 2 4;
}

.faceT {
  fill: var(--accent);
  stroke: var(--ink);
  stroke-width: 1.2;
}

.faceL {
  fill: var(--ink);
  stroke: var(--ink);
}

.faceR {
  fill: var(--ink-2);
  stroke: var(--ink);
}

.float {
  transform: translateY(-6px);
}

:global(.is-in) .float {
  animation: float 900ms var(--ease-out) 300ms both;
}

.isoLabel {
  font-family: var(--font-mono), monospace;
  font-size: 14px;
  fill: var(--muted);
}

.ctx {
  width: 100%;
  max-width: 300px;
  border: 1px solid var(--ink-2);
  border-radius: var(--radius);
  background: var(--surface);
  padding: 10px;
  display: grid;
  gap: 8px;
}

.ctxHead {
  display: flex;
  justify-content: space-between;
  font-size: var(--t-12);
  color: var(--muted);
}

.ctxFull {
  color: var(--ink);
  opacity: 0;
}

.ctxMem {
  display: grid;
  gap: 2px;
  padding: 8px 10px;
  border-radius: 4px;
  background: var(--ink);
  color: var(--bg);
  font-size: var(--t-12);
}

.ctxTag {
  opacity: 0;
  color: var(--accent);
}

.ctxRows {
  position: relative;
  display: grid;
  gap: 6px;
  min-height: 132px;
  align-content: start;
}

.ctxRow {
  height: 10px;
  border-radius: 2px;
  background: var(--line-2);
  transform-origin: top left;
  opacity: 0;
}

.ctxSummary {
  position: absolute;
  left: 0;
  top: 0;
  padding: 4px 8px;
  border: 1px dashed var(--ink-2);
  border-radius: 4px;
  font-size: var(--t-12);
  color: var(--ink);
  opacity: 0;
}

:global(.is-in) .fill {
  animation: sweep 1200ms var(--ease-out) 300ms both;
}

:global(.is-in) .ctxRow {
  animation: rowIn 300ms var(--ease-out) var(--rd, 0ms) both, squash 520ms var(--ease-in-out) 1700ms forwards;
}

:global(.is-in) .ctxFull {
  animation: show 300ms var(--ease-out) 1150ms both, hide 300ms var(--ease-out) 1700ms forwards;
}

:global(.is-in) .ctxSummary {
  animation: show 400ms var(--ease-out) 1900ms both;
}

:global(.is-in) .ctxTag {
  animation: show 400ms var(--ease-out) 2200ms both;
}

:global(.is-in) .ctxMem {
  animation: nudge 520ms var(--ease-out) 2100ms both;
}

@keyframes sweep {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes rowIn {
  from {
    opacity: 0;
    transform: scaleX(0.4);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes squash {
  to {
    opacity: 0;
    transform: scaleY(0.2);
  }
}

@keyframes hide {
  to {
    opacity: 0;
  }
}

@keyframes nudge {
  0% {
    transform: none;
  }
  40% {
    transform: translateY(-3px);
  }
  100% {
    transform: none;
  }
}

@keyframes show {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes blink {
  50% {
    opacity: 0;
  }
}

@keyframes float {
  from {
    transform: translateY(22px);
    opacity: 0;
  }
  to {
    transform: translateY(-6px);
    opacity: 1;
  }
}

@media (max-width: 900px) {
  .row {
    grid-template-columns: minmax(0, 1fr);
  }
  .tile,
  .tile:first-child,
  .tile:last-child {
    padding: var(--s-6) 0;
    border-left: 0;
    border-top: 1px dashed var(--line-2);
  }
  .tile:first-child {
    border-top: 0;
  }
}

.section {
  padding-bottom: 0;
}

.track {
  position: relative;
  height: 520vh;
}

.sticky {
  position: sticky;
  top: 60px;
  height: calc(100vh - 60px);
  height: calc(100svh - 60px);
  display: flex;
  align-items: center;
  overflow: hidden;
}

.stage {
  display: grid;
  grid-template-columns: minmax(0, 0.78fr) minmax(0, 2fr);
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
}

.k {
  opacity: 0;
  will-change: opacity, transform;
}

.side {
  display: grid;
  gap: var(--s-5);
  align-content: center;
}

.steps {
  list-style: none;
  margin: 0;
  padding: 0 0 0 20px;
  display: grid;
  gap: var(--s-3);
  position: relative;
}

.step {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: var(--s-2);
  align-items: baseline;
  opacity: 0.32;
  transition: opacity var(--dur-3) var(--ease-out);
}

.step h3 {
  font-size: var(--t-20);
  letter-spacing: -0.01em;
}

.details {
  display: grid;
  padding-left: 56px;
}

.detail {
  grid-area: 1 / 1;
  font-size: var(--t-14);
  line-height: 1.55;
  color: var(--muted);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--dur-2) var(--ease-out), visibility 0s linear var(--dur-2);
}

.detailTitle {
  display: none;
  color: var(--ink);
}

.num {
  font-size: var(--t-12);
  color: var(--muted);
}

.track[data-step="0"] .step[data-i="0"],
.track[data-step="1"] .step[data-i="1"],
.track[data-step="2"] .step[data-i="2"],
.track[data-step="3"] .step[data-i="3"],
.track[data-step="4"] .step[data-i="4"] {
  opacity: 1;
}

.track[data-step="0"] .detail[data-i="0"],
.track[data-step="1"] .detail[data-i="1"],
.track[data-step="2"] .detail[data-i="2"],
.track[data-step="3"] .detail[data-i="3"],
.track[data-step="4"] .detail[data-i="4"] {
  opacity: 1;
  visibility: visible;
  transition: opacity var(--dur-2) var(--ease-out), visibility 0s linear 0s;
}

.rail {
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 1px;
  background: var(--line);
}

.rail span {
  position: absolute;
  inset: 0;
  background: var(--accent);
  transform-origin: top;
  transform: scaleY(0);
}

.figure {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.12fr);
  gap: var(--s-4);
  align-items: start;
}

.pane {
  border: 1px solid var(--line);
