  color: var(--ink);
}

.hookTag {
  color: var(--ink);
  overflow: hidden;
  text-overflow: clip;
}

.sessionBody {
  display: grid;
  padding: 14px;
  flex: 1;
}

.mon,
.tue {
  grid-area: 1 / 1;
  list-style: none;
