  padding: 0;
  display: grid;
  gap: 10px;
  align-content: start;
}

.line {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  column-gap: 8px;
  row-gap: 2px;
  font-family: var(--font-mono), monospace;
  font-size: var(--t-12);
  line-height: 1.5;
}

.user {
  color: var(--ink);
  font-weight: 600;
}

.tool {
  color: var(--ink);
  font-weight: 500;
}

.arg {
  color: var(--ink-2);
  overflow-wrap: anywhere;
}

.out {
  grid-column: 2;
  color: var(--muted);
}

.inject {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border: 1px solid var(--accent);
  border-radius: var(--radius);
  background: var(--sunk);
  font-size: var(--t-12);
  line-height: 1.55;
  color: var(--ink);
  font-family: var(--font-mono), monospace;
}

.injectHead {
  color: var(--muted);
  font-size: var(--t-12);
}

.store {
  padding: 14px;
  display: grid;
  gap: 12px;
  align-content: start;
}

.group {
  display: grid;
  gap: 8px;
}

.groupHead {
  font-size: var(--t-12);
  letter-spacing: var(--track-mono);
  text-transform: uppercase;
  color: var(--muted);
}

.obsList {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}

.obs {
  display: grid;
  grid-template-columns: 52px 50px minmax(0, 1fr);
  column-gap: 8px;
  row-gap: 4px;
  align-items: baseline;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  font-family: var(--font-mono), monospace;
  font-size: var(--t-12);
  line-height: 1.45;
}

.obsId {
  color: var(--muted);
}

.obsKind {
  color: var(--ink);
}

.obsText {
  color: var(--ink-2);
  overflow-wrap: anywhere;
}

.terms {
  grid-column: 3;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.terms span {
  padding: 0 6px;
  border-radius: 3px;
  background: var(--sunk);
  border: 1px solid var(--line);
  color: var(--ink-2);
  line-height: 18px;
}

.terms .vec {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--bg);
}

.indexLine {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  font-size: var(--t-12);
  color: var(--muted)

.grid {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.4fr);
  gap: clamp(24px, 4vw, 64px);
  align-items: start;
}

.list {
  border-top: 1px solid var(--line);
}

.item {
  border-bottom: 1px solid var(--line);
}

.item summary {
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-4);
  padding: var(--s-5) 0;
  cursor: pointer;
  color: var(--ink);
  font-size: var(--t-20);
  font-weight: 520;
  letter-spacing: -0.01em;
}

.item summary::-webkit-details-marker {
  display: none;
}

.mark {
  position: relative;
  width: 14px;
  height: 14px;
  flex: none;
}

.mark::before,
.mark::after {
  content: "";
  position: absolute;
  left: 0;
  top: 6.5px;
  width: 14px;
  height: 1px;
  background: var(--ink);
  transition: transform var(--dur-2) var(--ease-out);
}

.mark::after {
  transform: rotate(90deg);
}

.item[open] .mark::after {
  transform: rotate(0deg);
}

.item p {
  padding: 0 var(--s-6) var(--s-5) 0;
  color: var(--muted);
  font-size: var(--t-16);
  line-height: 1.65;
  max-width: 62ch;
  animation: open var(--dur-3) var(--ease-out);
}

.item summary:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 4px;
}

@keyframes open {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (max-width: 900px) {
  .grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }
  .item summary {
    font-size: var(--t-16);
  }
  .item p {
    padding-right: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .item p {
    animation: none;
  }
  .mark::before,
  .mark::after {
    transition: none;
  }
}

.dotsFigure {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow);
  padding: var(--s-5);
  display: grid;
  gap: var(--s-5);
}

.figHead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  font-size: var(--t-12);
  color: var(--muted);
  letter-spacing: 0.02em;
}

.toggle {
  display: inline-flex;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--sunk);
}

.toggle button {
  height: 30px;
  padding: 0 12px;
  border-radius: 4px;
  font-family: var(--font-mono), monospace;
  font-size: var(--t-12);
  color: var(--muted);
  transition: background-color var(--dur-1) ease, color var(--dur-1) ease, transform var(--dur-1) var(--ease-out);
}

.toggle button:active {
  transform: scale(0.97);
}

.toggle button[aria-pressed="true"] {
  background: var(--ink);
  color: var(--bg);
}

.verdict {
  font-size: var(--t-25);
  line-height: 1.3;
  color: var(--muted);
  letter-spacing: var(--track-head);
}

.verdict strong {
  color: var(--ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.groups {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--s-5) var(--s-6);
}

.group {
  display: grid;
  gap: 10px;
  align-content: start;
}

.groupHead {
  display: flex;
  justify-content: space-between;
  gap: var(--s-2);
  font-size: var(--t-12);
  color: var(--ink-2);
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line);
}

.groupHead span:last-child {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.dots {
  display: grid;
  grid-template-columns: repeat(auto-fill, 10px);
  gap: 5px;
}

.dot {
  position: relative;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--line-2);
}

.fill {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--accent);
  opacity: 0;
  transform: scale(0.35);
  transition: opacity 240ms var(--ease-out), transform 240ms var(--ease-out);
}

.dot[data-on] .fill {
  opacity: 1;
  transform: none;
  transition-delay: var(--d, 0ms);
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-5);
  font-size: var(--t-12);
  color: var(--muted);
}

.legend > span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.key {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--line-2);
}

.keyOn {
  background: var(--accent);
  box-shadow: none;
}

.ledgerWrap {
  overflow-x: auto;
  border-top: 1px solid var(--line);
  padding-top: var(--s-3);
}

.ledger {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-mono), monospace;
  font-size: var(--t-12);
  font-variant-numeric: tabular-nums;
}

.ledger th,
.ledger td {
  text-align: right;
  padding: 8px 10px;
  white-space: nowrap;
  border-bottom: 1px solid var(--line);
  transition: color var(--dur-1) ease, background-color var(--dur-1) ease;
}

.ledger tr:last-child th,
.ledger tr:last-child td {
  border-bottom: 0;
}

.ledger th:first-child {
  text-align: left;
  padding-left: 0;
}

.ledger thead th {
  font-weight: 500;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: var(--track-mono);
}

