import type { EmbeddingProvider } from "../../types.js";
import { getEnvVar } from "../../config.js";
import { fetchWithTimeout } from "../_fetch.js";

const BATCH_LIMIT = 100;
const MODEL = "models/gemini-embedding-001";
const API_BASE = `https://generativelanguage.googleapis.com/v1beta/${MODEL}:batchEmbedContents`;

export class GeminiEmbeddingProvider implements EmbeddingProvider {
  readonly name = "gemini";
  readonly dimensions = 768;
  private apiKey: string;

  constructor(apiKey?: string) {
    this.apiKey = apiKey || getEnvVar("GEMINI_API_KEY") || "";
    if (!this.apiKey) throw new Error("GEMINI_API_KEY is required");
  }

  async embed(text: string): Promise<Float32Array> {
    const [result] = await this.embedBatch([text]);
    return result;
  }

  async embedBatch(texts: string[]): Promise<Float32Array[]> {
    const results: Float32Array[] = [];

    for (let i = 0; i < texts.length; i += BATCH_LIMIT) {
      const chunk = texts.slice(i, i + BATCH_LIMIT);
      const response = await fetchWithTimeout(`${API_BASE}?key=${this.apiKey}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          requests: chunk.map((t) => ({
            model: MODEL,
            content: { parts: [{ text: t }] },
            outputDimensionality: this.dimensions,
          })),
        }),
      });

      if (!response.ok) {
        const err = await response.text();
        throw new Error(`Gemini embedding failed (${response.status}): ${err}`);
      }

      const data = (await response.json()) as {
        embeddings: Array<{ values: number[] }>;
      };

      for (const emb of data.embeddings) {
        results.push(l2Normalize(new Float32Array(emb.values)));
      }
    }

    return results;
  }
}

let zeroNormWarned = false;

function l2Normalize(vec: Float32Array): Float32Array {
  let sum = 0;
  for (let i = 0; i < vec.length; i++) sum += vec[i]! * vec[i]!;
  const norm = Math.sqrt(sum);
  if (norm === 0) {
    if (!zeroNormWarned) {
      zeroNormWarned = true;
      process.stderr.write(
        `[agentmemory] warn: gemini-embedding-001 returned a zero-norm ` +
          `embedding (length=${vec.length}); leaving it un-normalized. ` +
          `Subsequent zero-norm vectors will not be reported.\n`,
      );
    }
    return vec;
  }
  for (let i = 0; i < vec.length; i++) vec[i] = vec[i]! / norm;
  return vec;
}

/**
 * Shared embedding-dimension logic for OpenAI-compatible providers.
 *
 * OpenAI and OpenRouter expose the same underlying embedding models, so they
 * share one dimension table and one resolver. OpenRouter namespaces model ids
 * (e.g. "openai/text-embedding-3-small"); the lookup strips a leading
 * "provider/" prefix so both bare and namespaced keys resolve to the same
 * dimensions.
 *
 * The dimension guard (index.ts) throws on mismatch, so a wrong value here
 * breaks every embed call — keep entries accurate. Callers pass the relevant
 * env-var name (OPENAI_EMBEDDING_DIMENSIONS / OPENROUTER_EMBEDDING_DIMENSIONS)
 * so error messages point at the knob the operator actually set.
 */
const MODEL_DIMENSIONS: Record<string, number> = {
  "text-embedding-3-small": 1536,
  "text-embedding-3-large": 3072,
  "text-embedding-ada-002": 1536,
};

const DEFAULT_DIMENSIONS = 1536;

function lookupModelDimensions(model: string): number | undefined {
  if (model in MODEL_DIMENSIONS) return MODEL_DIMENSIONS[model];
  const slash = model.indexOf("/");
  if (slash === -1) return undefined;
  const bare = model.slice(slash + 1);
  return MODEL_DIMENSIONS[bare];
}

export function resolveDimensions(
  model: string,
  override: string | undefined,
  envName: string,
): number {
  if (override !== undefined && override.trim().length > 0) {
    const parsed = parseInt(override, 10);
    if (!Number.isFinite(parsed) || parsed <= 0) {
      throw new Error(
        `${envName} must be a positive integer, got: ${override}`,
      );
    }
    return parsed;
  }
  return lookupModelDimensions(model) ?? DEFAULT_DIMENSIONS;
}

export { MODEL_DIMENSIONS, DEFAULT_DIMENSIONS };

import type { EmbeddingProvider } from "../../types.js";

type FeatureExtractor = (
  texts: string[],
  options: { pooling: string; normalize: boolean },
) => Promise<{ tolist: () => number[][] }>;

export class LocalEmbeddingProvider implements EmbeddingProvider {
  readonly name = "local";
  readonly dimensions = 384;
  private extractor: FeatureExtractor | null = null;

  async embed(text: string): Promise<Float32Array> {
    const [result] = await this.embedBatch([text]);
    return result;
  }

  async embedBatch(texts: string[]): Promise<Float32Array[]> {
    const extractor = await this.getExtractor();
    const output = await extractor(texts, {
      pooling: "mean",
      normalize: true,
    });
    return output.tolist().map((v) => new Float32Array(v));
  }

  private async getExtractor() {
    if (this.extractor) return this.extractor;
    let transformers: typeof import("@huggingface/transformers");
    try {
      transformers = await import("@huggingface/transformers");
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ERR_MODULE_NOT_FOUND") {
        throw new Error(
          "Install @huggingface/transformers for local embeddings: npm install @huggingface/transformers",
        );
      }
      throw err;
    }
    this.extractor = (await transformers.pipeline(
      "feature-extraction",
      "Xenova/all-MiniLM-L6-v2",
      { dtype: "q8" },
    )) as FeatureExtractor;
    return this.extractor;
  }
}

import type { EmbeddingProvider } from "../../types.js";
import { getEnvVar } from "../../config.js";
import { fetchWithTimeout } from "../_fetch.js";
import { resolveDimensions } from "./_dimensions.js";

const API_URL = "https://openrouter.ai/api/v1/embeddings";

const DEFAULT_MODEL = "openai/text-embedding-3-small";

export class OpenRouterEmbeddingProvider implements EmbeddingProvider {
  readonly name = "openrouter";
  readonly dimensions: number;
  private apiKey: string;
  private model: string;

  constructor(apiKey?: string) {
    this.apiKey = apiKey || getEnvVar("OPENROUTER_API_KEY") || "";
    if (!this.apiKey) throw new Error("OPENROUTER_API_KEY is required");
    this.model = getEnvVar("OPENROUTER_EMBEDDING_MODEL") || DEFAULT_MODEL;
    this.dimensions = resolveDimensions(
      this.model,
      getEnvVar("OPENROUTER_EMBEDDING_DIMENSIONS"),
      "OPENROUTER_EMBEDDING_DIMENSIONS",
    );
  }

  async embed(text: string): Promise<Float32Array> {
    const [result] = await this.embedBatch([text]);
    return result;
  }

  async embedBatch(texts: string[]): Promise<Float32Array[]> {
    const response = await fetchWithTimeout(API_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: this.model,
        input: texts,
      }),
    });

    if (!response.ok) {
      const err = await response.text();
      throw new Error(
        `OpenRouter embedding failed (${response.status}): ${err}`,
      );
    }

    const data = (await response.json()) as {
      data: Array<{ embedding: number[] }>;
    };

    return data.data.map((d) => new Float32Array(d.embedding));
  }
}

import type { EmbeddingProvider } from "../../types.js";
import { detectEmbeddingProvider, getEnvVar } from "../../config.js";
import { GeminiEmbeddingProvider } from "./gemini.js";
import { OpenAIEmbeddingProvider } from "./openai.js";
import { VoyageEmbeddingProvider } from "./voyage.js";
import { CohereEmbeddingProvider } from "./cohere.js";
import { OpenRouterEmbeddingProvider } from "./openrouter.js";
import { LocalEmbeddingProvider } from "./local.js";
import { ClipEmbeddingProvider } from "./clip.js";

export {
  GeminiEmbeddingProvider,
  OpenAIEmbeddingProvider,
  VoyageEmbeddingProvider,
  CohereEmbeddingProvider,
  OpenRouterEmbeddingProvider,
  LocalEmbeddingProvider,
  ClipEmbeddingProvider,
};

let imageEmbeddingProvider: EmbeddingProvider | null = null;

export function createImageEmbeddingProvider(): EmbeddingProvider | null {
  if (process.env["AGENTMEMORY_IMAGE_EMBEDDINGS"] !== "true") return null;
  if (imageEmbeddingProvider) return imageEmbeddingProvider;
  imageEmbeddingProvider = withDimensionGuard(new ClipEmbeddingProvider());
  return imageEmbeddingProvider;
}

export function createEmbeddingProvider(): EmbeddingProvider | null {
  const detected = detectEmbeddingProvider();
  if (!detected) return null;

  switch (detected) {
    case "gemini":
      return withDimensionGuard(new GeminiEmbeddingProvider(getEnvVar("GEMINI_API_KEY")!));
    case "openai":
      return withDimensionGuard(new OpenAIEmbeddingProvider());
    case "voyage":
      return withDimensionGuard(new VoyageEmbeddingProvider(getEnvVar("VOYAGE_API_KEY")!));
    case "cohere":
      return withDimensionGuard(new CohereEmbeddingProvider(getEnvVar("COHERE_API_KEY")!));
    case "openrouter":
      return withDimensionGuard(new OpenRouterEmbeddingProvider(getEnvVar("OPENROUTER_API_KEY")!));
    case "local":
      return withDimensionGuard(new LocalEmbeddingProvider());
    default:
      return null;
  }
}

// Wrong-dimension vectors corrupt the index silently: vector-index.ts
// returns 0 from cosineSimilarity on length mismatch instead of throwing,
// so a bad vector is stored, never matches anything, and the memory
// becomes invisible without an error. Catch it at the boundary.
export function withDimensionGuard(provider: EmbeddingProvider): EmbeddingProvider {
  const expected = provider.dimensions;
  const check = (v: Float32Array, where: string): Float32Array => {
    if (v.length !== expected) {
      throw new Error(
        `Embedding dimension mismatch in ${provider.name}.${where}: expected ${expected}, got ${v.length}`,
      );
    }
    return v;
  };
  // Preserve the provider's prototype chain so `instanceof` checks
  // against concrete classes (e.g. GeminiEmbeddingProvider) keep working.
  const wrapped = Object.create(provider) as EmbeddingProvider;
  wrapped.embed = async (t) => check(await provider.embed(t), "embed");
  wrapped.embedBatch = async (ts) => {
    const out = await provider.embedBatch(ts);
    out.forEach((v, i) => check(v, `embedBatch[${i}]`));
    return out;
  };
  if (provider.embedImage) {
    wrapped.embedImage = async (s: string) =>
      check(await provider.embedImage!(s), "embedImage");
  }
  return wrapped;
}

import type { HealthSnapshot } from "../types.js";

interface ThresholdConfig {
  eventLoopLagWarnMs: number;
  eventLoopLagCriticalMs: number;
  cpuWarnPercent: number;
  cpuCriticalPercent: number;
  memoryWarnPercent: number;
  memoryCriticalPercent: number;
  memoryRssFloorBytes: number;
}

const DEFAULTS: ThresholdConfig = {
  eventLoopLagWarnMs: 100,
  eventLoopLagCriticalMs: 500,
  cpuWarnPercent: 80,
  cpuCriticalPercent: 90,
  memoryWarnPercent: 80,
  memoryCriticalPercent: 95,
  memoryRssFloorBytes: 512 * 1024 * 1024,
};

export function evaluateHealth(
  snapshot: HealthSnapshot,
  config: Partial<ThresholdConfig> = {},
): { status: "healthy" | "degraded" | "critical"; alerts: string[]; notes: string[] } {
  const cfg = { ...DEFAULTS, ...config };
  const alerts: string[] = [];
  const notes: string[] = [];
  let critical = false;
  let degraded = false;

  if (
    snapshot.connectionState === "disconnected" ||
    snapshot.connectionState === "failed"
  ) {
    alerts.push(`connection_${snapshot.connectionState}`);
    critical = true;
  } else if (snapshot.connectionState === "reconnecting") {
    alerts.push("connection_reconnecting");
    degraded = true;
  }

  if (snapshot.streamRelay === "down") {
    alerts.push("stream_relay_down");
    degraded = true;
  }

  if (snapshot.eventLoopLagMs > cfg.eventLoopLagCriticalMs) {
    alerts.push(
      `event_loop_lag_critical_${Math.round(snapshot.eventLoopLagMs)}ms`,
    );
    critical = true;
  } else if (snapshot.eventLoopLagMs > cfg.eventLoopLagWarnMs) {
    alerts.push(`event_loop_lag_warn_${Math.round(snapshot.eventLoopLagMs)}ms`);
    degraded = true;
  }

  if (snapshot.cpu.percent > cfg.cpuCriticalPercent) {
    alerts.push(`cpu_critical_${Math.round(snapshot.cpu.percent)}%`);
    critical = true;
  } else if (snapshot.cpu.percent > cfg.cpuWarnPercent) {
    alerts.push(`cpu_warn_${Math.round(snapshot.cpu.percent)}%`);
    degraded = true;
  }

  const heapCeiling = snapshot.memory.heapLimit || snapshot.memory.heapTotal;
  const memPercent =
    heapCeiling > 0 ? (snapshot.memory.heapUsed / heapCeiling) * 100 : 0;
  const rss = snapshot.memory.rss ?? 0;
  const rssAboveFloor = rss >= cfg.memoryRssFloorBytes;
  const memMb = Math.round(rss / (1024 * 1024));
  if (memPercent > cfg.memoryCriticalPercent && rssAboveFloor) {
    alerts.push(`memory_critical_${Math.round(memPercent)}%_rss${memMb}mb`);
    critical = true;
  } else if (memPercent > cfg.memoryWarnPercent && rssAboveFloor) {
    alerts.push(`memory_warn_${Math.round(memPercent)}%_rss${memMb}mb`);
    degraded = true;
  } else if (memPercent > cfg.memoryWarnPercent) {
    notes.push(`memory_heap_tight_${Math.round(memPercent)}%_rss${memMb}mb`);
  }

  const status = critical ? "critical" : degraded ? "degraded" : "healthy";
  return { status, alerts, notes };
}

import type { IIIClient } from "iii-sdk";
import { STREAM } from "../state/schema.js";

export type StreamRelayState = "ok" | "down" | "unknown";

export interface StreamRelayProbe {
  check(): Promise<StreamRelayState>;
  close(): void;
}

interface ProbeSocket {
  readyState: number;
  onopen: (() => void) | null;
  onmessage: ((event: { data: unknown }) => void) | null;
  onclose: (() => void) | null;
  onerror: (() => void) | null;
  send(data: string): void;
  close(): void;
}

export interface StreamRelayProbeOptions {
  url: string;
  timeoutMs?: number;
  createSocket?: (url: string) => ProbeSocket;
}

const PROBE_GROUP = "relay-probe";
const PROBE_EVENT = "relay.probe";
const OPEN = 1;

function defaultSocket(url: string): ProbeSocket {
  return new WebSocket(url) as unknown as ProbeSocket;
}

export function createStreamRelayProbe(
  sdk: IIIClient,
  options: StreamRelayProbeOptions,
): StreamRelayProbe {
  const timeoutMs = options.timeoutMs ?? 5000;
  const createSocket = options.createSocket ?? defaultSocket;
  let socket: ProbeSocket | null = null;
  let ready: Promise<boolean> | null = null;
  const waiters = new Map<string, () => void>();

  function connect(): Promise<boolean> {
    if (socket && socket.readyState === OPEN && ready) return ready;
    try {
      socket?.close();
    } catch {}
    let current: ProbeSocket;
    try {
      current = createSocket(options.url);
    } catch {
      socket = null;
      ready = null;
      return Promise.resolve(false);
    }
    socket = current;
    ready = new Promise<boolean>((resolve) => {
      const timer = setTimeout(() => resolve(false), timeoutMs);
      current.onopen = () => {
        clearTimeout(timer);
        current.send(
          JSON.stringify({
            type: "join",
            data: {
              subscriptionId: `relay-probe-${process.pid}-${Date.now()}`,
              streamName: STREAM.name,
              groupId: PROBE_GROUP,
            },
          }),
        );
        resolve(true);
      };
      current.onerror = () => {
        clearTimeout(timer);
        resolve(false);
      };
      current.onclose = () => {
        clearTimeout(timer);
        if (socket === current) {
          socket = null;
          ready = null;
        }
        resolve(false);
      };
    });
    current.onmessage = (event) => {
      try {
        const raw = typeof event.data === "string" ? event.data : String(event.data);
        const nonce = JSON.parse(raw)?.event?.event?.data?.nonce;
        if (typeof nonce === "string") waiters.get(nonce)?.();
      } catch {}
    };
    return ready;
  }

  async function check(): Promise<StreamRelayState> {
    if (!(await connect())) return "unknown";
    const nonce = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const received = new Promise<boolean>((resolve) => {
      waiters.set(nonce, () => resolve(true));
      timer = setTimeout(() => resolve(false), timeoutMs);
    });
    try {
      await sdk.trigger({
        function_id: "stream::send",
        payload: {
          stream_name: STREAM.name,
          group_id: PROBE_GROUP,
          id: nonce,
          type: PROBE_EVENT,
          data: { nonce },
        },
        timeoutMs,
      });
    } catch {
      waiters.delete(nonce);
      clearTimeout(timer);
      return "down";
    }
    const ok = await received;
    waiters.delete(nonce);
    clearTimeout(timer);
    return ok ? "ok" : "down";
  }

  return {
    check,
    close() {
      waiters.clear();
      try {
        socket?.close();
      } catch {}
      socket = null;
      ready = null;
    },
  };
}

import { getHeapStatistics } from "node:v8";
import type { IIIClient } from "iii-sdk";
import type { HealthSnapshot } from "../types.js";
import type { StateKV } from "../state/kv.js";
import { KV } from "../state/schema.js";
import { evaluateHealth } from "./thresholds.js";
import type { StreamRelayProbe } from "./stream-relay-probe.js";

export function registerHealthMonitor(
  sdk: IIIClient,
  kv: StateKV,
  options: { streamRelayProbe?: StreamRelayProbe } = {},
): { stop: () => void } {
  let connectionState = "connected";
  let prevCpuUsage = process.cpuUsage();
  let prevCpuTime = Date.now();

  if (typeof sdk.on === "function") {
    sdk.on("connection_state", (state?: unknown) => {
      connectionState = state as string;
    });
  }

  async function collectHealth(): Promise<HealthSnapshot> {
    const mem = process.memoryUsage();
    const currentCpu = process.cpuUsage();
    const now = Date.now();
    const uptime = process.uptime();

    const elapsedMs = now - prevCpuTime;
    const userDelta = currentCpu.user - prevCpuUsage.user;
    const systemDelta = currentCpu.system - prevCpuUsage.system;
    const cpuPercent =
      elapsedMs > 0 ? ((userDelta + systemDelta) / 1000 / elapsedMs) * 100 : 0;
    prevCpuUsage = currentCpu;
    prevCpuTime = now;

    const startMark = performance.now();
    await new Promise((resolve) => setImmediate(resolve));
    const eventLoopLagMs = performance.now() - startMark;

    let workers: HealthSnapshot["workers"] = [];
    try {
      const result = await sdk.trigger<
        unknown,
        { workers?: HealthSnapshot["workers"] }
      >({ function_id: "engine::workers::list", payload: {} });
      if (result?.workers) workers = result.workers;
    } catch {}

    const KV_PROBE_TIMEOUT = 5000;
    let kvConnectivity: { status: string; latencyMs?: number; error?: string };
    const kvStart = performance.now();
    try {
      await Promise.race([
        (async () => {
          await kv.set(KV.health, "_probe", { ts: Date.now() });
          await kv.get(KV.health, "_probe");
        })(),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error("timeout")), KV_PROBE_TIMEOUT),
        ),
      ]);
      kvConnectivity = { status: "ok", latencyMs: Math.round((performance.now() - kvStart) * 100) / 100 };
    } catch {
      kvConnectivity = { status: "error", error: "kv_probe_failed", latencyMs: Math.round((performance.now() - kvStart) * 100) / 100 };
    }

    const streamRelay = options.streamRelayProbe
      ? await options.streamRelayProbe.check().catch(() => "unknown" as const)
      : undefined;

    const snapshot: HealthSnapshot = {
      connectionState,
      ...(streamRelay ? { streamRelay } : {}),
      workers,
      memory: {
        heapUsed: mem.heapUsed,
        heapTotal: mem.heapTotal,
        heapLimit: getHeapStatistics().heap_size_limit,
        rss: mem.rss,
        external: mem.external,
      },
      cpu: {
        userMicros: currentCpu.user,
        systemMicros: currentCpu.system,
        percent: Math.round(cpuPercent * 100) / 100,
      },
      eventLoopLagMs,
      uptimeSeconds: uptime,
      kvConnectivity,
      status: "healthy",
      alerts: [],
    };

    const evaluated = evaluateHealth(snapshot);
    snapshot.status = evaluated.status;
    snapshot.alerts = evaluated.alerts;
    snapshot.notes = evaluated.notes;

    await kv.set(KV.health, "latest", snapshot).catch(() => {});
    return snapshot;
  }

  collectHealth().catch(() => {});
  const interval = setInterval(() => {
    collectHealth().catch(() => {});
  }, 30_000);
  interval.unref();

  return {
    stop: () => {
      clearInterval(interval);
      options.streamRelayProbe?.close();
    },
  };
}

export async function getLatestHealth(
  kv: StateKV,
): Promise<HealthSnapshot | null> {
  return kv.get<HealthSnapshot>(KV.health, "latest");
}

import { homedir } from "node:os";
import { join, resolve, sep } from "node:path";
import { existsSync } from "node:fs";
import { mkdir, writeFile, unlink, utimes, stat } from "node:fs/promises";
import { createHash } from "node:crypto";

export const IMAGES_DIR = join(homedir(), ".agentmemory", "images");

const DEFAULT_MAX_BYTES = 500 * 1024 * 1024;

export function getMaxBytes(): number {
  return Number(process.env.AGENTMEMORY_IMAGE_STORE_MAX_BYTES) || DEFAULT_MAX_BYTES;
}

export function isManagedImagePath(filePath: string): boolean {
  const resolved = resolve(filePath);
  const normalizedImagesDir = resolve(IMAGES_DIR);
  return resolved.startsWith(normalizedImagesDir + sep) || resolved === normalizedImagesDir;
}

function contentHash(data: string): string {
  return createHash("sha256").update(data).digest("hex");
}

export async function saveImageToDisk(base64Data: string): Promise<{ filePath: string; bytesWritten: number }> {
  if (!base64Data) return { filePath: "", bytesWritten: 0 };

  if (!existsSync(IMAGES_DIR)) {
    await mkdir(IMAGES_DIR, { recursive: true });
  }

  let cleanBase64 = base64Data;
  let ext = "png";

  if (base64Data.startsWith("data:image/")) {
     const commaIdx = base64Data.indexOf(",");
     if (commaIdx !== -1) {
       const meta = base64Data.substring(0, commaIdx);
       if (meta.includes("jpeg") || meta.includes("jpg")) ext = "jpg";
       else if (meta.includes("webp")) ext = "webp";
       else if (meta.includes("gif")) ext = "gif";
       cleanBase64 = base64Data.substring(commaIdx + 1);
     }
  } else if (base64Data.startsWith("/9j/")) {
     ext = "jpg";
  }

  const hash = contentHash(cleanBase64);
  const filePath = join(IMAGES_DIR, `${hash}.${ext}`);

  if (existsSync(filePath)) {
    return { filePath, bytesWritten: 0 };
  }

  const buffer = Buffer.from(cleanBase64, "base64");
  await writeFile(filePath, buffer);

  const s = await stat(filePath);

  return { filePath, bytesWritten: s.size };
}

export async function deleteImage(filePath: string | undefined): Promise<{ deletedBytes: number }> {
  if (!filePath) return { deletedBytes: 0 };
  if (!isManagedImagePath(filePath)) return { deletedBytes: 0 };
  try {
    if (existsSync(filePath)) {
      const s = await stat(filePath);
      const size = s.size;
      await unlink(filePath);
      return { deletedBytes: size };
    }
  } catch (err) {
    console.error("[agentmemory] Failed to delete image context:", err);
  }
  return { deletedBytes: 0 };
}

/** Touch an image file to update its mtime (marking it as recently used for LRU eviction) */
export async function touchImage(filePath: string): Promise<void> {
  if (!filePath || !isManagedImagePath(filePath)) return;
  try {
    if (existsSync(filePath)) {
      const now = new Date();
      await utimes(filePath, now, now);
    }
  } catch (err) {
    // Ignore touch errors silently
  }
}

import { pathToFileURL } from "node:url";
import { VERSION } from "../version.js";
import { resolveClientSecret } from "../secret-store.js";
import { resolveEnvOrEmpty } from "./rest-proxy.js";
import { createStdioTransport, JsonRpcError, type RequestHandler } from "./transport.js";

const PROTOCOLS = ["2025-11-25", "2025-06-18", "2025-03-26", "2024-11-05"];
const SETUP = "Start Agent Memory, check `agentmemory status`, and verify AGENTMEMORY_URL and AGENTMEMORY_SECRET in the MCP host environment.";

// This bridge owns no memory store. All operations use the same daemon as hooks.
export function createPluginBridge(): RequestHandler {
  const base = new URL(resolveEnvOrEmpty("AGENTMEMORY_URL") || "http://localhost:3111");
  if (!["http:", "https:"].includes(base.protocol) || base.username || base.password || base.search || base.hash) {
    throw new Error("AGENTMEMORY_URL must be an HTTP(S) base URL without credentials, query, or fragment.");
  }
  const loopback = ["localhost", "localhost.", "[::1]"].includes(base.hostname)
    || /^127(?:\.\d{1,3}){3}$/.test(base.hostname);
  function resolveSecret(): string {
    const secret = resolveClientSecret(base.href);
    if (secret && base.protocol !== "https:" && !loopback) {
      throw new Error("AGENTMEMORY_URL requires HTTPS when AGENTMEMORY_SECRET is set, except for loopback URLs.");
    }
    return secret;
  }
  resolveSecret();

  async function call(path: string, body?: Record<string, unknown>): Promise<any> {
    const secret = resolveSecret();
