export function generateId(prefix: string): string {
  const ts = Date.now().toString(36);
  const rand = crypto.randomUUID().replace(/-/g, "").slice(0, 12);
  return `${prefix}_${ts}_${rand}`;
}

export function fingerprintId(prefix: string, content: string): string {
  const hash = createHash("sha256").update(content).digest("hex");
  return `${prefix}_${hash.slice(0, 16)}`;
}

// CJK/Japanese/Thai text carries no inter-word whitespace, so a plain
// split(/\s+/) collapses a whole sentence into one token and the two token
// sets never overlap — dedup silently stops working. When either input
// contains CJK we segment the CJK runs (word tokens via the shared
// segmenter, plus character bigram shingles so near-identical strings still
// overlap even when the optional segmenter deps fall back to whole-string).
// ASCII text keeps the original word-level behavior.
function jaccardTokens(text: string): Set<string> {
  if (!hasCjk(text)) {
    return new Set(text.split(/\s+/).filter((t) => t.length > 2));
  }
  const tokens = new Set<string>();
  for (const raw of text.split(/\s+/)) {
    if (!raw) continue;
    if (hasCjk(raw)) {
      for (const seg of segmentCjk(raw)) {
        if (seg) tokens.add(seg);
      }
      // Character bigram shingles keep the CJK signal even when the
      // segmenter returns the whole run: overlapping bigrams make
      // near-identical strings match while unrelated ones ("北京" vs
      // "上海") share none. Never drop short CJK tokens.
      const chars = Array.from(raw);
      if (chars.length === 1) {
        tokens.add(chars[0]);
      } else {
        for (let i = 0; i < chars.length - 1; i++) {
          tokens.add(chars[i] + chars[i + 1]);
        }
      }
    } else if (raw.length > 2) {
      tokens.add(raw);
    }
  }
  return tokens;
}

export function jaccardSimilarity(a: string, b: string): number {
  const na = a.normalize("NFC");
  const nb = b.normalize("NFC");
  const setA = jaccardTokens(na);
  const setB = jaccardTokens(nb);
  // An empty token set carries no signal for the overlap metric. Very short
  // ASCII text ("AI", "a b", "go") tokenizes to nothing because words <=2
  // chars are dropped. Fall back to exact normalized equality so re-saving
  // the identical short memory still supersedes, while unrelated short
  // strings ("AI" vs "ML") correctly score 0. Returning 1 unconditionally
  // here (as an "both empty" shortcut once did) would let any short memory
  // falsely supersede another, silently marking a real memory not-latest.
  if (setA.size === 0 || setB.size === 0) {
    return na.trim().repl

import type { IIIClient } from "iii-sdk";
import { STREAM } from "./schema.js";
import { generatedIdTime } from "./kv.js";
import { getViewerStreamMax } from "../config.js";
import { logger } from "../logger.js";

const PRUNE_BATCH_INTERVAL = 50;
const DELETE_BATCH_SIZE = 100;
const UNSHIFT_CHUNK_SIZE = 1000;
const SEED_TIMEOUT_MS = 5000;

const trackedItemIds: string[] = [];
const trackedItemIdSet = new Set<string>();
let writesSincePrune = 0;
let pruning = false;
let pruneAgain = false;

export function trackViewerStreamItem(itemId: string): void {
  if (trackedItemIdSet.has(itemId)) return;
  trackedItemIdSet.add(itemId);
  trackedItemIds.push(itemId);
  writesSincePrune += 1;
}

function unshiftMany(target: string[], items: string[]): void {
  for (let end = items.length; end > 0; end -= UNSHIFT_CHUNK_SIZE) {
    const start = Math.max(0, end - UNSHIFT_CHUNK_SIZE);
    target.splice(0, 0, ...items.slice(start, end));
  }
}

async function deleteItems(sdk: IIIClient, itemIds: string[]): Promise<string[]> {
  const failedItemIds: string[] = [];
  for (let start = 0; start < itemIds.length; start += DELETE_BATCH_SIZE) {
    const batch = itemIds.slice(start, start + DELETE_BATCH_SIZE);
    const results = await Promise.allSettled(
      batch.map((itemId) =>
        sdk.trigger({
          function_id: "stream::delete",
          payload: {
            stream_name: STREAM.name,
            group_id: STREAM.viewerGroup,
            item_id: itemId,
          },
        }),
      ),
    );
    for (let i = 0; i < results.length; i++) {
      const result = results[i];
      if (result.status === "rejected") {
        logger.warn("Failed to prune viewer stream item", {
          error:
            result.reason instanceof Error
              ? result.reason.message
              : String(result.reason),
        });
        failedItemIds.push(batch[i]);
      }
    }
  }
  return failedItemIds;
}

async function pruneOverflow(sdk: IIIClient): Promise<void> {
  if (pruning) {
    pruneAgain = true;
    return;
  }
  pruning = true;
  try {
    do {
      pruneAgain = false;
      const overflow = trackedItemIds.length - getViewerStreamMax();
      if (overflow <= 0) break;
      const candidates = trackedItemIds.splice(0, overflow);
      for (const itemId of candidates) trackedItemIdSet.delete(itemId);
      candidates.reverse();
      const failedItemIds = await deleteItems(sdk, candidates);
      if (failedItemIds.length > 0) {
        for (const itemId of failedItemIds) trackedItemIdSet.add(itemId);
        unshiftMany(trackedItemIds, failedItemIds);
      }
    } while (pruneAgain);
  } finally {
    pruning = false;
  }
}

export async function pruneViewerStreamIfDue(sdk: IIIClient): Promise<void> {
  if (writesSincePrune < PRUNE_BATCH_INTERVAL) return;
  writesSincePrune = 0;
  await pruneOverflow(sdk);
}

type StoredViewerItem = {
  observation?: { id?: unknown; timestamp?: unknown };
};

function itemTime(item: StoredViewerItem): number {
  const fromId = generatedIdTime(item?.observation?.id);
  if (fromId !== null) return fromId;
  const raw = item?.observation?.timestamp;
  const parsed = typeof raw === "string" ? Date.parse(raw) : typeof raw === "number" ? raw : NaN;
  return Number.isFinite(parsed) ? parsed : Number.NEGATIVE_INFINITY;
}

function oldestFirst(items: StoredViewerItem[]): StoredViewerItem[] {
  return items
    .map((item, index) => ({ item, index, at: itemTime(item) }))
    .sort((a, b) => (a.at !== b.at ? (a.at < b.at ? -1 : 1) : a.index - b.index))
    .map((entry) => entry.item);
}

export interface SeedViewerStreamOptions {
  unorderedListing?: boolean;
}

export async function seedViewerStreamTracker(
  sdk: IIIClient,
  options: SeedViewerStreamOptions = {},
): Promise<number> {
  let items: StoredViewerItem[];
  try {
    items = await sdk.trigger<unknown, StoredViewerItem[]>({
      function_id: "stream::list",
      payload: { stream_name: STREAM.name, group_id: STREAM.viewerGroup },
      timeoutMs: SEED_TIMEOUT_MS,
    });
  } catch (err) {
    logger.warn("Could not read the viewer stream backlog", {
      error: err instanceof Error ? err.message : String(err),
    });
    return 0;
  }
  if (!Array.isArray(items)) return 0;
  const stored: string[] = [];
  for (const item of options.unorderedListing ? oldestFirst(items) : items) {
    const id = item?.observation?.id;
    if (typeof id !== "string" || trackedItemIdSet.has(id)) continue;
    trackedItemIdSet.add(id);
    stored.push(id);
  }
  unshiftMany(trackedItemIds, stored);
  await pruneOverflow(sdk);
  return stored.length;
}

export function resetViewerStreamTracker(): void {
  trackedItemIds.length = 0;
  trackedItemIdSet.clear();
  writesSincePrune = 0;
  pruning = false;
  pruneAgain = false;
}

import type { CompressedObservation } from "../types.js";
import { stem } from "./stemmer.js";
import { getSynonyms } from "./synonyms.js";
import { segmentCjk, hasCjk } from "./cjk-segmenter.js";

interface IndexEntry {
  obsId: string;
  sessionId: string;
  termCount: number;
}

export class SearchIndex {
  private entries: Map<string, IndexEntry> = new Map();
  private invertedIndex: Map<string, Set<string>> = new Map();
  private docTermCounts: Map<string, Map<string, number>> = new Map();
  private totalDocLength = 0;
  private sortedTerms: string[] | null = null;

  private readonly k1 = 1.2;
  private readonly b = 0.75;

  add(obs: CompressedObservation): void {
    if (this.entries.has(obs.id)) this.remove(obs.id);
    const terms = this.extractTerms(obs);
    const termFreq = new Map<string, number>();
    let termCount = 0;

    for (const term of terms) {
      termFreq.set(term, (termFreq.get(term) || 0) + 1);
      termCount++;
    }

    this.entries.set(obs.id, {
      obsId: obs.id,
      sessionId: obs.sessionId,
      termCount,
    });
    this.docTermCounts.set(obs.id, termFreq);
    this.totalDocLength += termCount;

    for (const term of termFreq.keys()) {
      if (!this.invertedIndex.has(term)) {
        this.invertedIndex.set(term, new Set());
      }
      this.invertedIndex.get(term)!.add(obs.id);
    }

    this.sortedTerms = null;
  }

  has(id: string): boolean {
    return this.entries.has(id);
  }

  sessionOf(id: string): string | undefined {
    return this.entries.get(id)?.sessionId;
  }

  observationCountsBySession(): Map<string, number> {
    const counts = new Map<string, number>();
    for (const entry of this.entries.values()) {
      if (entry.obsId.startsWith("mem_")) continue;
      counts.set(entry.sessionId, (counts.get(entry.sessionId) ?? 0) + 1);
    }
    return counts;
  }

  documentKindCounts(): { memories: number; lessons: number } {
    let memories = 0;
    let lessons = 0;
    for (const entry of this.entries.values()) {
      if (entry.obsId.startsWith("mem_")) memories++;
      else if (entry.sessionId === "lesson") lessons++;
    }
    return { memories, lessons };
  }

  remove(id: string): void {
    const entry = this.entries.get(id);
    if (!entry) return;

    const termFreq = this.docTermCounts.get(id);
    if (termFreq) {
      for (const term of termFreq.keys()) {
        const postingList = this.invertedIndex.get(term);
        if (postingList) {
          postingList.delete(id);
          if (postingList.size === 0) {
            this.invertedIndex.delete(term);
          }
        }
      }
      this.docTermCounts.delete(id);
    }

    this.totalDocLength = Math.max(0, this.totalDocLength - entry.termCount);
    this.entries.delete(id);
    this.sortedTerms = null;
  }

  search(
    query: string,
    limit = 20,
  ): Array<{ obsId: string; sessionId: string; score: number }> {
    const rawTerms = this.tokenize(query.toLowerCase());
    if (rawTerms.length === 0) return [];

    const N = this.entries.size;
    if (N === 0) return [];
    const avgDocLen = this.totalDocLength / N;

    const queryTerms: Array<{ term: string; weight: number }> = [];
    const seen = new Set<string>();
    for (const term of rawTerms) {
      if (!seen.has(term)) {
        seen.add(term);
        queryTerms.push({ term, weight: 1.0 });
      }
      for (const syn of getSynonyms(term)) {
        if (!seen.has(syn)) {
          seen.add(syn);
          queryTerms.push({ term: syn, weight: 0.7 });
        }
      }
    }

    const scores = new Map<string, number>();
    const sorted = this.getSortedTerms();

    for (const { term, weight } of queryTerms) {
      const matchingDocs = this.invertedIndex.get(term);
      if (matchingDocs) {
        const df = matchingDocs.size;
        const idf = Math.log((N - df + 0.5) / (df + 0.5) + 1);

        for (const obsId of matchingDocs) {
