const OBS_INDEX_SHARDS = 64;

function shardFor(obsId: string): number {
  let hash = 5381;
  for (let i = 0; i < obsId.length; i++) {
    hash = ((hash << 5) + hash + obsId.charCodeAt(i)) | 0;
  }
  return Math.abs(hash) % OBS_INDEX_SHARDS;
}

