        method: "POST",
        headers: authHeaders(),
        body: JSON.stringify({}),
        signal: AbortSignal.timeout(5000),
      });
    } catch {
      // best-effort
    }
  }

  const budget = preCompactBudget();
  if (budget === 0) return;

