#!/usr/bin/env node
import { resolveClientSecret } from "../secret-store.js";
import { resolveProject, hookCwd } from "./_project.js";

// Inlined from ./sdk-guard so each hook bundles to a single self-contained
// .mjs (matches the pattern used by every other hook entry in tsdown.config).
function isSdkChildContext(payload: unknown): boolean {
  if (process.env["AGENTMEMORY_SDK_CHILD"] === "1") return true;
  if (!payload || typeof payload !== "object") return false;
  return (payload as { entrypoint?: unknown }).entrypoint === "sdk-ts";
}

const INJECT_CONTEXT = process.env["AGENTMEMORY_INJECT_CONTEXT"] === "true";

const REST_URL = process.env["AGENTMEMORY_URL"] || "http://localhost:3111";
const SECRET = resolveClientSecret(REST_URL);

const INJECT_TIMEOUT_MS = 1500;
const REGISTER_TIMEOUT_MS = 800;

function authHeaders(): Record<string, string> {
  const h: Record<string, string> = { "Content-Type": "application/json" };
  if (SECRET) h["Authorization"] = `Bearer ${SECRET}`;
  return h;
}

function isPlainTextHost(): boolean {
  return Boolean(
    process.env["FACTORY_PROJECT_DIR"] || process.env["DROID_PLUGIN_ROOT"],
  );
}

function wantsStructuredOutput(data: Record<string, unknown>): boolean {
  if (process.env["DEVIN_PROJECT_DIR"] || data.prompt_id !== undefined) {
    return true;
  }
  return data.hook_event_name === "SessionStart" && !isPlainTextHost();
}

function contextPayload(data: Record<string, unknown>, context: string): string {
  if (
    typeof data.cursor_version === "string" ||
    data.hook_event_name === "sessionStart"
  ) {
    return JSON.stringify({ additional_context: context });
  }
  if (wantsStructuredOutput(data)) {
    return JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "SessionStart",
        additionalContext: context,
      },
    });
  }
  return context;
}

async function main() {
  let input = "";
  for await (const chunk of process.stdin) {
    input += chunk;
  }

  let data: Record<string, unknown>;
  try {
    data = JSON.parse(input);
  } catch {
    return;
  }

  if (!data || typeof data !== "object") return;
  if (isSdkChildContext(data)) return;

  const sessionId =
    ((data.session_id || data.sessionId || data.conversation_id) as string) ||
    `ses_${Date.now().toString(36)}`;
  const cwd = hookCwd(data) || process.cwd();
  const project = resolveProject(cwd);

  const url = `${REST_URL}/agentmemory/session/start`;
  const init: RequestInit = {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({ sessionId, project, cwd }),
  };

  if (!INJECT_CONTEXT) {
    // Pure telemetry path: caller never reads the response, so don't
    // block on it. AbortSignal.timeout caps the wait the event loop
    // gives the pending socket before exit.
    fetch(url, {
      ...init,
      signal: AbortSignal.timeout(REGISTER_TIMEOUT_MS),
    }).catch(() => {});
    return;
  }

  try {
    const res = await fetch(url, {
      ...init,
      signal: AbortSignal.timeout(INJECT_TIMEOUT_MS),
    });
    if (res.ok) {
      const result = (await res.json()) as { context?: string };
      if (result.context) {
        process.stdout.write(contextPayload(data, result.context));
      }
    }
  } catch {
    // silently fail -- don't block Claude Code startup
  }
}

main().catch(() => process.exit(0));

#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { resolveProject, hookCwd } from "./_project.js";
import { REST_URL, authHeaders, captureObservation, isDrainChild, runDrainChild, withEventId } from "./_capture.js";

function isSdkChildContext(payload: unknown): boolean {
  if (process.env["AGENTMEMORY_SDK_CHILD"] === "1") return true;
  if (!payload || typeof payload !== "object") return false;
  return (payload as { entrypoint?: unknown }).entrypoint === "sdk-ts";
}

function extractTranscriptPrompts(data: Record<string, unknown>): string[] {
  const path = data.transcript_path;
  if (typeof path !== "string" || !path.endsWith(".jsonl")) return [];
  let raw: string;
  try {
    raw = readFileSync(path, "utf-8");
  } catch {
    return [];
  }
  const prompts: string[] = [];
  for (const line of raw.split("\n")) {
    if (!line.trim()) continue;
    let msg: {
      role?: string;
      message?: { content?: Array<{ type?: string; text?: string }> };
    };
    try {
      msg = JSON.parse(line);
    } catch {
      continue;
    }
    if (msg.role !== "user") continue;
    for (const block of msg.message?.content ?? []) {
      if (prompts.length >= 50) return prompts;
      if (block.type !== "text" || typeof block.text !== "string") continue;
      const m = block.text.match(/<user_query>\n?([\s\S]*?)\n?<\/user_query>/);
      const text = (m ? m[1] : block.text).trim();
      if (text) prompts.push(text.slice(0, 8000));
    }
  }
  return prompts;
}

async function main() {
  if (isDrainChild()) return runDrainChild();
  let input = "";
  for await (const chunk of process.stdin) {
    input += chunk;
  }

  let data: Record<string, unknown>;
  try {
    data = JSON.parse(input);
  } catch {
    return;
  }

  if (!data || typeof data !== "object") return;
  if (isSdkChildContext(data)) return;

  const sessionId = ((data.session_id || data.sessionId || data.conversation_id) as string) || "unknown";

  const transcriptPrompts = extractTranscriptPrompts(data);
  if (transcriptPrompts.length > 0) {
    const cwd = hookCwd(data) || process.cwd();
    const project = resolveProject(cwd);
    const timestamp = new Date().toISOString();
    await Promise.allSettled(
      transcriptPrompts.map((prompt, index) =>
        captureObservation(
          withEventId(
            { hookType: "prompt_submit", sessionId, project, cwd, timestamp, data: { prompt, backfill: true } },
            {},
            { source: "transcript", transcript: data.transcript_path, index, prompt },
            { stable: true },
          ),
          3000,
        ),
      ),
    );
  }

  fetch(`${REST_URL}/agentmemory/session/end`, {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({ sessionId }),
    signal: AbortSignal.timeout(30000),
  }).catch(() => {});

  if (process.env["CLAUDE_MEMORY_BRIDGE"] === "true") {
    fetch(`${REST_URL}/agentmemory/claude-bridge/sync`, {
      method: "POST",
      headers: authHeaders(),
      signal: AbortSignal.timeout(30000),
    }).catch(() => {});
  }

  setTimeout(() => process.exit(0), 1500).unref();
}

main().catch(() => process.exit(0));

export function isSdkChildContext(payload: unknown): boolean {
  if (process.env.AGENTMEMORY_SDK_CHILD === "1") return true;
  if (!payload || typeof payload !== "object") return false;
  const p = payload as Record<string, unknown>;
  if (p["entrypoint"] === "sdk-ts") return true;
  return false;
}

