import type { IIIClient } from "iii-sdk";
import type { StateKV } from "../state/kv.js";
import { KV } from "../state/schema.js";
import type { Session } from "../types.js";
import { execFile } from "node:child_process";
import { resolve } from "node:path";

function execAsync(
  cmd: string,
  args: string[],
  cwd: string,
): Promise<string> {
  return new Promise((resolve, reject) => {
    execFile(cmd, args, { cwd, timeout: 5000 }, (err, stdout) => {
      if (err) reject(err);
      else resolve(stdout.trim());
    });
  });
}

export function registerBranchAwareFunction(sdk: IIIClient, kv: StateKV): void {
  sdk.registerFunction("mem::detect-worktree", 
    async (data: { cwd: string }) => {
      if (!data.cwd) {
        return { success: false, error: "cwd is required" };
      }

      try {
        const gitDir = await execAsync(
          "git",
          ["rev-parse", "--git-dir"],
          data.cwd,
        );
        const commonDir = await execAsync(
          "git",
          ["rev-parse", "--git-common-dir"],
          data.cwd,
        );
        const branch = await execAsync(
          "git",
          ["rev-parse", "--abbrev-ref", "HEAD"],
          data.cwd,
        ).catch(() => "detached");

        const topLevel = await execAsync(
          "git",
          ["rev-parse", "--show-toplevel"],
          data.cwd,
        );

        const isWorktree = resolve(data.cwd, gitDir) !== resolve(data.cwd, commonDir);
        const mainRepoRoot = isWorktree
          ? resolve(data.cwd, commonDir, "..")
          : topLevel;

        return {
          success: true,
          isWorktree,
          branch,
          topLevel,
          mainRepoRoot,
          gitDir: resolve(data.cwd, gitDir),
          commonDir: resolve(data.cwd, commonDir),
        };
      } catch {
        return {
          success: true,
          isWorktree: false,
          branch: null,
          topLevel: data.cwd,
          mainRepoRoot: data.cwd,
          gitDir: null,
          commonDir: null,
        };
      }
    },
  );

  sdk.registerFunction("mem::list-worktrees", 
    async (data: { cwd: string }) => {
      if (!data.cwd) {
        return { success: false, error: "cwd is required" };
      }

      try {
        const output = await execAsync(
          "git",
          ["worktree", "list", "--porcelain"],
          data.cwd,
        );

        const worktrees: Array<{
          path: string;
          head: string;
          branch: string;
          bare: boolean;
        }> = [];

        const blocks = output.split("\n\n").filter(Boolean);
        for (const block of blocks) {
          const lines = block.split("\n");
          const wt: { path: string; head: string; branch: string; bare: boolean } = {
            path: "",
            head: "",
            branch: "",
            bare: false,
          };
          for (const line of lines) {
            if (line.startsWith("worktree ")) wt.path = line.slice(9);
            else if (line.startsWith("HEAD ")) wt.head = line.slice(5);
            else if (line.startsWith("branch "))
              wt.branch = line.slice(7).replace("refs/heads/", "");
            else if (line === "bare") wt.bare = true;
          }
          if (wt.path) worktrees.push(wt);
        }

        return { success: true, worktrees };
      } catch {
        return { success: true, worktrees: [] };
      }
    },
  );

  sdk.registerFunction("mem::branch-sessions", 
    async (data: { cwd: string; branch?: string }) => {
      if (!data.cwd) {
        return { success: false, error: "cwd is required" };
      }

      const worktreeInfo = await sdk.trigger<
        { cwd: string },
        {
          success: boolean;
          isWorktree: boolean;
          mainRepoRoot: string;
          branch: string | null;
        }
      >({ function_id: "mem::detect-worktree", payload: { cwd: data.cwd } });

      const projectRoot = worktreeInfo.mainRepoRoot || data.cwd;
      const branch = data.branch || worktreeInfo.branch;

      const sessions = await kv.list<Session>(KV.sessions);

      const matching = sessions.filter((s) => {
        if (s.project === projectRoot || s.cwd === projectRoot) return true;
        if (s.cwd.startsWith(projectRoot + "/")) return true;
        return false;
      });

      matching.sort(
        (a, b) =>
          new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime(),
      );

      return {
        success: true,
        sessions: matching,
        projectRoot,
        branch,
        isWorktree: worktreeInfo.isWorktree,
      };
    },
  );
}

import type { IIIClient } from "iii-sdk";
import type { StateKV } from "../state/kv.js";
import { KV } from "../state/schema.js";
import { withKeyedLock } from "../state/keyed-mutex.js";
import type { Session } from "../types.js";
import { logger } from "../logger.js";
import { safeAudit } from "./audit.js";
import {
  isSessionSweepEnabled,
  getSessionSweepStaleHours,
} from "../config.js";

const HOUR_MS = 60 * 60 * 1000;

export interface SessionSweepResult {
  success: boolean;
  scanned: number;
  abandoned: number;
  failed: number;
  error?: string;
}

function isStaleActive(session: Session | null, cutoff: number): session is Session {
  if (!session || session.status !== "active") return false;
  const freshness = session.updatedAt ?? session.startedAt;
  if (!freshness) return false;
  const ts = new Date(freshness).getTime();
  return Number.isFinite(ts) && ts < cutoff;
}

export function registerSessionSweepFunction(sdk: IIIClient, kv: StateKV): void {
  sdk.registerFunction(
    "mem::session-sweep",
    async (): Promise<SessionSweepResult> => {
      if (!isSessionSweepEnabled()) {
        return { success: false, scanned: 0, abandoned: 0, failed: 0, error: "session sweep disabled" };
      }
      const cutoff = Date.now() - getSessionSweepStaleHours() * HOUR_MS;
      let sessions: Session[];
      try {
        sessions = await kv.list<Session>(KV.sessions);
      } catch (err) {
        const error = err instanceof Error ? err.message : String(err);
        logger.error("Session sweep scan failed", { error });
        return { success: false, scanned: 0, abandoned: 0, failed: 0, error };
      }

      const abandonedIds: string[] = [];
      let failed = 0;
      for (const candidate of sessions) {
        if (!isStaleActive(candidate, cutoff)) continue;
        try {
          const marked = await withKeyedLock(`obs:${candidate.id}`, async () => {
            const current = await kv.get<Session>(KV.sessions, candidate.id);
            if (!isStaleActive(current, cutoff)) return false;
            await kv.update(KV.sessions, candidate.id, [
              { type: "set", path: "status", value: "abandoned" },
              { type: "set", path: "endedAt", value: new Date().toISOString() },
            ]);
            return true;
          });
          if (marked) abandonedIds.push(candidate.id);
        } catch (err) {
          failed++;
          logger.warn("Session sweep update failed", {
            sessionId: candidate.id,
            error: err instanceof Error ? err.message : String(err),
          });
        }
      }

      if (abandonedIds.length > 0) {
        await safeAudit(kv, "session_sweep", "mem::session-sweep", abandonedIds, {
          abandoned: abandonedIds.length,
          staleHours: getSessionSweepStaleHours(),
        });
        logger.info("Session sweep complete", {
          scanned: sessions.length,
          abandoned: abandonedIds.length,
          failed,
        });
      }
      return {
        success: failed === 0,
        scanned: sessions.length,
        abandoned: abandonedIds.length,
        failed,
        ...(failed > 0 ? { error: `${failed} session update(s) failed` } : {}),
      };
    },
  );
}

