  const vectors = getVectorIndex();
  if (vectors && !vectors.has(obs.id)) {
    await vectorIndexAddGuarded(obs.id, obs.sessionId, obs.title + " " + (obs.narrative || ""), {
      kind: "synthetic",
      logId: obs.id,
    });
  }
}

