  nextOffset: number | null;
  total: number | null;
}

export type GraphCompactBootState = "off" | "pending" | "running" | "done" | "failed";

export interface GraphCompactBootStatus {
  state: GraphCompactBootState;
  phase?: BootPhase;
  processed?: number;
  total?: number | null;
  scanned?: number;
  trimmed?: number;
  idsRemoved?: number;
  startedAt?: string;
  completedAt?: string;
  error?: string;
}

