  consolidationRun: Counter;
  teamShare: Counter;
  auditLog: Counter;
  snapshotCreate: Counter;
  governanceDelete: Counter;
  smartSearchFollowupWithinWindow: Counter;
  readerFailureWithEvidence: Counter;
}

interface Histograms {
  compressionLatency: Histogram;
  searchLatency: Histogram;
  contextTokens: Histogram;
  qualityScore: Histogram;
  embeddingLatency: Histogram;
  vectorSearchLatency: Histogram;
}

type Meter = {
  createCounter: (name: string) => Counter;
  createHistogram: (name: string) => Histogram;
};

let counters: Counters | null = null;
let histograms: Histograms | null = null;

const NOOP_COUNTER: Counter = { add: () => {} };
const NOOP_HISTOGRAM: Histogram = { record: () => {} };

const COUNTER_NAMES: Array<[keyof Counters, string]> = [
  ["observationsTotal", "observations.total"],
  ["compressionSuccess", "compression.success"],
  ["compressionFailure", "compression.failure"],
  ["searchTotal", "search.total"],
  ["dedupSkipped", "dedup.skipped"],
  ["evictionTotal", "eviction.total"],
  ["circuitBreakerOpen", "circuit_breaker.open"],
  ["embeddingSuccess", "embedding.success"],
  ["embeddingFailure", "embedding.failure"],
  ["vectorSearchTotal", "vector_search.total"],
  ["autoForgetTotal", "auto_forget.total"],
  ["profileGenerated", "profile.generated"],
  ["claudeBridgeSync", "claude_bridge.sync"],
  ["graphExtraction", "graph.extraction"],
  ["consolidationRun", "consolidation.run"],
  ["teamShare", "team.share"],
  ["auditLog", "audit.log"],
  ["snapshotCreate", "snapshot.create"],
  ["governanceDelete", "governance.delete"],
  ["smartSearchFollowupWithinWindow", "smart_search.followup_within_window_total"],
  ["readerFailureWithEvidence", "reader_failure_with_evidence_total"],
];

const HISTOGRAM_NAMES: Array<[keyof Histograms, string]> = [
  ["compressionLatency", "compression.latency_ms"],
  ["searchLatency", "search.latency_ms"],
  ["contextTokens", "context.tokens"],
  ["qualityScore", "quality.score"],
  ["embeddingLatency", "embedding.latency_ms"],
  ["vectorSearchLatency", "vector_search.latency_ms"],
];

// Accessors so functions outside `initMetrics`'s closure can record into
// the same counter / histogram instances after init. Before init both
// return no-op fallbacks so call sites stay safe in tests and during
// the boot window.
export function getCounters(): Counters {
  if (counters) return counters;
  return Object.fromEntries(
    COUNTER_NAMES.map(([key]) => [key, NOOP_COUNTER]),
  ) as unknown as Counters;
}

export function getHistograms(): Histograms {
  if (histograms) return histograms;
  return Object.fromEntries(
    HISTOGRAM_NAMES.map(([key]) => [key, NOOP_HISTOGRAM]),
  ) as unknown as Histograms;
}

export function initMetrics(getMeter?: (name: string) => Meter): {
  counters: Counters;
  histograms: Histograms;
} {
  const meter = getMeter?.("agentmemory");

  counters = Object.fromEntries(
    COUNTER_NAMES.map(([key, name]) => [
      key,
      meter ? meter.createCounter(name) : NOOP_COUNTER,
    ]),
  ) as unknown as Counters;

  histograms = Object.fromEntries(
    HISTOGRAM_NAMES.map(([key, name]) => [
      key,
      meter ? meter.createHistogram(name) : NOOP_HISTOGRAM,
    ]),
  ) as unknown as Histograms;

  return { counters, histograms };
}

export function scoreCompression(obs: {
  type?: string;
  title?: string;
  facts?: string[];
  narrative?: string;
  concepts?: string[];
  importance?: number;
}): number {
  let score = 0;
  if (obs.facts && obs.facts.length > 0) score += 25;
  if (obs.facts && obs.facts.length >= 3) score += 10;
  if (obs.narrative && obs.narrative.length >= 20) score += 20;
  if (obs.narrative && obs.narrative.length >= 50) score += 5;
  if (obs.title && obs.title.length >= 5 && obs.title.length <= 120) score += 15;
  if (obs.concepts && obs.concepts.length > 0) score += 15;
  if (obs.importance && obs.importance >= 1 && obs.importance <= 10) score += 10;
  return Math.min(100, score);
}

export function scoreSummary(summary: {
  title?: string;
  narrative?: string;
  keyDecisions?: string[];
  filesModified?: string[];
  concepts?: string[];
}): number {
  let score = 0;
  if (summary.title && summary.title.length >= 5) score += 20;
  if (summary.narrative && summary.narrative.length >= 20) score += 25;
  if (summary.narrative && summary.narrative.length >= 100) score += 5;
  if (summary.keyDecisions && summary.keyDecisions.length > 0) score += 20;
  if (summary.filesModified && summary.filesModified.length > 0) score += 15;
  if (summary.concepts && summary.concepts.length > 0) score += 15;
  return Math.min(100, score);
}

export function scoreContextRelevance(
  context: string,
  project: string,
): number {
  let score = 0;
  if (context.length > 0) score += 20;
  if (project && context.toLowerCase().includes(project.toLowerCase())) score += 20;
  if (context.includes("<")) score += 15;
  const sectionCount = (context.match(/<\w+>/g) || []).length;
  if (sectionCount >= 2) score += 15;
  if (sectionCount >= 4) score += 10;
  if (context.length >= 100) score += 10;
  if (context.length >= 500) score += 10;
  return Math.min(100, score);
}

import type { FunctionMetrics } from "../types.js";
import type { StateKV } from "../state/kv.js";
import { KV } from "../state/schema.js";

export class MetricsStore {
  private cache = new Map<string, FunctionMetrics>();
  private qualityCallCounts = new Map<string, number>();

  constructor(private kv: StateKV) {}

  async record(
    functionId: string,
    latencyMs: number,
    success: boolean,
    qualityScore?: number,
  ): Promise<void> {
    let m = this.cache.get(functionId);
    if (!m) {
      m = (await this.kv.get<FunctionMetrics>(KV.metrics, functionId)) ?? {
        functionId,
        totalCalls: 0,
        successCount: 0,
        failureCount: 0,
        avgLatencyMs: 0,
        avgQualityScore: 0,
      };
    }

    const prev = m.totalCalls;
    m.totalCalls += 1;
    m.avgLatencyMs = (m.avgLatencyMs * prev + latencyMs) / m.totalCalls;
    if (success) {
      m.successCount += 1;
    } else {
      m.failureCount += 1;
    }
    if (qualityScore !== undefined) {
      const prevQualityCalls = this.qualityCallCounts.get(functionId) || 0;
      m.avgQualityScore =
        (m.avgQualityScore * prevQualityCalls + qualityScore) /
        (prevQualityCalls + 1);
      this.qualityCallCounts.set(functionId, prevQualityCalls + 1);
    }

    this.cache.set(functionId, m);
    await this.kv.set(KV.metrics, functionId, m).catch(() => {});
  }

  async get(functionId: string): Promise<FunctionMetrics | null> {
    return (
      this.cache.get(functionId) ??
      (await this.kv.get<FunctionMetrics>(KV.metrics, functionId))
    );
  }

  async getAll(): Promise<FunctionMetrics[]> {
    const kvMetrics = await this.kv
      .list<FunctionMetrics>(KV.metrics)
      .catch(() => []);
    const merged = new Map<string, FunctionMetrics>();
    for (const m of kvMetrics) merged.set(m.functionId, m);
    for (const [id, m] of this.cache) merged.set(id, m);
    return Array.from(merged.values());
  }
}

