"""Correction engine — detect weak/wrong answers and upgrade them."""
from __future__ import annotations

import re
from typing import Any


class CorrectionEngine:
    """Second-pass correction when the model answer is weak."""

    FAILURE_PHRASES = (
        "couldn't produce a clear answer",
        "could not produce a clear answer",
        "i don't know how to",
        "as an ai language model",
        "i cannot help with that",
        "sorry, i can't assist",
    )

    def needs_correction(self, answer: str, *, quality_ok: bool = True) -> bool:
        text = (answer or "").strip().lower()
        if not text:
            return True
        if not quality_ok:
            return True
        if any(p in text for p in self.FAILURE_PHRASES):
            return True
        if len(text) < 8:
            return True
        if re.search(r"(.)\1{10,}", text):
            return True
        return False

    def correct(
        self,
        message: str,
        answer: str,
        *,
        solution: dict[str, Any] | None = None,
        intent: str = "",
    ) -> dict[str, Any]:
        solution = dict(solution or {})
        original = (answer or "").strip()

        # Prefer structured solution when available.
        sol = str(solution.get("answer") or "").strip()
        if sol and self.needs_correction(original, quality_ok=False):
            return {
                "corrected": True,
                "answer": sol,
                "reason": "replaced_with_solution_engine",
            }

        if not self.needs_correction(original):
            return {"corrected": False, "answer": original, "reason": "ok"}

        if sol:
            return {
                "corrected": True,
                "answer": sol,
                "reason": "replaced_with_solution_engine",
            }

        return {"corrected": False, "answer": original, "reason": "leave_to_brain"}

"""Confidence scoring for chat answers."""
from __future__ import annotations

from typing import Any


class ConfidenceEngine:
    """Estimate confidence that the answer solves the user ask."""

    def score(
        self,
        *,
        intent: str = "",
        quality: dict[str, Any] | None = None,
        solution: dict[str, Any] | None = None,
        used_model: bool = False,
        corrected: bool = False,
    ) -> dict[str, Any]:
        quality = dict(quality or {})
        solution = dict(solution or {})
        base = 0.55

        if intent in {"greeting", "morning", "evening", "afternoon", "identity", "thanks", "goodbye"}:
            base = 0.95
        elif solution.get("solved") and solution.get("complete"):
            base = 0.88
        elif solution.get("solved"):
            base = 0.78
        elif used_model:
            base = 0.62

        qscore = float(quality.get("score") or 0.5)
        conf = (base * 0.65) + (qscore * 0.35)
        if corrected:
            conf = max(conf, 0.7)
        if quality.get("ok") is False:
            conf = min(conf, 0.45)

        conf = max(0.05, min(0.99, conf))
        return {
            "confidence": round(conf, 3),
            "level": "high" if conf >= 0.8 else ("medium" if conf >= 0.6 else "low"),
        }

"""Detect canned solution-template replies that must never reach the user."""
from __future__ import annotations

import re

_STUB_SMELL = re.compile(
    r"(?is)("
    r"the issue may come from incorrect assumptions|"
    r"here'?s the direct path for\s*:|"
    r"solve\s*:\s*.{0,200}\b(understand|acknowledge|answer|next\s*step)\b|"
    r"clarify goal, then give a direct actionable answer|"
    r"the problem may be caused by environment or configuration|"
    r"the current approach may need redesign"
    r")"
)


def is_solution_stub(text: str) -> bool:
    """True for generic Solve:/assumption outline dumps."""
    t = (text or "").strip()
    if not t:
        return False
    if "**Quick checks**" in t or "```" in t or "Step-by-step for:" in t:
        return False
    if _STUB_SMELL.search(t):
        if len(t) < 400 and not any(h in t for h in ("**Fix plan**", "**Quick checks**", "Step-by-step")):
            return True
        if re.search(r"(?i)\b(solve|fix|accomplish|understand)\s*:\s*.{0,150}\b(understand|acknowledge|answer)\b", t):
            return True
    # Numbered outline that just echoes the user ask
    if re.search(r"(?i)\b(solve|fix|accomplish|understand)\s*:", t) and re.search(
        r"(?m)^\s*1\.\s+\w+", t
    ):
        if len(t) < 420 and t.count("\n") <= 8:
            return True
    return False

"""Research route helper — returns a user-facing string answer."""
from __future__ import annotations

from typing import Any


class ResearchEngine:
    """Chat-facing research engine with a string `.research()` API."""

    def research(self, message: str, **_: Any) -> str:
        q = (message or "").strip()
        if not q:
            return "What would you like me to research?"

        try:
            from om_ai.core.research import ResearchEngine as CoreResearchEngine

            state = CoreResearchEngine().research(q)
            summary = getattr(state, "summary", None) or getattr(state, "answer", None)
            if summary:
                return str(summary).strip()
            sources = getattr(state, "sources", None) or []
            if sources:
                lines = [f"Research notes for: {q}", ""]
                for i, src in enumerate(list(sources)[:5], 1):
                    title = getattr(src, "title", None) or (src.get("title") if isinstance(src, dict) else None) or f"Source {i}"
                    lines.append(f"{i}. {title}")
                return "\n".join(lines)
        except Exception:
            pass

        return (
            f"I looked into “{q}”. "
            "I can dig deeper if you share more specifics "
            "(scope, constraints, or what outcome you need)."
        )

"""Safety filter for OM Chat Intelligence."""
from __future__ import annotations

import re
from typing import Any


class SafetyFilter:
    """Block obvious unsafe / leaked internal content from user-facing replies."""

    BLOCK_PATTERNS = [
        re.compile(r"\b(api[_-]?key|secret[_-]?key|private[_-]?key)\s*[:=]\s*\S+", re.I),
        re.compile(r"\bBEGIN (RSA |OPENSSH )?PRIVATE KEY\b"),
    ]
    INTERNAL_LEAK = re.compile(
        r"\b(system prompt|hidden chain|trace_id|OM_INTERNAL|tokenizer special)\b",
        re.I,
    )

    def filter(self, answer: str) -> dict[str, Any]:
        text = (answer or "").strip()
        flags: list[str] = []

        for pat in self.BLOCK_PATTERNS:
            if pat.search(text):
                flags.append("secret_leak")
                text = pat.sub("[redacted]", text)

        if self.INTERNAL_LEAK.search(text):
            flags.append("internal_leak")
            # Soft scrub — drop suspicious lines
            lines = []
            for line in text.splitlines():
                if self.INTERNAL_LEAK.search(line):
                    continue
                lines.append(line)
            text = "\n".join(lines).strip()

        if not text and flags:
            text = "I can help with that in a safer way — please rephrase your request."

        return {
            "answer": text,
            "flags": flags,
            "safe": "secret_leak" not in flags,
        }

"""Conversation memory for OM Chat Intelligence."""
from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any


@dataclass
class Turn:
    role: str
    content: str
    intent: str = ""
    timestamp: str = field(default_factory=lambda: datetime.utcnow().isoformat())

    def to_dict(self) -> dict[str, Any]:
        return {
            "role": self.role,
            "content": self.content,
            "intent": self.intent,
            "timestamp": self.timestamp,
        }


class ConversationMemory:
    """Per-session short-term conversation memory."""

    def __init__(self, *, max_turns: int = 40) -> None:
        self.max_turns = max_turns
        self._sessions: dict[str, deque[Turn]] = defaultdict(
            lambda: deque(maxlen=self.max_turns)
        )

    def session_id(self, tenant_id: str = "default", actor: str = "") -> str:
        return f"{tenant_id}:{actor or 'anon'}"

    def add(
        self,
        session: str,
        role: str,
        content: str,
        *,
        intent: str = "",
    ) -> None:
        text = (content or "").strip()
        if not text:
            return
        self._sessions[session].append(
            Turn(role=role, content=text[:4000], intent=intent)
        )

    def history(self, session: str, *, limit: int = 12) -> list[dict[str, Any]]:
        turns = list(self._sessions.get(session) or [])
        return [t.to_dict() for t in turns[-limit:]]

    def recent_user_topics(self, session: str, *, limit: int = 5) -> list[str]:
        out: list[str] = []
        for t in reversed(list(self._sessions.get(session) or [])):
            if t.role == "user":
                out.append(t.content[:160])
                if len(out) >= limit:
                    break
        return list(reversed(out))

    def summary(self, session: str) -> str:
        turns = self.history(session, limit=6)
        if not turns:
            return ""
        parts = [f"{t['role']}: {t['content'][:120]}" for t in turns]
        return " | ".join(parts)[:800]

    def clear(self, session: str) -> None:
        self._sessions.pop(session, None)

