    OM Dataset Intelligence Brain.
    """


    def __init__(self):

        self.quality = (
            DatasetQualityEvaluator()
        )

        self.duplicate = (
            DuplicateDetector()
        )

        self.filter = (
            ContaminationFilter()
        )

        self.validator = (
