"""STEP 29 — Knowledge gap registry."""
from __future__ import annotations

from collections import Counter
from typing import Any


class KnowledgeGapRegistry:
    def __init__(self) -> None:
        self._gaps: Counter[str] = Counter()
        self._examples: dict[str, list[str]] = {}

    def record(self, gap: str, example: str = "") -> None:
        g = (gap or "general").strip() or "general"
        self._gaps[g] += 1
        if example:
            self._examples.setdefault(g, []).append(example[:300])
            self._examples[g] = self._examples[g][-20:]

    def top(self, n: int = 10) -> list[dict[str, Any]]:
        return [
            {"gap": k, "count": v, "examples": list(self._examples.get(k) or [])[:3]}
            for k, v in self._gaps.most_common(n)
        ]

    def snapshot(self) -> dict[str, Any]:
        return {"gaps": self.top(), "total": int(sum(self._gaps.values()))}

"""STEP 29 — Improvement loop."""
from __future__ import annotations

from typing import Any


class ImprovementLoop:
    def run(
        self,
        *,
        failures: list[dict[str, Any]] | None = None,
        gaps: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        failures = list(failures or [])
        gaps = list(gaps or [])
        dataset = []
        for f in failures[:20]:
            dataset.append(
                {
                    "input": f.get("message") or "",
                    "bad_output_signal": f.get("issues") or [],
                    "target_skill": f.get("gap") or "conversation",
                }
            )
        for g in gaps[:10]:
            for ex in g.get("examples") or []:
                dataset.append({"input": ex, "target_skill": g.get("gap"), "source": "gap"})
        return {
            "dataset_size": len(dataset),
            "dataset": dataset[:50],
            "action": "train" if dataset else "noop",
            "flow": "bad_answer→gap→dataset→train→improve",
        }

"""STEP 29 — Failure analyzer."""
from __future__ import annotations

from typing import Any


class FailureAnalyzer:
    def analyze(self, message: str, answer: str, *, quality: dict[str, Any] | None = None) -> dict[str, Any]:
        quality = dict(quality or {})
        text = (answer or "").strip()
        issues: list[str] = []
        if not text:
            issues.append("empty_answer")
        if len(text) < 20:
            issues.append("too_short")
        if quality.get("ok") is False or float(quality.get("score") or 1) < 0.5:
            issues.append("low_quality")
        if "couldn't produce" in text.lower() or "clear answer" in text.lower():
            issues.append("fallback_phrase")
        gap = "conversation"
        low = (message or "").lower()
        if any(w in low for w in ("code", "react", "python", "bug", "error")):
            gap = "coding"
        elif any(w in low for w in ("why", "explain", "compare")):
            gap = "reasoning"
        return {
            "failed": bool(issues),
            "issues": issues,
            "gap": gap if issues else "",
            "severity": round(min(1.0, 0.3 * len(issues)), 2),
        }

