from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from typing import Any
import uuid


@dataclass
class FeedbackEvent:
    message: str
    answer: str
    rating: float = 0.0
    reason: str = ""
    event_id: str = field(default_factory=lambda: str(uuid.uuid4())[:8])
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())

    def to_dict(self) -> dict[str, Any]:
        return {
            "event_id": self.event_id,
            "message": self.message[:500],
            "answer": self.answer[:1000],
            "rating": self.rating,
            "reason": self.reason,
            "created_at": self.created_at,
        }


class FeedbackCollector:
    def __init__(self) -> None:
        self._events: list[FeedbackEvent] = []

    def add(self, message: str, answer: str, *, rating: float = 0.0, reason: str = "") -> dict[str, Any]:
        ev = FeedbackEvent(message=message, answer=answer, rating=rating, reason=reason)
        self._events.append(ev)
        if len(self._events) > 500:
            self._events = self._events[-500:]
        return ev.to_dict()

    def recent(self, limit: int = 20) -> list[dict[str, Any]]:
        return [e.to_dict() for e in self._events[-limit:]]

    def negatives(self) -> list[dict[str, Any]]:
        return [e.to_dict() for e in self._events if e.rating < 0.5 or e.reason]

"""Rank and compress retrieved context for the model prompt."""
from __future__ import annotations

from typing import Any


class ContextIntelligence:

    def process(self, contexts: Any, query: str) -> list[Any]:
        if not contexts:
            return []

        if not isinstance(contexts, (list, tuple)):
            contexts = [contexts]

        words = set((query or "").lower().split())
        result: list[tuple[int, Any]] = []

        for item in contexts:
            if item is None or item == "":
                continue
            # Prefer summary strings over raw ResearchSource objects
            if hasattr(item, "summary_context"):
                text_src = getattr(item, "summary_context") or ""
                if text_src:
                    item = text_src
            elif hasattr(item, "content") and hasattr(item, "title"):
                item = f"{getattr(item, 'title', '')}\n{getattr(item, 'content', '')[:1500]}"

            text = str(item).lower()
            score = sum(1 for w in words if w and w in text)
            result.append((score, item))

        result.sort(key=lambda x: x[0], reverse=True)
        return [x[1] for x in result[:10]]

"""Detect corrupted / meaningless model output and nonsense user asks."""
from __future__ import annotations

import re


class GarbageDetector:

    _RANDOM_REQUEST = re.compile(
        r"\b("
        r"generate\s+random\s+words?"
        r"|random\s+(?:gibberish|nonsense|garbage|text|string)"
        r"|output\s+meaningless"
        r"|spew\s+random"
        r"|corrupted\s+content"
        r")\b",
        re.I,
    )

    _REFUSAL = (
        "I can help generate text, but I will not output "
        "meaningless corrupted content."
    )

    def is_nonsense_request(self, message: str) -> bool:
        text = (message or "").strip()
        if not text:
            return False
        return bool(self._RANDOM_REQUEST.search(text))

    def refusal_message(self) -> str:
        return self._REFUSAL

    def check(self, text: str) -> bool:
        """Return True when text looks like garbage / corrupted output."""
        if not text:
            return False

        words = text.split()
        if not words:
            return True

        # High unique-token density → word salad
        if len(words) > 40:
            unique = len({w.lower() for w in words})
            if unique / len(words) > 0.85:
                return True

        # Repeated stutter / loop
        low = text.lower()
        if re.search(r"\b(\w+)(?:\s+\1){4,}\b", low):
            return True

        # Replacement chars / tokenizer junk
        if text.count("�") >= 2:
            return True

        # Weird casing soup
        weird = 0
        for word in words:
            if len(word) > 28:
                weird += 1
                continue
            up = sum(1 for c in word if c.isupper())
            lo = sum(1 for c in word if c.islower())
            if up >= 3 and lo >= 3 and not word.isupper():
                weird += 1
        if len(words) >= 12 and weird / len(words) > 0.2:
            return True

        # Fragment soup: many commas, no sentence end
        if (
            len(words) >= 12
            and text.count(",") >= 5
            and text.count(".") == 0
            and "http" not in low
        ):
            return True

        return False

