class ContextFilter:


    BLOCKED = [

        "tool:",
        "traceback",
        "README.md",
        "package.json",
        "file structure",
        "internal path",
    ]


    def clean(
        self,
        data
    ):


        if not data:
            return []


        if isinstance(data,dict):

            data=[
                data
            ]


        cleaned=[]


        for item in data:


            text=str(item)


            blocked=False


