"""Task graph with dependency ordering."""
from __future__ import annotations

from collections import deque

from .task import Task, TaskStatus


class TaskGraph:
    def __init__(self) -> None:
        self._tasks: dict[str, Task] = {}

    def add(self, task: Task) -> None:
        self._tasks[task.task_id] = task

    def get(self, task_id: str) -> Task | None:
        return self._tasks.get(task_id)

    def all_tasks(self) -> list[Task]:
        return list(self._tasks.values())

    def ready_tasks(self) -> list[Task]:
        ready: list[Task] = []
        for task in self._tasks.values():
            if task.status not in {TaskStatus.PENDING, TaskStatus.READY}:
                continue
            if self._deps_satisfied(task):
                task.status = TaskStatus.READY
                ready.append(task)
        return ready

    def _deps_satisfied(self, task: Task) -> bool:
        for dep_id in task.depends_on:
            dep = self._tasks.get(dep_id)
            if dep is None or dep.status != TaskStatus.SUCCEEDED:
                return False
        return True

    def topological_order(self) -> list[Task]:
        indegree: dict[str, int] = {tid: 0 for tid in self._tasks}
        for task in self._tasks.values():
            for dep in task.depends_on:
                if dep in indegree:
                    indegree[task.task_id] += 1
        q: deque[str] = deque(t for t, d in indegree.items() if d == 0)
        order: list[Task] = []
        while q:
            tid = q.popleft()
            order.append(self._tasks[tid])
            for task in self._tasks.values():
                if tid in task.depends_on:
                    indegree[task.task_id] -= 1
                    if indegree[task.task_id] == 0:
                        q.append(task.task_id)
        if len(order) != len(self._tasks):
            raise ValueError("task graph contains a cycle")
        return order

    def mark_cancelled_recursive(self, task_id: str) -> None:
        task = self._tasks.get(task_id)
        if not task:
            return
        task.status = TaskStatus.CANCELLED
        task.touch()
        for t in self._tasks.values():
            if task_id in t.depends_on and t.status == TaskStatus.PENDING:
                self.mark_cancelled_recursive(t.task_id)

"""Simple recovery strategies for failed tasks."""
from __future__ import annotations

from .task import Task, TaskStatus


class RecoveryEngine:
    def __init__(self, *, max_retries: int = 2) -> None:
        self.max_retries = max_retries
        self._attempts: dict[str, int] = {}

    def should_retry(self, task: Task) -> bool:
        count = self._attempts.get(task.task_id, 0)
        return task.status == TaskStatus.FAILED and count < self.max_retries

    def prepare_retry(self, task: Task) -> None:
        self._attempts[task.task_id] = self._attempts.get(task.task_id, 0) + 1
        task.status = TaskStatus.READY
        task.error = None
        task.touch()

"""Verify task postconditions after execution."""
from __future__ import annotations

from typing import Any

from .task import Task, TaskStatus


class ExecutionVerifier:
    def verify(self, task: Task, output: Any) -> tuple[bool, str]:
        if task.status == TaskStatus.CANCELLED:
            return False, "task cancelled"

        expected = task.postconditions or {}
        if not expected:
            if output is None and task.capability:
                return False, "expected non-null output for capability task"
            return True, ""

        if "non_empty" in expected and expected["non_empty"]:
            if output is None or output == "" or output == {}:
                return False, "output empty"

        if "contains" in expected:
            needle = str(expected["contains"])
            if needle not in str(output):
                return False, f"output missing {needle!r}"

        if "returncode" in expected and isinstance(output, dict):
            if output.get("returncode") != expected["returncode"]:
                return False, "unexpected returncode"

        return True, ""

"""Cancellation tokens for companion sessions."""
from __future__ import annotations

import threading
import uuid


class CancellationToken:
    def __init__(self) -> None:
        self._event = threading.Event()

    def cancel(self) -> None:
        self._event.set()

    @property
    def is_cancelled(self) -> bool:
        return self._event.is_set()

    def raise_if_cancelled(self) -> None:
        if self.is_cancelled:
            raise RuntimeError("operation cancelled")


class CancellationManager:
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._tokens: dict[str, CancellationToken] = {}

    def create(self, session_id: str | None = None) -> tuple[str, CancellationToken]:
        sid = session_id or str(uuid.uuid4())
        token = CancellationToken()
        with self._lock:
            self._tokens[sid] = token
        return sid, token

    def get(self, session_id: str) -> CancellationToken | None:
        with self._lock:
            return self._tokens.get(session_id)

    def cancel(self, session_id: str) -> bool:
        token = self.get(session_id)
        if token is None:
            return False
        token.cancel()
        return True

