"""STEP 94.15 — Learning Scheduler.

Pull knowledge gaps / curriculum topics into a runnable learning queue.
"""
from __future__ import annotations

import json
import time
import uuid
from pathlib import Path
from typing import Any


def _root() -> Path:
    return Path(__file__).resolve().parents[3] / "data" / "om_learning" / "scheduler"


class LearningScheduler:
    """Queue background learning jobs for the autonomous loop."""

    def __init__(self, root: Path | str | None = None) -> None:
        self.root = Path(root) if root else _root()
        self.root.mkdir(parents=True, exist_ok=True)
        self.queue_path = self.root / "jobs.jsonl"
        self.state_path = self.root / "state.json"

    def _state(self) -> dict[str, Any]:
        if not self.state_path.is_file():
            return {"enqueued": 0, "completed": 0, "failed": 0, "running": False}
        try:
            return json.loads(self.state_path.read_text(encoding="utf-8"))
        except Exception:
            return {"enqueued": 0, "completed": 0, "failed": 0, "running": False}

    def _save_state(self, state: dict[str, Any]) -> None:
        self.state_path.write_text(json.dumps(state, indent=2), encoding="utf-8")

    def enqueue(
        self,
        question: str,
        *,
        source: str = "manual",
        priority: int = 5,
        domain: str = "software",
        meta: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        q = (question or "").strip()
        if not q:
            raise ValueError("question required")
        job = {
            "id": f"learn_{uuid.uuid4().hex[:10]}",
            "question": q,
            "source": source,
            "priority": int(priority),
            "domain": domain,
            "status": "queued",
            "meta": meta or {},
            "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        with self.queue_path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(job, ensure_ascii=False) + "\n")
        st = self._state()
        st["enqueued"] = int(st.get("enqueued") or 0) + 1
        self._save_state(st)
        return job

    def enqueue_from_gaps(self, *, limit: int = 10) -> list[dict[str, Any]]:
        from om_ai.core.distillation import KnowledgeGapCollector, CurriculumGenerator

        gaps = KnowledgeGapCollector().top_gaps(limit=limit)
        if not gaps:
            return []
        cur = CurriculumGenerator().from_gaps(gaps, per_gap=1)
        out = []
        for q in cur.get("questions") or []:
            out.append(
                self.enqueue(
                    str(q.get("question") or ""),
                    source="gaps",
                    priority=int(q.get("priority") or 5),
                    domain=str(q.get("domain") or "software"),
                    meta={"curriculum_id": cur.get("curriculum_id"), "level": q.get("level")},
                )
            )
        return out

    def enqueue_topic(self, topic: str, *, count: int = 5, domain: str = "software") -> list[dict[str, Any]]:
        from om_ai.core.distillation import CurriculumGenerator

        cur = CurriculumGenerator().generate(topic, domain=domain, count=count)
        out = []
        for q in cur.get("questions") or []:
            out.append(
                self.enqueue(
                    str(q.get("question") or ""),
                    source="topic",
                    priority=int(q.get("priority") or 5),
                    domain=domain,
                    meta={"curriculum_id": cur.get("curriculum_id"), "topic": topic},
                )
            )
        return out

    def _read(self) -> list[dict[str, Any]]:
        if not self.queue_path.is_file():
            return []
        rows = []
        for line in self.queue_path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except Exception:
                continue
        return rows

    def _write(self, rows: list[dict[str, Any]]) -> None:
        with self.queue_path.open("w", encoding="utf-8") as f:
            for row in rows:
                f.write(json.dumps(row, ensure_ascii=False) + "\n")

    def pending(self) -> list[dict[str, Any]]:
        rows = [r for r in self._read() if r.get("status") == "queued"]
        rows.sort(key=lambda r: (int(r.get("priority") or 99), str(r.get("created_at") or "")))
        return rows

    def next_batch(self, limit: int = 5) -> list[dict[str, Any]]:
        return self.pending()[: max(1, int(limit))]

    def mark(self, job_id: str, status: str, *, error: str = "") -> None:
        rows = self._read()
        for row in rows:
            if row.get("id") == job_id:
                row["status"] = status
                row["finished_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
                if error:
                    row["error"] = error

"""Training queue — stage distilled SFT/DPO examples for OM training."""
from __future__ import annotations

import json
import time
import uuid
from pathlib import Path
from typing import Any


def _root() -> Path:
    return Path(__file__).resolve().parents[3] / "data" / "om_learning" / "training_queue"


class TrainingQueue:
    """Persist training jobs produced by distillation for later SFT/DPO."""

    def __init__(self, root: Path | str | None = None) -> None:
        self.root = Path(root) if root else _root()
        self.root.mkdir(parents=True, exist_ok=True)
        self.path = self.root / "queue.jsonl"
        self.buffer = (
            Path(__file__).resolve().parents[3]
            / "data"
            / "om-memory"
            / "advanced_learning"
            / "training_buffer.jsonl"
        )

    def enqueue_from_distill(self, distill_result: dict[str, Any]) -> dict[str, Any] | None:
        if not isinstance(distill_result, dict):
            return None
        dataset = distill_result.get("dataset") or distill_result
        sft = dataset.get("sft") if isinstance(dataset, dict) else None
        # collect_and_save nests dataset under result
        if not sft and isinstance(distill_result.get("dataset"), dict):
            sft = distill_result["dataset"].get("sft")
        if not sft and distill_result.get("sft"):
            sft = distill_result.get("sft")
        # After collect_and_save, structure is result["dataset"]["sft"]
        if not sft:
            inner = distill_result.get("result") if isinstance(distill_result.get("result"), dict) else {}
            sft = (inner.get("dataset") or {}).get("sft")
        if not sft:
            return None
        job = {
            "id": f"train_{uuid.uuid4().hex[:10]}",
            "type": "sft",
            "status": "queued",
            "run_id": distill_result.get("run_id") or (dataset.get("run_id") if isinstance(dataset, dict) else None),
            "instruction": sft.get("instruction") or sft.get("prompt"),
            "example": sft,
            "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        with self.path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(job, ensure_ascii=False) + "\n")
        # Also append to shared OM training buffer
        self.buffer.parent.mkdir(parents=True, exist_ok=True)
        with self.buffer.open("a", encoding="utf-8") as f:
            f.write(
                json.dumps(
                    {
                        "type": "sft",
                        "messages": sft.get("messages"),
                        "score": (sft.get("meta") or {}).get("score"),
                        "source": "om_learn_queue",
                    },
                    ensure_ascii=False,
                )
                + "\n"
            )
        return job

    def list_jobs(self, *, limit: int = 50) -> list[dict[str, Any]]:
        if not self.path.is_file():
            return []
        rows = []
        for line in self.path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except Exception:
                continue
        return rows[-limit:]

    def pending_count(self) -> int:
        return sum(1 for j in self.list_jobs(limit=10000) if j.get("status") == "queued")

    def status(self) -> dict[str, Any]:
        jobs = self.list_jobs(limit=10000)
        return {
            "module": "training_queue",
            "total": len(jobs),
            "queued": sum(1 for j in jobs if j.get("status") == "queued"),
            "path": str(self.path),
            "training_buffer": str(self.buffer),
        }

"""Distillation worker — run teacher harvest jobs for the learning loop."""
from __future__ import annotations

from typing import Any, Callable


class DistillationWorker:
    """
    Knowledge Gaps / Scheduler jobs
            |
            ↓
    Distillation Engine / TeacherManager
            |
            ↓
    SFT/DPO artifacts
    """

    def __init__(
        self,
        *,
        harvest_fn: Callable[[str], Any] | None = None,
    ) -> None:
        self.harvest_fn = harvest_fn

    def _default_harvest(self, question: str) -> dict[str, Any]:
        from om_ai.core.distillation import create_teacher_manager

        manager = create_teacher_manager()
        return manager.collect_and_save(question)

    def run_job(self, question: str) -> dict[str, Any]:
        q = (question or "").strip()
        if not q:
            return {"ok": False, "error": "empty_question"}
        fn = self.harvest_fn or self._default_harvest
        try:
            result = fn(q)
            return {
                "ok": True,
                "question": q,
                "result": result,
                "run_id": (result or {}).get("run_id") if isinstance(result, dict) else None,
                "exported": ((result or {}).get("export") or {}).get("exported")
                if isinstance(result, dict)
                else 0,
            }
        except Exception as exc:
            return {"ok": False, "question": q, "error": str(exc)}

    def run_batch(self, questions: list[str]) -> dict[str, Any]:
        items = []
        ok = 0
        for q in questions or []:
            item = self.run_job(q)
            items.append(item)
            if item.get("ok"):
                ok += 1
        return {"ok": ok, "failed": len(items) - ok, "items": items}

