                "mode": "continue",
                "hint": "Mirror the unfinished thought and invite the next beat.",
                "example": "You were fixing the server yesterday. What happened next?",
            }
        return {
            "mode": "companion",
            "hint": "Speak like a loyal friend: direct, short, human. No helpdesk lines.",
            "example": "",
        }

