class DatasetIndex:

    def __init__(self) -> None:

        self.by_intent: dict[
            str,
            set[str]
        ] = defaultdict(set)

        self.by_domain: dict[
            str,
            set[str]
        ] = defaultdict(set)

        self.by_type: dict[
            str,
            set[str]
        ] = defaultdict(set)

        self.by_language: dict[
            str,
            set[str]
        ] = defaultdict(set)

        self.by_tag: dict[
            str,
            set[str]
        ] = defaultdict(set)

    # ---------------------------------------------------------
    # Add
    # ---------------------------------------------------------

    def add(
        self,
        item: DatasetItem,
    ) -> None:

        self.by_intent[
            item.intent
        ].add(
            item.item_id
        )

        self.by_domain[
            item.domain
        ].add(
            item.item_id
        )

        self.by_type[
            item.dataset_type.value
        ].add(
            item.item_id
        )

        self.by_language[
            item.language
        ].add(
            item.item_id
        )

        for tag in item.tags:

            self.by_tag[
                tag.lower()
            ].add(
                item.item_id
            )

    # ---------------------------------------------------------
    # Bulk
    # ---------------------------------------------------------

    def add_many(
        self,
        items: Iterable[DatasetItem],
    ) -> None:

        for item in items:
            self.add(item)

    # ---------------------------------------------------------
    # Query
    # ---------------------------------------------------------

    def ids_for_intent(
        self,
        intent: str,
    ) -> set[str]:

        return set(
            self.by_intent.get(
                intent,
                set(),
            )
        )

    def ids_for_domain(
        self,
        domain: str,
    ) -> set[str]:

        return set(
            self.by_domain.get(
