    def save(
        self,
        item: DatasetItem,
    ) -> DatasetItem:

        validated = self.validator.validate(
            item
        )

        return self.store.save(
            validated
        )

    def save_many(
        self,
        items: Iterable[DatasetItem],
    ) -> int:

        count = 0

        for item in items:

            self.save(item)

            count += 1

        return count

    # ---------------------------------------------------------
    # Read
    # ---------------------------------------------------------

    def get(
        self,
        item_id: str,
    ) -> DatasetItem | None:

        return self.store.get(
            item_id
        )

    # ---------------------------------------------------------
    # Delete
    # ---------------------------------------------------------

    def delete(
        self,
        item_id: str,
    ) -> bool:

        return self.store.delete(
            item_id
        )

    # ---------------------------------------------------------
    # Count
    # ---------------------------------------------------------

    def count(self) -> int:

        return self.store.count()

