class DifficultyEngine:
    """
    OM Dynamic Difficulty Intelligence.
    """



    def __init__(self):

        self.analyzer = (
            ComplexityAnalyzer()
        )

        self.scorer = (
            ComplexityScoringEngine()
        )



    def evaluate(
        self,
        text: str
    ):


        dimensions = (
            self.analyzer
            .analyze_text(
                text
            )
        )


        overall = (
            self.scorer
            .calculate(
                dimensions
            )
        )


        level = (
            self.scorer
            .classify(
                overall
            )
        )


        return ComplexityScore(

            **dimensions,

            overall_score=overall,

            level=level

        )

