"""Streaming / cancellable TTS playback controller."""
from __future__ import annotations

import logging
import subprocess
import threading
from typing import Any, Callable

from .speech_synthesizer import SpeechSynthesizer

logger = logging.getLogger(__name__)


class StreamingTTS:
    def __init__(self, synthesizer: SpeechSynthesizer | None = None) -> None:
        self.synth = synthesizer or SpeechSynthesizer()
        self._proc: subprocess.Popen | None = None
        self._thread: threading.Thread | None = None
        self._cancel = threading.Event()
        self._speaking = False
        self.on_started: Callable[[], None] | None = None
        self.on_completed: Callable[[], None] | None = None
        self.on_cancelled: Callable[[], None] | None = None

    @property
    def speaking(self) -> bool:
        return self._speaking

    def speak(self, text: str, *, blocking: bool = False) -> dict[str, Any]:
        self.cancel()
        self._cancel.clear()
        text = (text or "").strip()
        if not text:
            return {"ok": False, "reason": "empty"}

        def _run() -> None:
            self._speaking = True
            if self.on_started:
                try:
                    self.on_started()
                except Exception:
                    pass
            try:
                # Prefer streaming OS say for barge-in cancel via kill
                import shutil

                if shutil.which("say") and not self._cancel.is_set():
                    cmd = ["say", "-r", str(getattr(self.synth, "_rate", 175))]
                    voice = getattr(self.synth, "_voice", None)
                    if voice:
                        cmd.extend(["-v", voice])
                    cmd.append(text)
                    self._proc = subprocess.Popen(cmd)
                    self._proc.wait()
                else:
                    self.synth.synthesize(text)
            finally:
                cancelled = self._cancel.is_set()
                self._speaking = False
                self._proc = None
                cb = self.on_cancelled if cancelled else self.on_completed
                if cb:
                    try:
                        cb()
                    except Exception:
                        pass

        if blocking:
            _run()
            return {"ok": True, "blocking": True}
        self._thread = threading.Thread(target=_run, daemon=True)
        self._thread.start()
        return {"ok": True, "blocking": False}

    def cancel(self) -> None:
        self._cancel.set()
        if self._proc and self._proc.poll() is None:
            try:
                self._proc.terminate()
            except Exception:
                try:
                    self._proc.kill()
                except Exception:
                    pass
        self._speaking = False

    def stop(self) -> None:
        self.cancel()

    def status(self) -> dict[str, Any]:
        return {"speaking": self._speaking, "synth": self.synth.status()}

"""STT backends: faster-whisper / whisper / existing voice hooks."""
from __future__ import annotations

import logging
import tempfile
from pathlib import Path
from typing import Any

import numpy as np

logger = logging.getLogger(__name__)


class SpeechRecognizer:
    def __init__(self, *, model_size: str = "base", language: str | None = "en") -> None:
        self.model_size = model_size
        self.language = language
        self._model = None
        self._backend = "none"
        self._init_error: str | None = None
        self._bootstrap()

    def _bootstrap(self) -> None:
        try:
            from faster_whisper import WhisperModel  # type: ignore

            self._model = WhisperModel(self.model_size, device="auto", compute_type="int8")
            self._backend = "faster_whisper"
            return
        except Exception as exc:
            self._init_error = f"faster_whisper:{exc}"
        try:
            import whisper  # type: ignore

            self._model = whisper.load_model(self.model_size)
            self._backend = "whisper"
            return
        except Exception as exc:
            self._init_error = f"{self._init_error}; whisper:{exc}"
        # Existing OM voice hook
        try:
            from om_ai.voice.speech_to_text import SpeechToText  # type: ignore

            self._model = SpeechToText()
            self._backend = "om_voice_stt"
        except Exception as exc:
            self._init_error = f"{self._init_error}; om_voice:{exc}"

    @property
    def ready(self) -> bool:
        return self._model is not None

    def status(self) -> dict[str, Any]:
        return {"backend": self._backend, "ready": self.ready, "error": self._init_error, "model_size": self.model_size}

    def transcribe_array(self, audio: np.ndarray, *, sample_rate: int = 16000) -> dict[str, Any]:
        audio = np.asarray(audio, dtype=np.float32).reshape(-1)
        if audio.size == 0:
            return {"text": "", "ok": False, "reason": "empty_audio"}
        if self._backend == "faster_whisper" and self._model is not None:
            segments, info = self._model.transcribe(audio, language=self.language, vad_filter=True)
            parts = [s.text.strip() for s in segments if getattr(s, "text", None)]
            text = " ".join(parts).strip()
            return {
                "ok": bool(text),
                "text": text,
                "language": getattr(info, "language", self.language),
                "backend": self._backend,
                "confidence": float(getattr(info, "language_probability", 0.0) or 0.0),
            }
        if self._backend == "whisper" and self._model is not None:
            # whisper expects file or dict
            with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as tmp:
                path = Path(tmp.name)
            try:
                self._write_wav(path, audio, sample_rate)
                result = self._model.transcribe(str(path), language=self.language)
                text = str(result.get("text") or "").strip()
                return {"ok": bool(text), "text": text, "backend": self._backend, "confidence": 0.0}
            finally:
                try:
                    path.unlink(missing_ok=True)
                except Exception:
                    pass
        if self._backend == "om_voice_stt" and self._model is not None:
            with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as tmp:
                path = Path(tmp.name)
            try:
                self._write_wav(path, audio, sample_rate)
                if hasattr(self._model, "transcribe"):
                    text = str(self._model.transcribe(str(path)) or "").strip()
                else:
                    text = ""
                return {"ok": bool(text), "text": text, "backend": self._backend}
            finally:
                try:
                    path.unlink(missing_ok=True)
                except Exception:
                    pass
        return {"ok": False, "text": "", "reason": self._init_error or "stt_unavailable", "backend": self._backend}

    def _write_wav(self, path: Path, audio: np.ndarray, sample_rate: int) -> None:
        import wave
        import struct

        pcm = np.clip(audio, -1.0, 1.0)
        ints = (pcm * 32767.0).astype(np.int16)
        with wave.open(str(path), "wb") as wf:
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(sample_rate)
            wf.writeframes(ints.tobytes())

"""Microphone streaming with reconnect."""
from __future__ import annotations

import logging
import threading
from typing import Any, Callable

from .audio_buffer import AudioBuffer
from .audio_device import AudioDeviceManager

logger = logging.getLogger(__name__)


class AudioStream:
    def __init__(
        self,
        *,
        sample_rate: int = 16000,
        blocksize: int = 1024,
        device_manager: AudioDeviceManager | None = None,
        on_chunk: Callable[[Any], None] | None = None,
    ) -> None:
        self.sample_rate = sample_rate
        self.blocksize = blocksize
        self.devices = device_manager or AudioDeviceManager()
        self.on_chunk = on_chunk
        self.buffer = AudioBuffer(sample_rate=sample_rate)
        self._stream = None
        self._lock = threading.RLock()
        self._running = False
        self._error: str | None = None

    @property
    def running(self) -> bool:
        return self._running

    def start(self) -> dict[str, Any]:
        with self._lock:
            if self._running:
                return {"ok": True, "already": True}
            try:
                import sounddevice as sd  # type: ignore

                device = self.devices.selected_input()

                def _callback(indata, frames, time, status):  # noqa: ARG001
                    if status:
                        logger.debug("audio status: %s", status)
                    mono = indata[:, 0] if indata.ndim > 1 else indata.reshape(-1)
                    self.buffer.extend(mono)
                    if self.on_chunk:
                        try:
                            self.on_chunk(mono.copy())
                        except Exception as exc:
                            logger.debug("on_chunk error: %s", exc)

                self._stream = sd.InputStream(
                    samplerate=self.sample_rate,
                    blocksize=self.blocksize,
                    channels=1,
                    dtype="float32",
                    device=device,
                    callback=_callback,
                )
                self._stream.start()
                self._running = True
                self._error = None
                return {"ok": True, "sample_rate": self.sample_rate, "device": device}
            except Exception as exc:
                self._error = str(exc)
                self._running = False
                logger.warning("AudioStream start failed: %s", exc)
                return {"ok": False, "error": str(exc)}

    def stop(self) -> None:
        with self._lock:
            self._running = False
            if self._stream is not None:
                try:
                    self._stream.stop()
                    self._stream.close()
                except Exception:
                    pass
                self._stream = None

    def reconnect(self) -> dict[str, Any]:
        self.stop()
        return self.start()

    def status(self) -> dict[str, Any]:
        return {
            "running": self._running,
            "error": self._error,
            "buffered_seconds": self.buffer.duration(),
            "sample_rate": self.sample_rate,
        }

