"""Track partial/final transcripts for a session."""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any
import uuid


@dataclass
class TranscriptTurn:
    text: str
    final: bool = False
    confidence: float = 0.0
    turn_id: str = field(default_factory=lambda: str(uuid.uuid4())[:8])
    created_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    def to_dict(self) -> dict[str, Any]:
        return {
            "turn_id": self.turn_id,
            "text": self.text,
            "final": self.final,
            "confidence": self.confidence,
            "created_at": self.created_at,
        }


class TranscriptManager:
    def __init__(self) -> None:
        self.partial: str = ""
        self.finals: list[TranscriptTurn] = []

    def set_partial(self, text: str, *, confidence: float = 0.0) -> TranscriptTurn:
        self.partial = (text or "").strip()
        return TranscriptTurn(text=self.partial, final=False, confidence=confidence)

    def commit_final(self, text: str, *, confidence: float = 0.0) -> TranscriptTurn:
        turn = TranscriptTurn(text=(text or "").strip(), final=True, confidence=confidence)
        if turn.text:
            self.finals.append(turn)
        self.partial = ""
        return turn

    def history(self, limit: int = 20) -> list[dict[str, Any]]:
        return [t.to_dict() for t in self.finals[-limit:]]

    def clear(self) -> None:
        self.partial = ""
        self.finals.clear()

"""Microphone / speaker device enumeration and preference persistence."""
from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)


class AudioDeviceManager:
    def __init__(self, prefs_path: str | Path | None = None) -> None:
        root = Path(__file__).resolve().parents[3]
        self.prefs_path = Path(prefs_path or root / "artifacts" / "companion" / "audio_device.json")
        self.prefs_path.parent.mkdir(parents=True, exist_ok=True)
        self._prefs = self._load()

    def _load(self) -> dict[str, Any]:
        if self.prefs_path.is_file():
            try:
                return json.loads(self.prefs_path.read_text())
            except Exception:
                return {}
        return {}

    def save(self) -> None:
        self.prefs_path.write_text(json.dumps(self._prefs, indent=2))

    def list_input_devices(self) -> list[dict[str, Any]]:
        devices: list[dict[str, Any]] = []
        try:
            import sounddevice as sd  # type: ignore

            for i, d in enumerate(sd.query_devices()):
                if int(d.get("max_input_channels") or 0) > 0:
                    devices.append(
                        {
                            "id": i,
                            "name": str(d.get("name") or f"input-{i}"),
                            "channels": int(d.get("max_input_channels") or 0),
                            "sample_rate": float(d.get("default_samplerate") or 16000),
                            "kind": "input",
                        }
                    )
        except Exception as exc:
            logger.debug("sounddevice unavailable: %s", exc)
            devices.append(
                {
                    "id": 0,
                    "name": "default-input (unavailable until sounddevice installed)",
                    "channels": 1,
                    "sample_rate": 16000,
                    "kind": "input",
                    "available": False,
                }
            )
        return devices

    def list_output_devices(self) -> list[dict[str, Any]]:
        devices: list[dict[str, Any]] = []
        try:
            import sounddevice as sd  # type: ignore

            for i, d in enumerate(sd.query_devices()):
                if int(d.get("max_output_channels") or 0) > 0:
                    devices.append(
                        {
                            "id": i,
                            "name": str(d.get("name") or f"output-{i}"),
                            "channels": int(d.get("max_output_channels") or 0),
                            "sample_rate": float(d.get("default_samplerate") or 22050),
                            "kind": "output",
                        }
                    )
        except Exception as exc:
            logger.debug("sounddevice output unavailable: %s", exc)
            devices.append(
                {
                    "id": 0,
                    "name": "default-output (optional)",
                    "channels": 1,
                    "sample_rate": 22050,
                    "kind": "output",
                    "available": False,
                }
            )
        return devices

    def select_input(self, device_id: int) -> dict[str, Any]:
        self._prefs["input_device_id"] = int(device_id)
        self.save()
        return {"ok": True, "input_device_id": int(device_id)}

    def selected_input(self) -> int | None:
        v = self._prefs.get("input_device_id")
        return int(v) if v is not None else None

    def status(self) -> dict[str, Any]:
        inputs = self.list_input_devices()
        outputs = self.list_output_devices()
        ready = any(d.get("available", True) for d in inputs if "unavailable" not in str(d.get("name")))
        # If sounddevice missing, mark warn not fail
        try:
            import sounddevice  # noqa: F401

            backend = "sounddevice"
            ready = len(inputs) > 0
        except Exception:
            backend = "none"
            ready = False
        return {
            "backend": backend,
            "inputs": inputs,
            "outputs": outputs,
            "selected_input": self.selected_input(),
            "ready": ready,
        }

"""macOS / local TTS — free path. Default: Aman (Indian male)."""
from __future__ import annotations

import logging
import os
import shutil
import subprocess
import tempfile
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

# Prefer real Indian male companion voice on macOS
_PREFERRED_VOICES = (
    "Aman",
    "Rishi",
    "Daniel",
    "Alex",
    "Moira",
    "Samantha",
)
_HINDI_VOICES = (
    "Aman",   # Hinglish / Latin — keep male companion identity
    "Rishi",
    "Lekha",  # Devanagari fallback if Aman struggles
    "Veena",
)


class SpeechSynthesizer:
    def __init__(self) -> None:
        self._backend = "none"
        self._error: str | None = None
        self._voice: str | None = None
        self._rate = int(os.getenv("OM_COMPANION_TTS_RATE") or "178")
        self._detect()

    def _detect(self) -> None:
        if shutil.which("say"):
            self._backend = "macos_say"
            self._voice = self._pick_macos_voice()
            return
        try:
            import pyttsx3  # noqa: F401

            self._backend = "pyttsx3"
            return
        except Exception as exc:
            self._error = str(exc)
        try:
            from om_ai.voice.text_to_speech import TextToSpeech  # noqa: F401

            self._backend = "om_voice_tts"
        except Exception as exc:
            self._error = f"{self._error}; {exc}"

    def _pick_macos_voice(self) -> str | None:
        forced = (os.getenv("OM_COMPANION_TTS_VOICE") or "").strip()
        if forced:
            return forced
        return self._pick_voice_from(_PREFERRED_VOICES) or "Aman"

    def _pick_voice_from(self, names: tuple[str, ...]) -> str | None:
        try:
            out = subprocess.run(
                ["say", "-v", "?"],
                capture_output=True,
                text=True,
                check=False,
            )
            available = out.stdout or ""
            for name in names:
                # Match voice name at line start (avoid false hits)
                for line in available.splitlines():
                    if line.strip().startswith(name + " ") or line.strip().startswith(name + "\t"):
                        return name
                if re_search_voice(name, available):
                    return name
        except Exception as exc:
            logger.debug("voice probe failed: %s", exc)
        return None

    @property
    def ready(self) -> bool:
        return self._backend != "none"

    def status(self) -> dict[str, Any]:
        return {
            "backend": self._backend,
            "ready": self.ready,
            "error": self._error,
            "voice": self._voice,
            "rate": self._rate,
            "accent": "indian_english",
            "free": True,
        }

    def synthesize(
        self,
        text: str,
        *,
        output_path: str | Path | None = None,
        emotion: str = "calm",
        preplanned: bool = False,
    ) -> dict[str, Any]:
        """
        Render audio. If preplanned=True (or text already has [[rate]]),
        do not re-run human_delivery — TTSProvider already paced it.
        """
        text = (text or "").strip()
        if not text:
            return {"ok": False, "reason": "empty"}

        rate = self._rate
        already = preplanned or "[[rate" in text.lower()
        if not already:
            try:
                from om_ai.core.voice_engine.human_delivery import delivery_plan

                plan = delivery_plan(text, emotion=emotion)
                text = str(plan.get("spoken_tts") or text)
                rate = int(plan.get("rate") or self._rate)
            except Exception:
                pass

        out = Path(output_path) if output_path else Path(tempfile.mkstemp(suffix=".aiff")[1])
        try:
            if self._backend == "macos_say":
                voice = self._voice or "Aman"
                try:
                    from om_ai.core.companion_personality.voice_presence import detect_speech_locale

                    if detect_speech_locale(text) == "hi":
                        # Stay on Aman for Hinglish identity; only switch if Devanagari-heavy
                        if _has_devanagari(text):
                            voice = self._pick_voice_from(_HINDI_VOICES) or voice
                        else:
                            voice = self._pick_voice_from(("Aman", "Rishi")) or voice
                except Exception:
                    pass
                if "[[rate" in text.lower():
                    cmd = ["say", "-o", str(out)]
                else:
                    cmd = ["say", "-o", str(out), "-r", str(rate)]
                if voice:
                    cmd.extend(["-v", voice])
                if out.suffix.lower() == ".wav":
                    cmd.extend(["--data-format=LEI16@22050"])
                cmd.append(text)
                proc = subprocess.run(cmd, check=False, capture_output=True)

"""Bounded PCM audio buffer."""
from __future__ import annotations

from collections import deque
from typing import Deque
import numpy as np


class AudioBuffer:
    def __init__(self, *, max_seconds: float = 30.0, sample_rate: int = 16000) -> None:
        self.sample_rate = int(sample_rate)
        self.max_samples = int(max_seconds * self.sample_rate)
        self._buf: Deque[float] = deque(maxlen=self.max_samples)

    def extend(self, samples) -> None:
        arr = np.asarray(samples, dtype=np.float32).reshape(-1)
        self._buf.extend(arr.tolist())

    def clear(self) -> None:
        self._buf.clear()

    def size(self) -> int:
        return len(self._buf)

    def duration(self) -> float:
        return len(self._buf) / float(self.sample_rate or 1)

    def numpy(self) -> "np.ndarray":
        if not self._buf:
            return np.zeros(0, dtype=np.float32)
        return np.asarray(self._buf, dtype=np.float32)

    def snapshot_seconds(self, seconds: float) -> "np.ndarray":
        n = int(seconds * self.sample_rate)
        data = self.numpy()
        if data.size <= n:
            return data
        return data[-n:]

"""Local-first wake-word detector.

Default: lightweight phrase gate on transcript (no always-on cloud upload).
Optional: Picovoice Porcupine if `pvporcupine` + `OM_WAKE_PORCUPINE_KEY` are set.
"""
from __future__ import annotations

import os
import re
from typing import Any


_DEFAULT_ALIASES = (
    "hey om",
    "hi om",
    "hello om",
    "ok om",
    "okay om",
    "om",
    "hey jarvis",
    "hi jarvis",
    "jarvis",
    "hey jarvice",  # common STT misspell
)


class WakeWordEngine:
    """Detect configured wake phrase locally. Does not upload ambient audio."""

    def __init__(self, phrase: str = "hey om") -> None:
        self._porcupine = None
        self._porcupine_err: str | None = None
        self.set_phrase(phrase)
        self._armed = True
        self._try_porcupine()

    def set_phrase(self, phrase: str) -> None:
        self.phrase = (phrase or "hey om").strip().lower() or "hey om"
        aliases = {self.phrase, *_DEFAULT_ALIASES}
        # Keep short single-token phrases only when they match the family
        self._aliases = tuple(sorted(aliases, key=len, reverse=True))
        parts = [re.escape(a) for a in self._aliases if a]
        self._pattern = re.compile(rf"\b(?:{'|'.join(parts)})\b", re.I)

    def _try_porcupine(self) -> None:
        """Optional ultra-light always-on engine — only if key + package present."""
        key = (os.getenv("OM_WAKE_PORCUPINE_KEY") or os.getenv("PICOVOICE_ACCESS_KEY") or "").strip()
        if not key or key.lower() in {"your_key_here", "changeme", "xxx", ""}:
            return
        try:
            import pvporcupine  # type: ignore

            keyword = (os.getenv("OM_WAKE_PORCUPINE_KEYWORD") or "jarvis").strip()
            self._porcupine = pvporcupine.create(
                access_key=key,
                keywords=[keyword],
            )
        except Exception as exc:
            self._porcupine = None
            self._porcupine_err = str(exc)[:200]

    def arm(self) -> None:
        self._armed = True

    def disarm(self) -> None:
        self._armed = False

    def detect_text(self, text: str) -> dict[str, Any]:
        if not self._armed:
            return {"detected": False, "armed": False, "phrase": self.phrase}
        low = (text or "").strip().lower()
        hit = bool(self._pattern.search(low))
        if not hit:
            # Fuzzy: "hey"/"hi" near om/jarvis in first few tokens
            toks = low.replace(",", " ").split()
            head = toks[:4]
            if any(t in {"om", "jarvis", "jarvice"} for t in head) and any(
                t in {"hey", "hi", "hello", "okay", "ok", "yo"} for t in head
            ):
                hit = True
        return {
            "detected": hit,
            "armed": self._armed,
            "phrase": self.phrase,
            "mode": "porcupine" if self._porcupine else "local_phrase",
            "matched_text": low[:120] if hit else "",
        }

    def process_pcm(self, pcm: bytes | None = None) -> dict[str, Any]:
        """Optional Porcupine frame hook for desktop always-on mic path."""
        if not self._armed or self._porcupine is None or not pcm:
            return {"detected": False, "mode": "local_phrase"}
        try:
            # Porcupine expects int16 frames; caller must pass correctly sized audio
            import struct

            frame_len = int(getattr(self._porcupine, "frame_length", 512) or 512)
            need = frame_len * 2
            if len(pcm) < need:
                return {"detected": False, "mode": "porcupine", "reason": "short_frame"}
            frame = struct.unpack_from(f"{frame_len}h", pcm, 0)
            result = self._porcupine.process(frame)
            hit = int(result) >= 0
            if hit:
                self.disarm()
            return {
                "detected": hit,
                "armed": self._armed,
                "phrase": self.phrase,
                "mode": "porcupine",
            }
        except Exception as exc:
            return {"detected": False, "mode": "porcupine", "error": str(exc)[:160]}

    def status(self) -> dict[str, Any]:
        return {
            "phrase": self.phrase,
            "armed": self._armed,
            "mode": "porcupine" if self._porcupine else "local_phrase",
            "aliases": list(self._aliases)[:12],
            "porcupine_error": self._porcupine_err,
        }

