class ConversationState:
    def __init__(self) -> None:
        self._state: dict[str, Any] = {
            "topic": "general",
            "last_intent": "conversation",
            "last_goal": "continue",
            "open_question": None,
            "awaiting_permission": False,
            "turn": 0,
            "entities": [],
            "thread": [],
        }

    def update(self, frame: dict[str, Any] | None = None) -> dict[str, Any]:
        frame = frame or {}
        self._state["turn"] = int(self._state.get("turn") or 0) + 1
        intent = str(frame.get("intent") or self._state["last_intent"])
        goal = str(frame.get("goal") or self._state["last_goal"])
        self._state["last_intent"] = intent
        self._state["last_goal"] = goal

        topics = frame.get("topics") or []
        if topics:
            self._state["topic"] = topics[0]
        elif frame.get("topic"):
            self._state["topic"] = frame["topic"]

        ents = list(frame.get("entities") or [])
        if ents:
            merged = list(dict.fromkeys(list(self._state.get("entities") or []) + ents))
            self._state["entities"] = merged[-20:]

        text = str(frame.get("corrected") or frame.get("text") or "")[:160]
        if text:
            thread = list(self._state.get("thread") or [])
            thread.append({"role": "user", "text": text, "intent": intent})
            self._state["thread"] = thread[-12:]

        if frame.get("needs_clarification"):
            self._state["open_question"] = frame.get("clarify_ask") or "Need a bit more."
        elif intent not in {"followup"}:
            self._state["open_question"] = None

        self._state["awaiting_permission"] = bool(frame.get("awaiting_permission"))
        return self.snapshot()

    def remember_assistant(self, text: str) -> None:
        thread = list(self._state.get("thread") or [])
        thread.append({"role": "assistant", "text": (text or "")[:160]})
        self._state["thread"] = thread[-12:]

    def snapshot(self) -> dict[str, Any]:
        return dict(self._state)

    def reset(self) -> None:
        self.__init__()

"""Intent understanding — semantic intent labels for a turn."""
from __future__ import annotations

import re
from typing import Any


class IntentUnderstanding:
    """Map corrected language → intent + confidence."""

    def understand(
        self,
        text: str,
        *,
        speech_act: str = "statement",
        history: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        low = (text or "").lower().strip()
        hist = history or []

        if re.search(r"(?i)\b(search|google|khoj|research|look\s+up)\b", low):
            return self._pack("research", 0.9, speech_act="request")
        if re.search(r"(?i)\b(open|kholo|launch|start|delete|send|run)\b", low):
            return self._pack("action", 0.88, speech_act="request")
        if re.search(
            r"(?i)\b(today was|difficult|failed|tired|sad|stress|bad day|thak|udas)\b",
            low,
        ):
            return self._pack("sharing", 0.9, speech_act="share")
        if re.search(r"(?i)^\s*(hi|hello|hey|namaste|yo)\b", low):
            return self._pack("greeting", 0.95, speech_act="statement")
        if re.search(r"(?i)\b(thanks|thank you|shukriya|dhanyavad)\b", low):
            return self._pack("thanks", 0.92, speech_act="statement")
        if re.search(r"(?i)\b(joke|majaak|funny|haha|lol)\b", low):
            return self._pack("joke", 0.85, speech_act="request")
        if re.search(r"(?i)\b(fix|bug|debug|not working|crash|exception)\b", low):
            return self._pack("problem", 0.87, speech_act=speech_act or "request")
        if speech_act == "question" or "?" in (text or "") or re.search(
            r"(?i)\b(what|how|why|when|where|kaise|kya|kyun|explain)\b", low
        ):
            return self._pack("question", 0.84, speech_act="question")
        if re.search(r"(?i)\b(continue|us[ei]|wahi|pehle|keep going)\b", low) or (
            len(low.split()) <= 3 and hist
        ):
            return self._pack("followup", 0.75, speech_act="statement")
        if speech_act == "share":
            return self._pack("sharing", 0.8, speech_act="share")
        return self._pack("conversation", 0.6, speech_act=speech_act or "statement")

    def _pack(self, intent: str, confidence: float, *, speech_act: str) -> dict[str, Any]:
        return {
            "intent": intent,
            "confidence": confidence,
            "speech_act": speech_act,
            "label": intent,
        }

"""Companion living loop — phase transitions."""
from __future__ import annotations

import time
from typing import Any

from .attention_manager import AttentionManager
from .availability_state import AvailabilityState
from .idle_behavior import IdleBehavior
from .interruption_manager import InterruptionManager
from .session_lifecycle import SessionLifecycle


class CompanionLoop:
    """
    OM Started → Ready → Waiting → Listening → Thinking → Responding → Waiting
    """

    def __init__(self) -> None:
        self.phase = AvailabilityState.OFFLINE
        self.attention = AttentionManager()
        self.idle = IdleBehavior()
        self.interruptions = InterruptionManager()
        self.session = SessionLifecycle()
        self._waiting_since_ms = 0.0

    def boot(self) -> dict[str, Any]:
        self.phase = AvailabilityState.STARTING
        self.phase = AvailabilityState.READY
        return self._enter(AvailabilityState.WAITING)

    def on_listen_start(self) -> dict[str, Any]:
        return self._enter(AvailabilityState.LISTENING)

    def on_user_final(self) -> dict[str, Any]:
        self.session.on_user()
        return self._enter(AvailabilityState.THINKING)

    def on_respond_start(self) -> dict[str, Any]:
        return self._enter(AvailabilityState.RESPONDING)

    def on_respond_end(self) -> dict[str, Any]:
        self.session.on_assistant()
        return self._enter(AvailabilityState.WAITING)

    def on_interrupt(self) -> dict[str, Any]:
        pack = self.interruptions.fire()
        self.phase = AvailabilityState.INTERRUPTED
        out = self._enter(AvailabilityState.WAITING)
        out["interrupt"] = pack
        return out

    def tick(self) -> dict[str, Any]:
        if self.phase != AvailabilityState.WAITING:
            return {"phase": self.phase.value, "idle": None}
        idle = self.idle.tick(waiting_since_ms=self._waiting_since_ms)
        return {"phase": self.phase.value, "idle": idle, **self.attention.on_phase(self.phase)}

    def _enter(self, phase: AvailabilityState) -> dict[str, Any]:
        self.phase = phase
        if phase == AvailabilityState.WAITING:
            self._waiting_since_ms = time.time() * 1000
        attn = self.attention.on_phase(phase)
        return {
            "phase": phase.value,
            "state": phase.value,
            "attention": attn,
            "session": self.session.snapshot(),
            "alive": True,
        }

