"""Authorization decisions — external content cannot authorize actions."""
from __future__ import annotations

from om_ai.core.action_control import ActionRequest

from .security_context import SecurityContext


class Authorization:
    _AUTH_ACTIONS = frozenset(
        {
            "approve",
            "grant",
            "authorize",
            "permission.grant",
            "action.approve",
        }
    )

    def can_execute_action(
        self, ctx: SecurityContext, request: ActionRequest
    ) -> tuple[bool, str]:
        if ctx.is_external_content or request.source == "external":
            if request.action_type in self._AUTH_ACTIONS:
                return False, "external content cannot authorize actions"
            if any(k in request.parameters for k in ("approve", "grant", "authorize")):
                return False, "external parameters cannot authorize actions"
        return True, ""

    def can_approve(self, ctx: SecurityContext) -> bool:
        if ctx.is_external_content:
            return False
        return "operator" in ctx.roles or "admin" in ctx.roles

"""Validate untrusted inputs at the security boundary."""
from __future__ import annotations

import re
from typing import Any

_INJECTION_MARKERS = (
    "ignore previous",
    "disregard prior",
    "system prompt",
    "you are now",
    "approve all",
    "grant permission",
    "allow everything",
)

_PATH_TRAVERSAL = re.compile(r"(^|/)\.\.(/|$)")


class InputValidator:
    def validate_user_text(self, text: str, *, max_len: int = 32_000) -> list[str]:
        errors: list[str] = []
        if not text or not text.strip():
            errors.append("empty input")
        if len(text) > max_len:
            errors.append("input too long")
        lower = text.lower()
        for marker in _INJECTION_MARKERS:
            if marker in lower:
                errors.append(f"suspicious marker: {marker}")
        return errors

    def validate_path(self, path: str) -> list[str]:
        if _PATH_TRAVERSAL.search(path.replace("\\", "/")):
            return ["path traversal"]
        return []

    def validate_action_parameters(self, params: dict[str, Any]) -> list[str]:
        errors: list[str] = []
        for key in ("authorize", "grant", "approve", "allow_everything_forever"):
            if key in params:
                errors.append(f"forbidden parameter key: {key}")
        argv = params.get("argv")
        if argv is not None and isinstance(argv, str):
            errors.append("argv must be list, not string")
        return errors

"""Redact secrets before logging or export."""
from __future__ import annotations

import re
from typing import Any

_SECRET_PATTERNS: tuple[re.Pattern[str], ...] = (
    re.compile(r"(?i)(api[_-]?key|secret|token|password|passwd|authorization)\s*[:=]\s*\S+"),
    re.compile(r"(?i)bearer\s+[a-z0-9\-_.~+/]+=*"),
    re.compile(r"-----BEGIN [A-Z ]+ PRIVATE KEY-----[\s\S]*?-----END [A-Z ]+ PRIVATE KEY-----"),
    re.compile(r"sk-[a-zA-Z0-9]{20,}"),
    re.compile(r"ghp_[a-zA-Z0-9]{20,}"),
)

_REDACTED = "[REDACTED]"


def redact_text(text: str) -> str:
    out = text
    for pat in _SECRET_PATTERNS:
        out = pat.sub(_REDACTED, out)
    return out


def redact_value(value: Any) -> Any:
    if isinstance(value, str):
        return redact_text(value)
    if isinstance(value, dict):
        return {k: redact_value(v) for k, v in value.items()}
    if isinstance(value, list):
        return [redact_value(v) for v in value]
    if isinstance(value, tuple):
        return tuple(redact_value(v) for v in value)
    return value

"""STEP 86 — Global Knowledge Intelligence.

Local knowledge + live retrieval + graph facts + ranking.
"""
from __future__ import annotations

from typing import Any


class GlobalKnowledgeIntelligence:
    def __init__(self) -> None:
        self._graph: dict[str, list[str]] = {}

    def ingest_text(self, text: str, *, source: str = "local") -> dict[str, Any]:
        words = [w.lower() for w in (text or "").split() if len(w) > 3][:40]
        entities = list(dict.fromkeys(words))[:12]
        for e in entities:
            self._graph.setdefault(e, [])
            for other in entities:
                if other != e and other not in self._graph[e]:
                    self._graph[e].append(other)
        return {"step": 86, "ingested": True, "entities": entities, "source": source}

    def link_entities(self, query: str) -> list[dict[str, Any]]:
        q_words = set((query or "").lower().split())
        linked = []
        for entity, neighbors in self._graph.items():
            if entity in q_words or any(w in entity for w in q_words):
                linked.append({"entity": entity, "links": neighbors[:8]})
        return linked[:10]

    def retrieve(self, query: str, knowledge: Any = None) -> dict[str, Any]:
        hits: list[str] = []
        if isinstance(knowledge, list):
            hits.extend(str(x)[:1500] for x in knowledge[:8] if x)
        elif isinstance(knowledge, dict):
            for k in ("hits", "results", "documents", "context"):
                v = knowledge.get(k)
                if isinstance(v, list):
                    hits.extend(str(x)[:1500] for x in v[:8])
                elif isinstance(v, str) and v.strip():
                    hits.append(v[:1500])
        elif isinstance(knowledge, str) and knowledge.strip():
            hits.append(knowledge[:2000])

        # Live knowledge when query looks global/current
        live = []
        q = (query or "").lower()
        if any(w in q for w in ("latest", "current", "world", "global", "what is", "who is")):
            try:
                from om_ai.live_knowledge.web_search import search_web

                for h in search_web(query, limit=4) or []:
                    live.append(
                        {
                            "title": getattr(h, "title", ""),
                            "url": getattr(h, "url", ""),
                            "snippet": getattr(h, "snippet", ""),
                        }
                    )
                    if getattr(h, "snippet", None):
                        hits.append(str(h.snippet)[:800])
            except Exception:
                pass

        for h in hits[:5]:
            self.ingest_text(h, source="retrieved")

        return {
            "step": 86,
            "query": query,
            "hits": hits[:10],
            "live": live,
            "entities": self.link_entities(query),
            "context": "\n\n".join(hits[:6])[:6000],
        }

