            True
        )


    def _bool(
        self,
        key,
        default
    ):

        value = os.getenv(key)

        if value is None:
            return default

        return value.lower() in (
            "true",
            "1",
            "yes"
        )


    def _list(
        self,
        key
    ):

        value = os.getenv(
            key,
            ""
        )

        if not value:
            return []

        return [
            x.strip()
            for x in value.split(",")
            if x.strip()
        ]

