    def __init__(self, path: Path | str | None = None) -> None:
        self.path = Path(path) if path else _default_audit_path()
        self._lock = threading.Lock()

    def append(self, event_type: str, payload: dict[str, Any]) -> str:
        record = {
            "ts": datetime.now(timezone.utc).isoformat(),
            "event": event_type,
            **payload,
        }
        self.path.parent.mkdir(parents=True, exist_ok=True)
        line = json.dumps(record, default=str, ensure_ascii=False)
        with self._lock:
            with self.path.open("a", encoding="utf-8") as fh:
                fh.write(line + "\n")
        return record["ts"]

    def log_request(self, request: ActionRequest) -> str:
        return self.append(
            "action_request",
            {
                "action_id": request.action_id,
                "action_type": request.action_type,
                "risk_class": request.risk_class.value,
                "actor": request.actor,
                "source": request.source,
            },
        )

    def log_approval_pending(self, request: ActionRequest) -> str:
        return self.append(
            "approval_pending",
            {"action_id": request.action_id, "action_type": request.action_type},
        )

    def log_approval_decision(
        self, action_id: str, *, approved: bool, approver: str
    ) -> str:
        return self.append(
            "approval_decision",
            {
                "action_id": action_id,
                "approved": approved,
                "approver": approver,
            },
        )

    def log_result(self, result: ActionResult) -> str:
        return self.append(
            "action_result",
            {
                "action_id": result.action_id,
                "status": result.status.value,
                "error": result.error,
            },
        )

"""Risk scoring and escalation."""
from __future__ import annotations

from dataclasses import dataclass

from .action_request import ActionRequest, RiskClass


@dataclass(frozen=True)
class RiskAssessment:
    risk_class: RiskClass
    score: float
    reasons: tuple[str, ...]


class RiskEngine:
    _BASE_SCORE: dict[RiskClass, float] = {
        RiskClass.READ_ONLY: 0.1,
        RiskClass.LOW_IMPACT: 0.25,
        RiskClass.REVERSIBLE_WRITE: 0.45,
        RiskClass.EXTERNAL_SIDE_EFFECT: 0.65,
        RiskClass.SENSITIVE: 0.85,
        RiskClass.DESTRUCTIVE: 1.0,
    }

    def assess(self, request: ActionRequest) -> RiskAssessment:
        reasons: list[str] = []
        score = self._BASE_SCORE.get(request.risk_class, 0.5)
        reasons.append(f"declared_risk={request.risk_class.value}")

        if request.source == "external":
            score = min(1.0, score + 0.15)
            reasons.append("external_source_boost")

        if request.action_type.endswith(".delete") or "delete" in request.action_type:
            if request.risk_class != RiskClass.DESTRUCTIVE:
                reasons.append("delete_action_should_be_destructive")

        effective = request.risk_class
        if score >= 0.95:
            effective = RiskClass.DESTRUCTIVE
        elif score >= 0.8:
            effective = RiskClass.SENSITIVE

        return RiskAssessment(
            risk_class=effective,
            score=round(score, 3),
            reasons=tuple(reasons),
        )

    def requires_human_approval(self, assessment: RiskAssessment) -> bool:
        return assessment.risk_class in {
            RiskClass.SENSITIVE,
            RiskClass.DESTRUCTIVE,
            RiskClass.EXTERNAL_SIDE_EFFECT,
        }

"""High-level security policy for action control."""
from __future__ import annotations

from dataclasses import dataclass, field

from .action_request import ActionRequest, RiskClass


@dataclass
class SecurityPolicy:
    """Operator-tunable policy knobs."""

    block_external_authorization: bool = True
    max_destructive_per_session: int = 3
    require_approval_for_external_side_effects: bool = True
    allowed_action_prefixes: tuple[str, ...] = field(
        default_factory=lambda: (
            "command.",
            "filesystem.",
            "application.",
            "browser.",
            "process.",
            "system.",
        )
    )

    def evaluate(self, request: ActionRequest) -> tuple[bool, str]:
        if not request.action_type:
            return False, "empty action_type"

        if not any(
            request.action_type.startswith(p) for p in self.allowed_action_prefixes
        ):
            return False, f"action_type not allowed: {request.action_type}"

        if self.block_external_authorization and request.source == "external":
            auth_keys = {"approve", "grant", "authorize", "permission"}
            if request.action_type in auth_keys or any(
                k in request.parameters for k in auth_keys
            ):
                return False, "external content cannot authorize actions"

        if (
            self.require_approval_for_external_side_effects
            and request.risk_class == RiskClass.EXTERNAL_SIDE_EFFECT
            and request.source == "external"
        ):
            return False, "external-sourced side effects require internal actor"

        return True, ""

