"""Scoped permission checks; default deny without explicit grants."""
from __future__ import annotations

from datetime import datetime, timezone
from threading import RLock

from .action_request import ActionRequest, RiskClass
from .permission import Permission, PermissionDecision


class PermissionManager:
    def __init__(self, *, allow_everything_forever: bool = False) -> None:
        self._lock = RLock()
        self._grants: list[Permission] = []
        self._allow_everything_forever = allow_everything_forever

    @property
    def allow_everything_forever(self) -> bool:
        return self._allow_everything_forever

    @allow_everything_forever.setter
    def allow_everything_forever(self, value: bool) -> None:
        self._allow_everything_forever = bool(value)

    def grant(self, permission: Permission) -> None:
        with self._lock:
            self._grants.append(permission)

    def revoke_subject(self, subject: str) -> int:
        with self._lock:
            before = len(self._grants)
            self._grants = [g for g in self._grants if g.subject != subject]
            return before - len(self._grants)

    def check(self, request: ActionRequest) -> PermissionDecision:
        if self._allow_everything_forever:
            return PermissionDecision.ALLOW

        now = datetime.now(timezone.utc)
        with self._lock:
            for grant in self._grants:
                if not grant.is_active(now):
                    continue
                if grant.subject not in {request.actor, "*"}:
                    continue
                if grant.action_type not in {request.action_type, "*"}:
                    continue
                if not _risk_covers(grant.risk_class, request.risk_class):
                    continue
                return grant.decision

        if request.is_auto_eligible():
            return PermissionDecision.ALLOW

        if request.risk_class in {RiskClass.SENSITIVE, RiskClass.DESTRUCTIVE}:
            return PermissionDecision.NEEDS_APPROVAL

        if request.requires_explicit_approval:
            return PermissionDecision.NEEDS_APPROVAL

        return PermissionDecision.DENY


def _risk_covers(granted: RiskClass, required: RiskClass) -> bool:
    order = list(RiskClass)
    return order.index(granted) >= order.index(required)

"""Action policy — separate information search from side-effect actions."""
from __future__ import annotations

import re
from typing import Any


class ActionPolicy:
    """
    Search  → information only (no browser redirect)
    Open    → action (permission required)
    Delete  → destructive (permission required)
    """

    def classify(self, message: str) -> dict[str, Any]:
        text = (message or "").strip()
        low = text.lower()

        wants_open = bool(
            re.search(
                r"(?i)\b(go|open|kholo|khol|launch|navigate|redirect|take\s+me|"
                r"open\s+in\s+browser|show\s+in\s+browser)\b",
                low,
            )
        )
        is_search = bool(
            re.search(r"(?i)\b(search|google|khoj|research|look\s+up|find|dhundo)\b", low)
            or "search karo" in low
        )
        is_open_app = bool(
            re.search(r"(?i)\b(open|kholo|launch|start)\b", low)
            and not is_search
        )
        is_destructive = bool(
            re.search(r"(?i)\b(delete|remove|rm\b|erase|uninstall|format)\b", low)
        )

        if is_search and not wants_open:
            return {
                "kind": "search",
                "side_effect": False,
                "requires_permission": False,
                "may_open_browser": False,
                "reason": "information_request",
            }
        if is_search and wants_open:
            return {
                "kind": "open",
                "side_effect": True,
                "requires_permission": True,
                "may_open_browser": True,
                "reason": "user_asked_to_open",
            }
        if is_destructive:
            return {
                "kind": "destructive",
                "side_effect": True,
                "requires_permission": True,
                "may_open_browser": False,
                "reason": "destructive_action",
            }
        if is_open_app or wants_open:
            return {
                "kind": "open",
                "side_effect": True,
                "requires_permission": True,
                "may_open_browser": "http" in low or "www." in low or "browser" in low,
                "reason": "action_request",
            }
        return {
            "kind": "none",
            "side_effect": False,
            "requires_permission": False,
            "may_open_browser": False,
            "reason": "conversation",
        }

"""Execution guard — think before acting; ask permission for side effects."""
from __future__ import annotations

from typing import Any


class ExecutionGuard:
    def check(self, policy: dict[str, Any] | None = None) -> dict[str, Any]:
        policy = policy or {}
        kind = str(policy.get("kind") or "none")

        if kind == "search":
            return {
                "allowed": True,
                "requires_permission": False,
                "execute": "search_only",
                "prompt": "",
                "message": "Search and summarize. Do not open browser.",
            }

        if kind in {"open", "destructive"} or policy.get("requires_permission"):
            prompt = (
                "I can open it. Permission required — proceed?"
                if kind == "open"
                else "This can change your system. Permission required — proceed?"
            )
            return {
                "allowed": False,
                "requires_permission": True,
                "execute": "wait",
                "prompt": prompt,
                "message": prompt,
            }

        return {
            "allowed": True,
            "requires_permission": False,
            "execute": "none",
            "prompt": "",
            "message": "",
        }

    def after_permission(self, approved: bool, policy: dict[str, Any] | None = None) -> dict[str, Any]:
        if not approved:
            return {"allowed": False, "execute": "cancel", "message": "Okay — cancelled."}
        return {
            "allowed": True,
            "requires_permission": False,
            "execute": str((policy or {}).get("kind") or "open"),
            "message": "Proceeding.",
        }

"""Structured action requests with schema validation."""
from __future__ import annotations

import uuid
from enum import Enum
from typing import Any

from pydantic import BaseModel, Field, field_validator, model_validator


class RiskClass(str, Enum):
    READ_ONLY = "READ_ONLY"
    LOW_IMPACT = "LOW_IMPACT"
    REVERSIBLE_WRITE = "REVERSIBLE_WRITE"
    EXTERNAL_SIDE_EFFECT = "EXTERNAL_SIDE_EFFECT"
    SENSITIVE = "SENSITIVE"
    DESTRUCTIVE = "DESTRUCTIVE"


_AUTO_ALLOW_RISKS = frozenset({RiskClass.READ_ONLY, RiskClass.LOW_IMPACT})


class ActionRequest(BaseModel):
    """Validated action intent; extra fields are rejected."""

    model_config = {"extra": "forbid"}

    action_id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    action_type: str = Field(..., min_length=1, max_length=256)
    risk_class: RiskClass
    parameters: dict[str, Any] = Field(default_factory=dict)
    actor: str = Field(default="system", min_length=1, max_length=128)
    source: str = Field(
        default="internal",
        description="internal | external — external cannot self-authorize",
    )
    reason: str = Field(default="", max_length=4096)
    requires_explicit_approval: bool | None = None
    correlation_id: str | None = None

    @field_validator("action_type")
    @classmethod
    def normalize_action_type(cls, v: str) -> str:
        return v.strip()

    @field_validator("source")
    @classmethod
    def normalize_source(cls, v: str) -> str:
        s = v.strip().lower()
        if s not in {"internal", "external"}:
            raise ValueError("source must be 'internal' or 'external'")
        return s

    @model_validator(mode="after")
    def set_default_approval(self) -> ActionRequest:
        if self.requires_explicit_approval is None:
            self.requires_explicit_approval = (
                self.risk_class not in _AUTO_ALLOW_RISKS
            )
        return self

    def is_auto_eligible(self) -> bool:
        return (
            not self.requires_explicit_approval
            and self.risk_class in _AUTO_ALLOW_RISKS
            and self.source == "internal"
        )

from __future__ import annotations

