class SkillEngine:
    """
    OM Skill Intelligence Engine.

    Converts knowledge into abilities.
    """



    def __init__(self):

        self.graph = SkillGraph()

        self.progress = {}



    def register_skill(
        self,
        skill: SkillNode
    ):


        self.graph.add_skill(
            skill
        )


        self.progress[
            skill.id
        ] = SkillProgress(

            skill_id=skill.id

        )



    def evaluate_skill(
        self,
        skill_id: str
    ):


        progress = (
            self.progress.get(
                skill_id
