        self,
        skill_id: str,
        success: bool,
        quality: float
    ):


        progress = (
            self.progress.get(
                skill_id
            )
        )


        if progress:

            progress.update(

                success,

                quality

            )



    def recommend_learning(
        self,
        skill_id: str
    ):


        return (

            self.graph.dependencies(

                skill_id

            )

        )

