class MoodContext:
    label: str = "neutral"
    valence: float = 0.0
    arousal: float = 0.35
    trust: float = 0.6
    history: list[str] = field(default_factory=list)

    def update(self, *, label: str = "", valence: float | None = None, arousal: float | None = None) -> None:
