        self._by_session.clear()

"""Privacy and retention policy for companion memory."""
from __future__ import annotations

import re
from typing import Any

# Structural secret patterns — not conversational keyword lists.
_SECRET_PATTERNS: tuple[re.Pattern[str], ...] = (
    re.compile(r"(?i)\b(api[_-]?key|secret[_-]?key|access[_-]?token)\s*[:=]\s*\S+"),
    re.compile(r"(?i)\b(password|passwd|pwd)\s*[:=]\s*\S+"),
    re.compile(r"(?i)\b(bearer)\s+[a-z0-9\-_.~+/]+=*", re.I),
    re.compile(r"-----BEGIN (?:RSA |EC )?PRIVATE KEY-----"),
    re.compile(r"\bsk-[a-zA-Z0-9]{20,}\b"),
    re.compile(r"\bghp_[a-zA-Z0-9]{20,}\b"),
    re.compile(r"\bxox[baprs]-[a-zA-Z0-9-]{10,}\b"),
)


class MemoryPolicy:
    """Decide whether content may be persisted."""

    def __init__(self, *, max_content_len: int = 8000) -> None:
        self.max_content_len = max_content_len

    def classify_sensitivity(self, content: str) -> str:
        text = (content or "").strip()
        if not text:
            return "empty"
        for pat in _SECRET_PATTERNS:
            if pat.search(text):
                return "secret"
        if len(text) > self.max_content_len:
            return "oversized"
        return "normal"

    def allow_store(self, content: str, *, kind: str = "") -> tuple[bool, str]:
        sens = self.classify_sensitivity(content)
        if sens == "secret":
            return False, "blocked_secret"
        if sens == "empty":
            return False, "empty_content"
        if sens == "oversized":
            return True, "truncated"
        if kind == "credential":
            return False, "blocked_credential_kind"
        return True, "ok"

    def sanitize_for_store(self, content: str) -> str:
        text = (content or "").strip()
        if self.classify_sensitivity(text) == "secret":
            return ""
        if len(text) > self.max_content_len:
            return text[: self.max_content_len]
        return text

    def redact_preview(self, content: str, *, max_len: int = 120) -> str:
        text = self.sanitize_for_store(content)
        if not text:
            return "[redacted]"
        if len(text) <= max_len:
            return text
        return text[: max_len - 3] + "..."

    def policy_summary(self) -> dict[str, Any]:
        return {
            "store_secrets": False,
            "max_content_len": self.max_content_len,
            "secret_detection": "structural_patterns",
        }

"""Semantic memory — stable facts and concepts."""
from __future__ import annotations

from typing import Any

from .memory_event import MemoryEvent


class SemanticMemory:
    """Facts indexed by topic key within a user scope."""

    KIND = "semantic"

    def __init__(self, store: dict[str, list[dict[str, Any]]]) -> None:
        self._store = store

    def _bucket(self, user_key: str) -> list[dict[str, Any]]:
        return self._store.setdefault(user_key, [])

    def upsert(
        self,
        user_key: str,
        topic: str,
        fact: str,
        *,
        meta: dict[str, Any] | None = None,
    ) -> MemoryEvent:
        ev = MemoryEvent(
            kind=self.KIND,
            content=fact,
            scope="user",
            key=topic,
            tags=[topic] if topic else [],
            meta=dict(meta or {}),
        )
        bucket = self._bucket(user_key)
        replaced = False
        for i, row in enumerate(bucket):
            if row.get("key") == topic and row.get("kind") == self.KIND:
                bucket[i] = ev.to_dict()
                replaced = True
                break
        if not replaced:
            bucket.append(ev.to_dict())
        if len(bucket) > 500:
            del bucket[:-500]
        return ev

    def list(self, user_key: str, *, limit: int = 100) -> list[dict[str, Any]]:
        return list(self._bucket(user_key)[-limit:])

    def clear(self, user_key: str) -> int:
        n = len(self._bucket(user_key))
        self._store.pop(user_key, None)
        return n

"""User preference memory."""
from __future__ import annotations

from typing import Any

