        decision = (
            self.router.decide(
                query
            )
        )


        if not decision["research_needed"]:


            return {

                "research":
                    False,

                "query":
                    query

            }



        documents = (
            self.search.search(
                query
            )
        )


        extracted=[]


        for doc in documents:


            data=self.reader.read(
                doc
            )


            extracted.append(

                self.extractor.extract(
                    data
                )

            )


        return self.builder.build(

            query,

            extracted

        )

