from __future__ import annotations

import re
from typing import Any


class FatigueDetector:
    _SLEEP = re.compile(
        r"(?i)\b("
        r"slept only|only\s+\d+\s+hours?(?:\s+(?:of\s+)?sleep)?|"
        r"(?:every|each)\s+day\s+this\s+week|"
        r"for\s+(?:the\s+)?last\s+week|all\s+week|"
        r"no sleep|insomnia|can'?t sleep|couldn'?t sleep|"
        r"\d+\s+hours?\s+(?:sleep|a\s+night)"
        r")\b"
    )
    _TIRED = re.compile(
        r"(?i)\b(very tired|exhausted|worn out|drained|thak(?:a| gaya)?|"
        r"burn(?:ed)?\s*out|no energy)\b"
    )

    def detect(self, message: str) -> dict[str, Any]:
        text = message or ""
        if self._SLEEP.search(text):
            return {
                "signal": "sleep_deprivation",
                "confidence": 0.82,
                "label": "sleep problems",
                "hit": True,
            }
        if self._TIRED.search(text):
            return {
                "signal": "fatigue",
                "confidence": 0.78,
                "label": "fatigue",
                "hit": True,
            }
        return {"signal": None, "confidence": 0.0, "label": None, "hit": False}

"""Rolling wellbeing context across turns."""
from __future__ import annotations

from typing import Any


class WellbeingContext:
    def __init__(self) -> None:
        self._events: list[dict[str, Any]] = []

    def push(self, pack: dict[str, Any]) -> None:
        if pack.get("has_signal"):
            self._events.append(pack)
            self._events = self._events[-20:]

    def summary(self) -> dict[str, Any]:
        if not self._events:
            return {"recent_signals": [], "dominant": None}
        sigs = [str(e.get("signal") or "") for e in self._events[-5:]]
        dominant = max(set(sigs), key=sigs.count) if sigs else None
        return {
            "recent_signals": sigs,
            "dominant": dominant,
            "count": len(self._events),
        }

