"""Conversation goal for the current thread."""
from __future__ import annotations

from typing import Any


class ConversationGoal:
    def infer(
        self,
        message: str,
        *,
        human: dict[str, Any] | None = None,
        emotion: dict[str, Any] | None = None,
        is_action: bool = False,
    ) -> dict[str, Any]:
        human = human or {}
        emotion = emotion or {}
        if is_action:
            return {"goal": "execute", "priority": "action"}
        if human.get("incomplete", {}).get("incomplete"):
            return {"goal": "continue_thread", "priority": "listen"}
        if emotion.get("need") == "listen_first" or human.get("listen_first"):
            return {"goal": "support", "priority": "listen"}
        if (human.get("conversation") or {}).get("celebration"):
            return {"goal": "celebrate", "priority": "encourage"}
        if (human.get("conversation") or {}).get("is_question"):
            return {"goal": "answer", "priority": "explain"}
        if (human.get("implicit") or {}).get("has_implicit"):
            return {"goal": "explore", "priority": "ask"}
        return {"goal": "assist", "priority": "answer"}

"""Turn manager — decide the move for this turn."""
from __future__ import annotations

from typing import Any


class TurnManager:
    def decide(self, goal: dict[str, Any], *, interrupted: bool = False) -> dict[str, Any]:
        if interrupted:
            return {"move": "yield", "action": "listen", "speak": False}
        priority = str(goal.get("priority") or "answer")
        mapping = {
            "listen": {"move": "listen", "action": "acknowledge_and_invite", "speak": True},
            "ask": {"move": "ask", "action": "one_gentle_question", "speak": True},
            "explain": {"move": "explain", "action": "answer_clearly", "speak": True},
            "encourage": {"move": "encourage", "action": "celebrate_then_ask", "speak": True},
            "action": {"move": "act", "action": "confirm_and_execute", "speak": True},
            "answer": {"move": "answer", "action": "direct_help", "speak": True},
        }
        return mapping.get(priority, mapping["answer"]) | {"goal": goal.get("goal")}

"""Interruption handler — barge-in / stop / redirect."""
from __future__ import annotations

import re
from typing import Any


class InterruptionHandler:
    _STOP = re.compile(
        r"(?i)^\s*(stop|cancel|ruk|band karo|chup|bas|quiet|enough)(?:\s|$)"
    )
    _REDIRECT = re.compile(r"(?i)\b(actually|wait|no\s+wait|instead|baat\s+sun)\b")

    def assess(self, message: str) -> dict[str, Any]:
        text = (message or "").strip()
        if self._STOP.search(text):
            return {"interrupted": True, "kind": "stop", "should_stop_speech": True}
        if self._REDIRECT.search(text):
            return {"interrupted": True, "kind": "redirect", "should_stop_speech": True}
        return {"interrupted": False, "kind": "none", "should_stop_speech": False}

"""Question generator — one natural question when useful."""
from __future__ import annotations

from typing import Any


class QuestionGenerator:
    def generate(
        self,
        *,
        human: dict[str, Any] | None = None,
        emotion: dict[str, Any] | None = None,
        locale: str = "en",
    ) -> str | None:
        human = human or {}
        emotion = emotion or {}
        if human.get("natural_ask"):
            return str(human["natural_ask"])
        if emotion.get("need") == "listen_first":
            return (
                "Kya hua tha?"
                if locale == "hi"
                else "What felt hardest about it?"
            )
        return None

"""OM conversational flow — dynamic topic + continuity (no canned follow-ups)."""
from __future__ import annotations

import re
from collections import Counter
from typing import Any


_STOP = {
    "the", "a", "an", "and", "or", "to", "of", "in", "on", "for", "is", "are", "was",
    "i", "you", "we", "me", "my", "it", "this", "that", "with", "from", "be", "do",
    "hai", "hain", "kya", "ki", "ka", "ke", "se", "mein", "main", "nahi", "nahin",
    "please", "just", "like", "can", "will", "would", "could", "should",
}


class ConversationalFlow:
    """Tracks live topic from tokens + history; never injects spoken canned Qs."""

    def __init__(self) -> None:
        self.topic_memory: dict[str, str] = {}
        self._token_memory: dict[str, Counter[str]] = {}
        self._seed_topics: dict[str, tuple[str, ...]] = {
            "model_pipeline": ("model", "llm", "training", "checkpoint", "weights", "dataset", "inference"),
            "voice_system": ("voice", "tts", "speech", "microphone", "audio", "listen", "aman"),
            "avatar_system": ("avatar", "3d", "animation", "face", "lip", "presence"),
            "memory_system": ("memory", "remember", "preference", "history", "context"),
            "om_project": ("om", "companion", "jarvis", "operating"),
            "debugging": ("bug", "error", "exception", "failed", "crash", "issue"),
            "planning": ("plan", "roadmap", "architecture", "design", "build"),
        }

    def _tokens(self, text: str) -> list[str]:
        raw = re.findall(r"[a-zA-Z\u0900-\u097F]{3,}", (text or "").lower())
        return [t for t in raw if t not in _STOP]

    def infer_topic(self, text: str, *, session_id: str = "") -> str:
        blob = (text or "").lower()
        scores: dict[str, float] = {}
        for topic, keywords in self._seed_topics.items():
            score = float(sum(1 for w in keywords if w in blob))
            if score:
                scores[topic] = score

        # Dynamic: boost session-frequent tokens as a soft topic label
        toks = self._tokens(text)
        if session_id and session_id in self._token_memory:
            prior = self._token_memory[session_id]
            for t in toks:
                if prior.get(t, 0) >= 2:
                    scores[t] = scores.get(t, 0) + 0.5 + prior[t] * 0.1

        if not scores:
            # Reference utterances keep prior topic
            if session_id and self.topic_memory.get(session_id) and re.search(
                r"\b(continue|that|this|it|wahi|usko|pehle)\b", blob
            ):
                return self.topic_memory[session_id]
            return "general"
        return max(scores, key=scores.get)

    def update_context(self, session_id: str, text: str) -> str:
        topic = self.infer_topic(text, session_id=session_id)
        if session_id:
            self.topic_memory[session_id] = topic
            bag = self._token_memory.setdefault(session_id, Counter())
            bag.update(self._tokens(text))
            # Cap bag size
            if len(bag) > 80:
                for k, _ in bag.most_common()[60:]:
                    del bag[k]
        return topic

    def current_topic(self, session_id: str) -> str:
        return self.topic_memory.get(session_id, "general")

    def continuity_hint(
        self,
        user_text: str,
        *,
        session_id: str = "",
        history: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        """Metadata for the brain — not a spoken append."""
        topic = self.current_topic(session_id) if session_id else self.infer_topic(user_text)
        low = (user_text or "").lower()
        is_ref = bool(re.search(r"\b(continue|that|this|it|wahi|usko|pehle|keep going)\b", low))
        prior = ""
        if history:
            for h in reversed(history):
                if h.get("role") == "user" and str(h.get("content") or "").strip():
                    prior = str(h["content"]).strip()[:160]
                    break
        hint = ""
        if is_ref and (topic != "general" or prior):
            hint = f"Continuing prior thread ({topic}): {prior or topic}"
        return {
            "topic": topic,
            "is_reference": is_ref,
            "prior_user": prior,
            "hint": hint,
        }

    def should_follow_up(
        self,
        answer: str,
        user_text: str,
        context: dict[str, Any] | None = None,
    ) -> bool:
        """Never auto-append spoken follow-ups."""
        del answer, user_text, context
        return False

    def follow_up(
        self,
        user_text: str,
        answer: str,
        *,
        topic: str = "",
        session_id: str = "",
    ) -> str | None:
        del user_text, answer, topic, session_id
        return None

    def merge_follow_up(self, answer: str, follow: str | None) -> str:
        del follow
        return (answer or "").strip()

    def already_asks(self, answer: str) -> bool:
        text = (answer or "").strip()

"""Sliding conversational context window."""
from __future__ import annotations

from typing import Any


class ContextWindow:
    def __init__(self, max_chars: int = 6000) -> None:
        self.max_chars = max_chars
        self.topic: str = ""
        self.goals: list[str] = []
        self.open_questions: list[str] = []

    def set_topic(self, topic: str) -> None:
        self.topic = (topic or "").strip()[:200]

    def add_goal(self, goal: str) -> None:
        g = (goal or "").strip()
        if g and g not in self.goals:
            self.goals.append(g)
            self.goals = self.goals[-8:]

    def add_question(self, q: str) -> None:
        q = (q or "").strip()
        if q and q not in self.open_questions:
            self.open_questions.append(q)
            self.open_questions = self.open_questions[-6:]

    def blob(self, history: list[dict[str, Any]]) -> str:
        parts = []
        if self.topic:
            parts.append(f"Current topic: {self.topic}")
        if self.goals:
            parts.append("Goals: " + "; ".join(self.goals[-3:]))
        if self.open_questions:
            parts.append("Open: " + "; ".join(self.open_questions[-2:]))
        for h in history[-10:]:
            parts.append(f"{h.get('role')}: {str(h.get('text') or '')[:400]}")
        out = "\n".join(parts)
        return out[: self.max_chars]

    def to_dict(self) -> dict[str, Any]:
        return {
            "topic": self.topic,
            "goals": list(self.goals),
            "open_questions": list(self.open_questions),
        }

"""Full conversation loop tying presence + realtime + human layer."""
from __future__ import annotations

from typing import Any, Callable

from .realtime_conversation import RealtimeConversation


class ConversationLoop:
    def __init__(self) -> None:
        self.realtime = RealtimeConversation()
        self._presence = None
        self._human = None

    def bind(
        self,
        *,
        stop_speech: Callable[[], None] | None = None,
        presence=None,
        human_pipeline=None,
    ) -> None:
        self.realtime.bind_stop(stop_speech)
        self._presence = presence
        self._human = human_pipeline

    def partial(self, text: str, *, history: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        if self._presence is not None:
            try:
                self._presence.listening()
            except Exception:
                pass
        return self.realtime.on_partial(text, history=history)

    def final_turn(
        self,
        text: str,
        *,
        history: list[dict[str, Any]] | None = None,
        generate: Callable[..., str] | None = None,
        profile: dict[str, Any] | None = None,
        memory_blob: str = "",
        locale: str = "en",
    ) -> dict[str, Any]:
        rt = self.realtime.on_final(text, history=history)
        if rt.get("interrupted"):
            if self._presence is not None:
                try:
                    self._presence.interrupt()
                except Exception:
                    pass
            return {**rt, "answer": "", "handled": True}

        if self._presence is not None:
            try:
                self._presence.thinking()
            except Exception:
                pass

        human_out: dict[str, Any] = {}
        if self._human is not None:
            try:
                human_out = self._human.run(
                    text,
                    history=history,
                    memory_blob=memory_blob,
                    profile=profile,
                    locale=locale,
                    generate=generate,
                )
            except Exception as exc:
                human_out = {"error": str(exc)}

        if self._presence is not None:
            try:
                self._presence.responding()
                self.realtime.on_speaking(True)
            except Exception:
                pass

        answer = str(human_out.get("answer") or human_out.get("spoken") or "")
        return {
            **rt,
            "human": human_out,
            "answer": answer,
            "spoken": answer,
            "handled": True,
            "presence_phase": "responding",
        }

    def after_speech(self) -> dict[str, Any]:
        self.realtime.on_speaking(False)
        if self._presence is not None:
            try:
                return self._presence.waiting()
            except Exception:
                pass
        return {"phase": "waiting"}

"""Predict intent from partial speech — never wait for perfection."""
from __future__ import annotations

import re
from typing import Any


class TurnPrediction:
    def predict(self, partial: str, *, history: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        low = (partial or "").lower().strip()
        hist = history or []
        intent = "continue"
        confidence = 0.4
        if re.search(r"(?i)\b(open|launch|start|close|kill)\b", low):
            intent, confidence = "action", 0.7
        elif re.search(r"(?i)\b(what|why|how|kya|kaise)\b", low) or "?" in low:
            intent, confidence = "question", 0.65
        elif re.search(r"(?i)\b(tired|stress|difficult|exhausted)\b", low):
            intent, confidence = "emotion_share", 0.7
        elif re.search(r"(?i)\b(remember|prefer|my name)\b", low):
            intent, confidence = "memory", 0.75
        elif re.search(r"(?:\.\.\.|…|\bbut\s*)$", low):
            intent, confidence = "partial_story", 0.8
        elif hist and len(low.split()) <= 4:
            intent, confidence = "followup", 0.55
        return {
            "predicted_intent": intent,
            "confidence": confidence,
            "can_prefetch": confidence >= 0.7 and intent in {"action", "question"},
        }

"""Streaming / partial transcript context."""
from __future__ import annotations

from typing import Any


class StreamingContext:
    def __init__(self) -> None:
        self.partial = ""
        self.final = ""
        self.partial_count = 0

    def on_partial(self, text: str) -> dict[str, Any]:
        self.partial = (text or "").strip()
        self.partial_count += 1
        return {
            "partial": self.partial,
            "ready_enough": len(self.partial.split()) >= 4,
            "count": self.partial_count,
        }

    def on_final(self, text: str) -> dict[str, Any]:
        self.final = (text or "").strip()
        self.partial = ""
        return {"final": self.final, "partial_count": self.partial_count}

