"""Continuous turn tracking with overlap / barge-in support."""
from __future__ import annotations

import time
import uuid
from dataclasses import dataclass, field
from typing import Any


@dataclass
class Turn:
    turn_id: str
    role: str
    text: str
    ts: float = field(default_factory=time.time)
    interrupted: bool = False
    topic: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "turn_id": self.turn_id,
            "role": self.role,
            "text": self.text,
            "ts": self.ts,
            "interrupted": self.interrupted,
            "topic": self.topic,
        }


class TurnManager:
    def __init__(self, max_turns: int = 80) -> None:
        self.turns: list[Turn] = []
        self.max_turns = max_turns
        self.active_assistant_id: str | None = None

    def begin_user(self, text: str, *, topic: str = "") -> Turn:
        t = Turn(str(uuid.uuid4()), "user", text, topic=topic)
        self.turns.append(t)
        self._trim()
        return t

    def begin_assistant(self, text: str, *, topic: str = "") -> Turn:
        t = Turn(str(uuid.uuid4()), "assistant", text, topic=topic)
        self.active_assistant_id = t.turn_id
        self.turns.append(t)
        self._trim()
        return t

    def mark_interrupted(self) -> Turn | None:
        if not self.active_assistant_id:
            return None
        for t in reversed(self.turns):
            if t.turn_id == self.active_assistant_id:
                t.interrupted = True
                self.active_assistant_id = None
                return t
        return None

    def history(self, limit: int = 20) -> list[dict[str, Any]]:
        return [t.to_dict() for t in self.turns[-limit:]]

    def _trim(self) -> None:
        if len(self.turns) > self.max_turns:
            self.turns = self.turns[-self.max_turns :]

"""Handle barge-in and mid-speech redirects."""
from __future__ import annotations

import re
from typing import Any


class InterruptionManager:
    REDIRECT = re.compile(
        r"(?i)\b(no[, ]+|wait|stop|actually|instead|first|pehle|रुको|नहीं)\b"
    )

    def analyze(self, text: str, *, speaking: bool = False) -> dict[str, Any]:
        low = (text or "").strip()
        redirected = bool(self.REDIRECT.search(low))
        barge = speaking and (redirected or len(low.split()) >= 2)
        return {
            "barge_in": barge,
            "redirect": redirected,
            "should_stop_speech": barge,
            "priority": "high" if barge else "normal",
            "ack": (
                "Understood. I will switch focus."
                if redirected
                else ("I'm listening." if barge else "")
            ),
        }

"""Human-like response timing / pause hints."""
from __future__ import annotations

from typing import Any


class ResponseTiming:
    def plan(self, *, presence_mode: str = "attentive", text_len: int = 0) -> dict[str, Any]:
        think_ms = 280
        if presence_mode in {"thinking", "remembering"}:
            think_ms = 650
        elif presence_mode in {"concerned", "confused"}:
            think_ms = 480
        elif presence_mode == "excited":
            think_ms = 180
        speak_gap_ms = 120 if text_len < 80 else 220
        return {
            "pre_think_ms": think_ms,
            "speak_gap_ms": speak_gap_ms,
            "allow_barge_in": True,
            "natural_pause": True,
        }

"""Realtime interruption — barge-in stops TTS immediately."""
from __future__ import annotations

import re
from typing import Any, Callable


class RealtimeInterruptionHandler:
    _STOP = re.compile(
        r"(?i)^\s*(stop|cancel|ruk|band karo|chup|bas|quiet|enough)(?:\s|$)"
    )
    _BARGE = re.compile(r"(?i)\b(wait|actually|no wait|sun|ruk)\b")

    def __init__(self) -> None:
        self._stop_fn: Callable[[], None] | None = None
        self.speaking = False

    def bind(self, stop_fn: Callable[[], None] | None) -> None:
        self._stop_fn = stop_fn

    def set_speaking(self, speaking: bool) -> None:
        self.speaking = speaking

    def handle(self, text: str) -> dict[str, Any]:
        t = (text or "").strip()
        if self._STOP.search(t) or (self.speaking and self._BARGE.search(t)):
            if self._stop_fn:
                try:
                    self._stop_fn()
                except Exception:
                    pass
            self.speaking = False
            return {
                "interrupted": True,
                "should_stop_speech": True,
                "continue_conversation": True,
            }
        return {"interrupted": False, "should_stop_speech": False, "continue_conversation": True}

"""Natural pause detection — when user likely finished speaking."""
from __future__ import annotations

import time
from typing import Any


class NaturalPause:
    def __init__(self, silence_ms: float = 650) -> None:
        self.silence_ms = silence_ms
        self._last_audio_ms = 0.0

    def on_audio(self) -> None:
        self._last_audio_ms = time.time() * 1000

    def ready_to_commit(self, *, has_partial: bool) -> dict[str, Any]:
        if not has_partial:
            return {"commit": False, "reason": "no_speech"}
        gap = time.time() * 1000 - self._last_audio_ms if self._last_audio_ms else 0
        if gap >= self.silence_ms:
            return {"commit": True, "silence_ms": gap, "reason": "natural_pause"}
        return {"commit": False, "silence_ms": gap, "reason": "still_speaking"}

"""Realtime conversation orchestrator (STEP 65)."""
from __future__ import annotations

from typing import Any, Callable

from .interruption_handler import RealtimeInterruptionHandler
from .natural_pause import NaturalPause
from .streaming_context import StreamingContext
from .turn_prediction import TurnPrediction


class RealtimeConversation:
    def __init__(self) -> None:
        self.stream = StreamingContext()
        self.predict = TurnPrediction()
        self.pause = NaturalPause()
        self.interrupt = RealtimeInterruptionHandler()

    def bind_stop(self, fn: Callable[[], None] | None) -> None:
        self.interrupt.bind(fn)

    def on_partial(self, text: str, *, history: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        self.pause.on_audio()
        stream = self.stream.on_partial(text)
        pred = self.predict.predict(text, history=history)
        return {**stream, **pred, "mode": "listening_continuous"}

    def on_final(self, text: str, *, history: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        interrupt = self.interrupt.handle(text)
        if interrupt.get("interrupted"):
            return {**interrupt, "final": text, "mode": "interrupted"}
        fin = self.stream.on_final(text)
        pred = self.predict.predict(text, history=history)
        return {**fin, **pred, **interrupt, "mode": "turn_ready"}

    def on_speaking(self, speaking: bool) -> None:
        self.interrupt.set_speaking(speaking)

