"""Detect preferred language from onboarding profile / free text."""
from __future__ import annotations

import re
from typing import Any


_DEV = re.compile(r"[\u0900-\u097F]")
_HING = re.compile(
    r"(?i)\b(hai|hain|kya|nahi|theek|bhai|yaar|kal|aaj|mujhe|karna|hinglish)\b"
)


class LanguageDetector:
    def detect(self, profile: dict[str, Any] | None = None, text: str = "") -> str:
        raw = str((profile or {}).get("language") or "").strip().lower()
        if raw in {"en", "english"}:
            return "en"
        if raw in {"hi", "hindi"}:
            return "hi"
        if raw in {"hi-en", "hinglish", "hi_en"}:
            return "hi-en"
        if raw and raw != "auto":
            return raw

        blob = " ".join(
            str((profile or {}).get(k) or "")
            for k in ("purpose", "style", "notes", "display_name")
        )
        blob = f"{blob} {text}".strip()
        if _DEV.search(blob) and re.search(r"[A-Za-z]", blob):
            return "hi-en"
        if _DEV.search(blob):
            return "hi"
        if _HING.search(blob):
            return "hi-en"
        return "en"

"""Dialogue policy from semantic frame."""
from __future__ import annotations

from typing import Any


class DialoguePolicy:
    def decide(self, semantic: dict[str, Any]) -> dict[str, Any]:
        mode = semantic.get("conversation_mode") or "assist"
        intent = semantic.get("intent") or "chat"
        if mode == "social":
            return {
                "allow_brief_reply": True,
                "prefer_runtime_fast_path": True,
                "max_questions": 0,
                "policy": "social_first",
            }
        if mode == "clarify":
            return {
                "allow_brief_reply": False,
                "prefer_runtime_fast_path": False,
                "max_questions": 1,
                "policy": "ask_one_question",
            }
        if mode == "task":
            return {
                "allow_brief_reply": False,
                "prefer_runtime_fast_path": False,
                "max_questions": 1 if semantic.get("requires_clarification") else 0,
                "policy": "task_focused",
            }
        if intent == "followup" or mode == "continue":
            return {
                "allow_brief_reply": False,
                "prefer_runtime_fast_path": False,
                "max_questions": 0,
                "policy": "thread_continuity",
            }
        return {
            "allow_brief_reply": True,
            "prefer_runtime_fast_path": semantic.get("confidence", 0) > 0.85,
            "max_questions": 0,
            "policy": "balanced_assist",
        }

