        self._mood = "neutral"

    def update(self, emotion: str) -> dict[str, Any]:
        label = (emotion or "neutral").strip().lower() or "neutral"
        self._window.append(label)
        # Dominant non-neutral wins; else neutral
        counts: dict[str, int] = {}
