"""Topic tracker — what the user is working on across turns."""
from __future__ import annotations

import re
from typing import Any


_TOPICS: dict[str, tuple[str, ...]] = {
    "voice_engine": ("voice", "tts", "stt", "speech", "microphone", "aman", "wake"),
    "avatar": ("avatar", "3d", "lip", "face", "presence", "animation"),
    "memory": ("memory", "remember", "preference", "yaad"),
    "actions": ("open", "youtube", "volume", "file", "app", "browser"),
    "coding": ("code", "bug", "error", "python", "function", "debug"),
    "project_om": ("om", "companion", "jarvis", "operating brain"),
    "weather": ("weather", "mausam", "temperature"),
}


class TopicTracker:
    def __init__(self) -> None:
        self._topic = "general"
        self._history: list[str] = []

    @property
    def current(self) -> str:
        return self._topic

    def update(self, text: str, *, history: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        low = (text or "").lower()
        hit = "general"
        best = 0
        for name, keys in _TOPICS.items():
            score = sum(1 for k in keys if k in low)
            if score > best:
                best = score
                hit = name
        # Continuity: short/reference utterances keep prior topic
        if best == 0 and self._is_reference(low) and self._topic != "general":
            hit = self._topic
        elif best == 0 and history:
            prior = " ".join(str(h.get("content") or "") for h in history[-4:]).lower()
            for name, keys in _TOPICS.items():
                if any(k in prior for k in keys):
                    hit = name
                    break
        if hit != "general":
            self._topic = hit
            self._history.append(hit)
            self._history = self._history[-12:]
        return {"topic": self._topic, "changed": best > 0, "history": list(self._history)[-5:]}

    def _is_reference(self, low: str) -> bool:
        return bool(
            re.search(
                r"\b(continue|us[ei]|that|this|it|same|pehle|wahi|usko|uska|continue that|keep going)\b",
                low,
            )
        )

"""Context engine — builds rich turn context for the brain."""
from __future__ import annotations

from typing import Any


class ContextEngine:
    def build(
        self,
        message: str,
        *,
        history: list[dict[str, Any]] | None = None,
        topic: str = "general",
        memory_blob: str = "",
        emotion: dict[str, Any] | None = None,
        profile: dict[str, Any] | None = None,
        followup: dict[str, Any] | None = None,
        task: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        hist = history or []
        parts: list[str] = []
        name = str((profile or {}).get("name") or "").strip()
        if name:
            parts.append(f"User name: {name}. Address naturally (Sir/Ji when fitting).")
        if topic and topic != "general":
            parts.append(f"Active topic: {topic.replace('_', ' ')}.")
        if followup and followup.get("continuity_hint"):
            parts.append(str(followup["continuity_hint"]))
        if followup and followup.get("resolved_reference"):
            parts.append(f"Resolved reference: {followup['resolved_reference'][:200]}")
        if emotion:
            label = emotion.get("label") or emotion.get("emotion") or "neutral"
            if label and label != "neutral":
                parts.append(f"User emotion: {label}. Match tone with care.")
        if memory_blob:
            parts.append(f"Memory:\n{memory_blob[:1400]}")
        if task and task.get("summary"):
            parts.append(f"Task context: {task['summary'][:200]}")
        # Recent dialogue
        if hist:
            lines = []
            for h in hist[-6:]:
                role = str(h.get("role") or "?")
                content = str(h.get("content") or "").strip()[:180]
                if content:
                    lines.append(f"{role}: {content}")
            if lines:
                parts.append("Recent turns:\n" + "\n".join(lines))
        blob = "\n".join(parts).strip()
        return {
            "context_blob": blob[:3200],
            "topic": topic,
            "followup": followup or {},
            "emotion": emotion or {},
            "profile": profile or {},
            "message": message,
        }

