            answer=answer,

            score=score,

            success=evaluation.get(
                "approved",
                False
            ),

            category=self.detect_category(
                question
            )

        )




    def detect_category(
        self,
        question:str
    ):


        q = question.lower()


        if any(
            x in q
            for x in [
                "code",
                "build",
                "api",
                "software"
            ]
        ):

            return "engineering"



        if any(
            x in q
            for x in [
                "business",
                "finance",
                "report"
            ]
        ):

            return "business"



        return "general"

