"""Native microphone bridge for desktop companion (when WebView mic is blocked)."""
from __future__ import annotations

import logging
import threading
import time
from typing import Any, Callable

logger = logging.getLogger(__name__)


class NativeMicBridge:
    """Capture mic in Python and emit final transcripts to a callback."""

    def __init__(self) -> None:
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None
        self._on_text: Callable[[str], None] | None = None
        self._busy = False

    @property
    def running(self) -> bool:
        return self._thread is not None and self._thread.is_alive()

    def start(self, on_text: Callable[[str], None]) -> dict[str, Any]:
        if self.running:
            self._on_text = on_text
            return {"ok": True, "already": True}
        self._on_text = on_text
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, name="om-native-mic", daemon=True)
        self._thread.start()
        return {"ok": True, "backend": self._probe_backend()}

    def stop(self) -> dict[str, Any]:
        self._stop.set()
        return {"ok": True}

    def _probe_backend(self) -> str:
        try:
            import sounddevice  # noqa: F401

            from om_ai.core.voice_intelligence.speech_recognizer import SpeechRecognizer

            st = SpeechRecognizer(model_size="tiny").status()
            if st.get("ready"):
                return str(st.get("backend") or "whisper")
        except Exception:
            pass
        try:
            import speech_recognition  # noqa: F401

            return "speech_recognition"
        except Exception:
            return "none"

    def _loop(self) -> None:
        backend = self._probe_backend()
        if backend in {"faster_whisper", "whisper", "om_voice_stt"}:
            self._loop_whisper()
        elif backend == "speech_recognition":
            self._loop_speech_recognition()
        else:
            logger.warning(
                "Native mic: no STT backend. Install sounddevice+faster-whisper "
                "or speech_recognition, and allow Microphone for Terminal/Python."
            )
            # Idle until stop — UI may still use Chrome path
            while not self._stop.wait(1.0):
                pass

    def _loop_whisper(self) -> None:
        try:
            import sounddevice as sd
            import numpy as np
            from om_ai.core.voice_intelligence.speech_recognizer import SpeechRecognizer
        except Exception as exc:
            logger.warning("whisper mic loop unavailable: %s", exc)
            return

        rec = SpeechRecognizer(model_size="tiny", language=None)
        sr = 16000
        block = int(sr * 3.5)  # ~3.5s chunks
        while not self._stop.is_set():
            if self._busy:
                time.sleep(0.2)
                continue
            try:
                audio = sd.rec(block, samplerate=sr, channels=1, dtype="float32")
                sd.wait()
                flat = np.asarray(audio, dtype=np.float32).reshape(-1)
                rms = float(np.sqrt(np.mean(np.square(flat)))) if flat.size else 0.0
                if rms < 0.012:
                    continue
                out = rec.transcribe_array(flat, sample_rate=sr)
                text = str(out.get("text") or "").strip()
                if text and self._on_text:
                    self._on_text(text)
            except Exception as exc:
                logger.debug("native whisper chunk: %s", exc)
                time.sleep(0.5)

    def _loop_speech_recognition(self) -> None:
        try:
            import speech_recognition as sr
        except Exception as exc:
            logger.warning("speech_recognition unavailable: %s", exc)
            return

        recognizer = sr.Recognizer()
        mic = sr.Microphone()
        with mic as source:
            try:
                recognizer.adjust_for_ambient_noise(source, duration=0.6)
            except Exception:
                pass
        while not self._stop.is_set():
            if self._busy:
                time.sleep(0.2)
                continue
            try:
                with mic as source:
                    audio = recognizer.listen(source, timeout=3, phrase_time_limit=8)
                try:
                    text = recognizer.recognize_google(audio)
                except sr.UnknownValueError:
                    continue
                except sr.RequestError:
                    # Offline fallback
                    try:
                        text = recognizer.recognize_sphinx(audio)
                    except Exception:
                        continue
                text = str(text or "").strip()
                if text and self._on_text:
                    self._on_text(text)
            except Exception:
                time.sleep(0.3)

    def set_busy(self, busy: bool) -> None:
        self._busy = bool(busy)

"""Native OM Companion window via pywebview / Chrome app (real mic)."""
from __future__ import annotations

import json
import os
import signal
import subprocess
import sys
import threading
import time
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any, Callable
from urllib.parse import urlparse


def _ensure_pywebview() -> Any:
    try:
        import webview  # type: ignore

        return webview
    except ImportError as exc:
        raise SystemExit(
            "Desktop companion needs pywebview.\n"
            "  pip install 'pywebview>=5.0'\n"
            "  # or:  pip install -e '.[companion]'\n"
            f"({exc})"
        ) from exc


def _chrome_binary() -> str | None:
    candidates = [
        "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
        "/Applications/Chromium.app/Contents/MacOS/Chromium",
        "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
        "/Applications/Brave Browser.app/Contents/MacOS/Brave Browser",
    ]
    for p in candidates:
        if Path(p).is_file():
            return p
    # Linux / Windows fallbacks
    for name in ("google-chrome", "chromium", "chromium-browser", "msedge"):
        try:
            out = subprocess.check_output(["which", name], text=True).strip()
            if out:
                return out
        except Exception:
            pass
    return None


def _quit_companion_chrome(profile: Path) -> None:
    """Stop only Chrome instances using the companion profile (so prefs stick)."""
    marker = str(profile.resolve())
    try:
        out = subprocess.check_output(["ps", "ax", "-o", "pid=,command="], text=True)
    except Exception:
        return
    for line in out.splitlines():
        if marker not in line:
            continue
        if not any(x in line for x in ("Chrome", "Chromium", "Edge", "Brave")):
            continue
        try:
            pid = int(line.strip().split(None, 1)[0])
            os.kill(pid, signal.SIGTERM)
        except Exception:
            pass
    time.sleep(0.9)


def _api_base_from_url(url: str) -> str:
    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        return "http://127.0.0.1:8765"
    return f"{parsed.scheme}://{parsed.netloc}"


def _post_native_final(base_url: str, text: str) -> None:
    payload = json.dumps({"text": text}).encode("utf-8")
    req = urllib.request.Request(
        f"{base_url.rstrip('/')}/api/companion/native-final",
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        urllib.request.urlopen(req, timeout=8)
    except (urllib.error.URLError, TimeoutError, OSError):
        pass


_chrome_native_mic: Any = None


def _start_chrome_native_mic(url: str) -> dict[str, Any]:
    """Python mic backup when Chrome profile has blocked getUserMedia."""
    global _chrome_native_mic
    from om_ai.desktop.native_mic import NativeMicBridge

    base = _api_base_from_url(url)
    if _chrome_native_mic is None:
        _chrome_native_mic = NativeMicBridge()

    def _on_text(text: str) -> None:
        cleaned = str(text or "").strip()
        if cleaned:
            _post_native_final(base, cleaned)

    result = _chrome_native_mic.start(_on_text)
    backend = str(result.get("backend") or "unknown")
    print(f"  Native mic ears: {backend} (backup if Chrome blocks mic)")
    return result


def launch_chrome_app(
    url: str,
    *,
    width: int = 980,
    height: int = 720,
) -> bool:
    """Open companion as a Chrome/Edge app window (has working microphone)."""
    binary = _chrome_binary()
    if not binary:
        return False
    profile = Path("artifacts") / "companion" / "chrome_profile"
    profile.mkdir(parents=True, exist_ok=True)

    # Quit prior companion Chrome so Preferences patch is not overwritten.
    _quit_companion_chrome(profile)
    try:
        from om_ai.desktop.chrome_mic_prefs import ensure_chrome_mic_allowed

        parsed = urlparse(url)
        ports: list[int] = [8765, 8080, 8767]
        try:
            if parsed.port:
                ports.insert(0, int(parsed.port))
