THRESHOLDS = {
    "structure": 70.0,
    "clarity": 65.0,
    "security": 70.0,
    "task_fit": 65.0,
    "code_quality": 70.0,
}


def detect_weaknesses(eval_result: dict[str, Any]) -> list[dict[str, Any]]:
    scores = eval_result.get("scores") or {}
    weak: list[dict[str, Any]] = []
    for key, thr in THRESHOLDS.items():
        val = float(scores.get(key, 100.0))
        if val < thr:
            weak.append(
                {
                    "area": key,
                    "score": val,
                    "threshold": thr,
                    "hint": _hint(key),
                }
            )
    if float(eval_result.get("overall") or 0) < 70:
        weak.append(
            {
                "area": "overall",
                "score": float(eval_result.get("overall") or 0),
                "threshold": 70.0,
                "hint": "Improve completeness and directness of the answer",
            }
        )
    # dedupe by area
    seen: set[str] = set()
    out: list[dict[str, Any]] = []
    for w in weak:
        if w["area"] in seen:
            continue
        seen.add(w["area"])
        out.append(w)
    return out


def _hint(area: str) -> str:
    return {
        "structure": "Use clear sections: Understanding, Plan, Implementation, Validation",
        "clarity": "Write shorter clear sentences; avoid garbled fragments",
        "security": "Include validation, no secrets, safe auth patterns",
        "task_fit": "Address every part of the user ask explicitly",
        "code_quality": "Include runnable code blocks and tests",
    }.get(area, "Improve this dimension")

"""
OM Training Example Generator

Converts successful OM experiences
into SFT training examples.
"""


from .example import TrainingExample





class TrainingExampleGenerator:



    def generate(

        self,

        question: str,

        answer: str,

        evaluation: dict

    ) -> TrainingExample:



        return TrainingExample(

            instruction=question,

            response=answer,

            category=self.detect_category(
                question
            ),

            quality_score=float(

                evaluation.get(
                    "score",
                    0.0
                )

            ),

            metadata={

                "approved":

                    evaluation.get(
                        "approved",
                        False
                    )

            }

        )



    def detect_category(

        self,

        question: str

    ) -> str:



        q = question.lower()



        if any(

            word in q

            for word in [

                "code",

                "api",

                "software",

                "application",

                "build",

                "develop"

            ]

        ):

            return "engineering"



        if any(

            word in q

            for word in [

                "finance",

                "business",

                "report",

                "sales"

            ]

        ):

            return "business"



        if any(

            word in q

            for word in [

                "database",

                "sql",

                "mysql",

                "schema"

            ]

        ):

            return "database"



        return "general"

"""
OM Knowledge Improvement Engine
"""


from .generator import TrainingExampleGenerator  # pyright: ignore[reportMissingImports]

from .dataset_writer import DatasetWriter





class KnowledgeImprovementEngine:



    def __init__(self):


        self.generator = TrainingExampleGenerator()

        self.writer = DatasetWriter()




    def improve(

        self,

        question,

        answer,

        evaluation

    ):


        if not evaluation.get(
            "approved",
            False
        ):

            return {


                "stored":
                    False,


                "reason":
                    "low quality answer"

            }



        example = self.generator.generate(

            question,

            answer,

            evaluation

        )


        self.writer.append(
            example
        )


        return {


            "stored":

                True,


            "dataset":

                str(

                    self.writer.path

                ),


            "category":

                example.category

        }

