"""Model lifecycle — registry, experiment, deploy candidacy."""
from __future__ import annotations

import json
import time
from pathlib import Path
from typing import Any

from services._common import ServiceHealth, ok


class ModelLifecycleService:
    def __init__(self, path: str = "artifacts/enterprise/model_lifecycle.json") -> None:
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        if not self.path.is_file():
            self.path.write_text(
                json.dumps(
                    {
                        "models": {
                            "om-1.0": {"state": "production", "checkpoint": "local"},
                            "om-1b": {"state": "config_ready"},
                            "om-7b": {"state": "config_ready"},
                            "om-70b": {"state": "config_ready"},
                        },
                        "experiments": [],
                        "deployments": [],
                    },
                    indent=2,
                )
                + "\n",
                encoding="utf-8",
            )

    def health(self) -> dict[str, Any]:
        return ServiceHealth("model-lifecycle").to_dict()

    def _load(self) -> dict[str, Any]:
        return json.loads(self.path.read_text(encoding="utf-8"))

    def _save(self, data: dict[str, Any]) -> None:
        self.path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")

    def register_experiment(self, name: str, metrics: dict[str, Any]) -> dict[str, Any]:
        data = self._load()
        exp = {"name": name, "metrics": metrics, "ts": time.time()}
        data.setdefault("experiments", []).append(exp)
        self._save(data)
        return ok(exp)

    def promote(self, model_id: str, state: str = "candidate") -> dict[str, Any]:
        data = self._load()
        models = data.setdefault("models", {})
        models[model_id] = {**(models.get(model_id) or {}), "state": state, "updated_at": time.time()}
        data.setdefault("deployments", []).append({"model_id": model_id, "state": state, "ts": time.time()})
        self._save(data)
        return ok(models[model_id])

    def status(self) -> dict[str, Any]:
        return ok(self._load())

"""Audit service — append-only enterprise audit trail."""
from __future__ import annotations

import json
import time
from pathlib import Path
from typing import Any

from services._common import ServiceHealth, ok


class AuditService:
    def __init__(self, path: str = "artifacts/enterprise/audit.jsonl") -> None:
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)

    def health(self) -> dict[str, Any]:
        return ServiceHealth("audit-service").to_dict()

    def log(self, action: str, *, actor: str = "", tenant_id: str = "default", meta: dict | None = None) -> dict[str, Any]:
        row = {
            "ts": time.time(),
            "action": action,
            "actor": actor,
            "tenant_id": tenant_id,
            "meta": meta or {},
        }
        with self.path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
        # also mirror to om security audit if available
        try:
            from om_ai.security.audit import AuditLog

            AuditLog().record(
                tenant_id=tenant_id,
                actor=actor or "system",
                action=action,
                resource="api-gateway",
                detail=meta or {},
            )
        except Exception:
            pass
        return ok(row)

    def recent(self, limit: int = 50) -> dict[str, Any]:
        rows: list[dict[str, Any]] = []
        if self.path.is_file():
            for line in self.path.read_text(encoding="utf-8").splitlines():
                if line.strip():
                    rows.append(json.loads(line))
        return ok(rows[-limit:])

"""Billing / usage metering (local ledger; provider optional)."""
from __future__ import annotations

import json
import time
from pathlib import Path
from typing import Any

from services._common import ServiceHealth, ok


class BillingService:
    def __init__(self, db: str = "artifacts/enterprise/billing.jsonl") -> None:
        self.path = Path(db)
        self.path.parent.mkdir(parents=True, exist_ok=True)

    def health(self) -> dict[str, Any]:
        return ServiceHealth("billing-service", detail={"mode": "local_ledger"}).to_dict()

    def record_usage(self, *, tenant_id: str, tokens_in: int, tokens_out: int, model: str) -> dict[str, Any]:
        # simple cost model: $0.000001 per token placeholder
        cost = (tokens_in + tokens_out) * 0.000001
        row = {
            "ts": time.time(),
            "tenant_id": tenant_id,
            "model": model,
            "tokens_in": tokens_in,
            "tokens_out": tokens_out,
            "cost_usd": round(cost, 8),
        }
        with self.path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(row) + "\n")
        return ok(row)

    def summary(self, tenant_id: str = "default") -> dict[str, Any]:
        total = 0.0
        n = 0
        if self.path.is_file():
            for line in self.path.read_text(encoding="utf-8").splitlines():
                if not line.strip():
                    continue
                row = json.loads(line)
                if row.get("tenant_id") == tenant_id:
                    total += float(row.get("cost_usd") or 0)
                    n += 1
        return ok({"tenant_id": tenant_id, "events": n, "cost_usd": round(total, 6)})

"""User management service."""
from __future__ import annotations

import json
import time
import uuid
from pathlib import Path
from typing import Any

from services._common import ServiceHealth, ok


class UserService:
    def __init__(self, db: str = "artifacts/enterprise/users.json") -> None:
        self.path = Path(db)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        if not self.path.is_file():
            self.path.write_text("{}", encoding="utf-8")

    def health(self) -> dict[str, Any]:
        return ServiceHealth("user-service").to_dict()

